TRANSCRIPT_REMOVAL_WORDS = {
    "um",
    "uh",
    "like",
    "you know",
    "so",
    "basically",
    "literally",
    "okay",
    "right",
}


def _safe_numeric_value(segment, keys, fallback=0):
    for key in keys:
        value = segment.get(key)
        if value is None:
            continue
        try:
            number = float(value)
        except (ValueError, TypeError):
            continue
        return max(0, int(round(number)))
    return fallback


def _sanitize_transcript_segments(raw_segments: list[dict]) -> list[dict]:
    cleaned_segments: list[dict] = []
    if not isinstance(raw_segments, list):
        return cleaned_segments
    for entry in raw_segments:
        if not isinstance(entry, dict):
            continue
        text = str(entry.get("text") or "").strip()
        if not text:
            continue
        text = re.sub(r"\s+", " ", text)
        for word in TRANSCRIPT_REMOVAL_WORDS:
            text = re.sub(rf"\b{re.escape(word)}\b", "", text, flags=re.IGNORECASE)
        text = text.strip()
        if not text:
            continue
        start = _safe_numeric_value(entry, ["start_seconds", "start", "start_time"], fallback=0)
        end = _safe_numeric_value(entry, ["end_seconds", "end", "end_time"], fallback=start)
        if end < start:
            end = start
        cleaned_segments.append({"text": text, "start_seconds": start, "end_seconds": end})
    return cleaned_segments


def _probe_video_duration(path: str) -> float:
    try:
        result = subprocess.run(
            [
                "ffprobe",
                "-v",
                "error",
                "-show_entries",
                "format=duration",
                "-of",
                "default=noprint_wrappers=1:nokey=1",
                path,
            ],
            capture_output=True,
            text=True,
            check=True,
        )
        return float(result.stdout.strip())
    except Exception:  # pragma: no cover
        return 0.0


def _probe_video_duration_from_storage(relative_path: str) -> float:
    """Probe duration for a `default_storage`-relative path.

    Local FileSystemStorage exposes a real filesystem path via `.path()`, so
    ffprobe can run against it directly. Remote backends (S3/Supabase) raise
    NotImplementedError from `.path()` — for those, pull the bytes into a
    temp file first since ffprobe needs a real file to open.
    """
    try:
        local_path = default_storage.path(relative_path)
    except NotImplementedError:
        local_path = None
    if local_path:
        return _probe_video_duration(local_path)
    try:
        with default_storage.open(relative_path, "rb") as remote_file:
            suffix = os.path.splitext(relative_path)[1] or ".mp4"
            with tempfile.NamedTemporaryFile(suffix=suffix) as tmp:
                tmp.write(remote_file.read())
                tmp.flush()
                return _probe_video_duration(tmp.name)
    except Exception:  # pragma: no cover
        return 0.0


def _collect_profile_broadcast_stats(profile_ids: list[str]) -> dict[str, dict]:
    stats: dict[str, dict] = {}
    for pid in profile_ids:
        stats[pid] = {"broadcast_count": 0, "last_broadcast_at": None, "last_broadcast_title": None}
    if not profile_ids:
        return stats

    items = BroadcastItem.objects.filter(
        source_type=BroadcastSourceType.EDUCATION_COURSE,
        is_deleted=False,
        metadata__education_profile_id__in=profile_ids,
    ).order_by("-broadcasted_at")
    for item in items:
        metadata = item.metadata or {}
        pid = str(metadata.get("education_profile_id") or "")
        if not pid or pid not in stats:
            continue
        entry = stats[pid]
        entry["broadcast_count"] += 1
        if not entry["last_broadcast_at"] or item.broadcasted_at and item.broadcasted_at > entry["last_broadcast_at"]:
            entry["last_broadcast_at"] = item.broadcasted_at
            entry["last_broadcast_title"] = str(metadata.get("title") or metadata.get("summary") or "")
    return stats


def _serialize_education_profiles(user):
    qs = (
        EducationProfile.objects.filter(user=user)
        .prefetch_related(
            "courses",
            "modules",
            "roles__assignments__user",
        )
        .order_by("-is_default", "-updated_at")
    )
    serializer = EducationProfileSerializer(qs, many=True)
    payload = serializer.data
    profile_ids = [str(entry.get("id")) for entry in payload if entry.get("id")]
    stats = _collect_profile_broadcast_stats(profile_ids)
    for entry in payload:
        pid = str(entry.get("id"))
        entry["analytics"] = stats.get(pid, {"broadcast_count": 0, "last_broadcast_at": None, "last_broadcast_title": None})
    return payload


def _build_education_summary(serialized_profile: dict[str, Any]) -> dict[str, Any]:
    if not serialized_profile:
        return {}
    return {
        "profile_name": serialized_profile.get("name"),
        "description": serialized_profile.get("description"),
        "profile_type": serialized_profile.get("profile_type"),
        "course_count": len(serialized_profile.get("courses", [])),
        "module_count": len(serialized_profile.get("modules", [])),
        "role_count": len(serialized_profile.get("roles", [])),
        "courses": serialized_profile.get("courses", []),
        "modules": serialized_profile.get("modules", []),
        "roles": serialized_profile.get("roles", []),
        "updated_at": serialized_profile.get("updated_at"),
        "created_at": serialized_profile.get("created_at"),
    }


def _education_manage_roles() -> set[str]:
    return {
        EducationInstitutionMembershipRole.OWNER,
        EducationInstitutionMembershipRole.MANAGER,
        EducationInstitutionMembershipRole.ADMINISTRATOR,
    }


def _education_institution_qs_for_user(user: User):
    from apps.partners.services import partner_ids_user_can_access

    query = Q(owner=user) | Q(memberships__user=user)
    partner_ids = partner_ids_user_can_access(user)
    if partner_ids:
        query |= Q(partner_id__in=partner_ids)
    return (
        EducationInstitution.objects.filter(query)
        .prefetch_related("memberships__user")
        .distinct()
        .order_by("-updated_at")
    )


def _get_education_institution_or_404(user: User, institution_id: str) -> EducationInstitution:
    return get_object_or_404(
        _education_institution_qs_for_user(user),
        id=institution_id,
    )


def _get_public_education_institution_or_404(institution_id: str) -> EducationInstitution:
    return get_object_or_404(
        EducationInstitution.objects.prefetch_related("memberships__user"),
        id=institution_id,
        is_active=True,
    )


def _get_institution_membership(user: User, institution: EducationInstitution) -> EducationInstitutionMembership | None:
    if institution.owner_id == user.id:
        prefetched = getattr(institution, "_prefetched_objects_cache", {})
        rows = prefetched.get("memberships")
        membership = next((row for row in rows if row.user_id == user.id), None) if rows is not None else institution.memberships.filter(user=user).first()
        if membership:
            return membership
        return SimpleNamespace(
            id=None,
            user=user,
            user_id=user.id,
            institution=institution,
            institution_id=institution.id,
            role=EducationInstitutionMembershipRole.OWNER,
            status=EducationInstitutionMembershipStatus.ACTIVE,
        )
    prefetched = getattr(institution, "_prefetched_objects_cache", {})
    rows = prefetched.get("memberships")
    if rows is not None:
        return next((row for row in rows if row.user_id == user.id), None)
    return institution.memberships.filter(user=user).first()


def _require_manage_institution_membership(user: User, institution: EducationInstitution) -> EducationInstitutionMembership | None:
    if institution.owner_id == user.id:
        return _get_institution_membership(user, institution)
    membership = _get_institution_membership(user, institution)
    if membership and membership.status == EducationInstitutionMembershipStatus.ACTIVE and membership.role in _education_manage_roles():
        return membership
    if institution.partner_id:
        from apps.partners.services import partner_user_can_manage
        if partner_user_can_manage(institution.partner, user):
            # Always synthesize a manager-role stand-in here rather than
            # ever returning a real-but-insufficient membership row (e.g. a
            # STUDENT-role membership the same user happens to also hold) -
            # this mirrors _get_institution_membership's synthesis for the
            # owner case, so every downstream call site that reads
            # membership.role/.id/.status off the return value keeps seeing
            # a manage-capable role rather than the unrelated lower role.
            return SimpleNamespace(
                id=None,
                user=user,
                user_id=user.id,
                institution=institution,
                institution_id=institution.id,
                role=EducationInstitutionMembershipRole.MANAGER,
                status=EducationInstitutionMembershipStatus.ACTIVE,
            )
    if not membership or membership.status != EducationInstitutionMembershipStatus.ACTIVE:
        raise PermissionDenied("You do not belong to this institution.")
    raise PermissionDenied("You do not have permission to manage this institution.")


