def _first_payload_value(payload, *keys: str):
    if not hasattr(payload, "get"):
        return None
    for key in keys:
        value = payload.get(key)
        if value not in (None, ""):
            return value
    return None


def _nested_payload_value(payload, *keys: str):
    value = _first_payload_value(payload, *keys)
    if value not in (None, ""):
        return value
    if not hasattr(payload, "get"):
        return None
    for container_key in ("target", "entity", "source", "item", "record", "metadata"):
        container = payload.get(container_key)
        if isinstance(container, dict):
            value = _first_payload_value(container, *keys)
            if value not in (None, ""):
                return value
    return None


def _coerce_payload_id(value, *keys: str):
    if isinstance(value, dict):
        return _first_payload_value(value, *keys, "id", "uuid", "pk")
    return value


def _education_price_amount_from_payload(payload):
    raw = _nested_payload_value(payload, "price_amount", "priceAmount", "amount", "amount_kisc", "amountKisc")
    if raw in (None, ""):
        raw = _nested_payload_value(payload, "price", "pricing", "cost", "fee")
    if isinstance(raw, dict):
        raw = _first_payload_value(
            raw,
            "price_amount",
            "priceAmount",
            "amount",
            "value",
            "kisc",
            "amount_kisc",
            "amountKisc",
            "displayAmount",
            "display_amount",
        )
    if isinstance(raw, str) and raw.strip().lower() in {"free", "none", "null", "n/a", "na", "no charge", "[object object]"}:
        return None
    return raw


def _education_broadcast_kind_from_targets(
    value: object,
    *,
    program=None,
    course=None,
    lesson=None,
    class_session=None,
    event=None,
) -> str:
    if value not in (None, ""):
        return _normalize_education_broadcast_kind(value)
    if event:
        if event.event_type == EducationInstitutionEventType.TRAINING_SESSION:
            return EducationBroadcastKind.TRAINING_SESSION
        return EducationBroadcastKind.EVENT
    if class_session:
        return EducationBroadcastKind.CLASS_SESSION
    if lesson:
        return EducationBroadcastKind.LESSON
    if course:
        return EducationBroadcastKind.COURSE
    if program:
        return EducationBroadcastKind.PROGRAM
    return EducationBroadcastKind.INSTITUTION_NOTICE


def _normalize_education_decimal(value: object, field_name: str, *, allow_none: bool = True) -> Decimal | None:
    if value in (None, ""):
        if allow_none:
            return None
        raise ValidationError({field_name: "A decimal value is required."})
    parsed = parse_decimal_amount(value)
    if parsed is None:
        raise ValidationError({field_name: "Enter a valid decimal value."})
    if parsed < 0:
        raise ValidationError({field_name: "Value cannot be negative."})
    return parsed.quantize(Decimal("0.01"))


def _normalize_education_branding_payload(payload, existing: dict | None = None, *, user=None, institution=None):
    """Returns (branding, intent). `intent` is set when the client uploaded
    a real logo file (logo_attachment.media_id) — the caller must
    bind_education_media() it once the institution row exists (for a
    brand-new institution, that's right after .objects.create()). See
    _education_cover_image_from_payload for why a plain logo_url/logoUrl/
    etc string remains free text (never resolved server-side) while an
    attachment object is.

    Every logo_url/image_url/etc value read back through
    EducationInstitutionSerializer.to_representation is a resolved,
    presigned, EXPIRING display URL — the serializer overwrites the same
    branding[key] in place with it rather than exposing it under a
    separate field (see that method for why). An edit form that hydrates
    its "current value" from a GET response and resends it unchanged on
    a later PATCH would otherwise round-trip that temporary URL straight
    back into storage, permanently replacing the stable object key with
    a value that stops working the moment its signature expires —
    confirmed in production (a signed url with X-Amz-Expires=3600, over
    7 hours stale, is exactly what had been persisted into
    branding.logo_url/logoUrl for Kingdom Impact Tech Academy). The fix
    lives one level down: normalize_media_reference (via
    common.media_urls.strip_backend_origin) now detects a presigned
    object-storage URL and self-heals it back to the stable object key
    before it's ever written to branding[target_key] below, rather than
    persisting it verbatim — see that function's docstring."""
    branding = dict(existing or {})
    raw_branding = payload.get("branding") if hasattr(payload, "get") else None
    if isinstance(raw_branding, dict):
        branding.update(raw_branding)

    intent = None
    logo_resolved = False
    logo_attachment = _first_payload_value(payload, "logo_attachment", "logoAttachment")
    if not isinstance(logo_attachment, dict) and isinstance(raw_branding, dict):
        logo_attachment = raw_branding.get("logo_attachment") or raw_branding.get("logoAttachment")
    if isinstance(logo_attachment, dict):
        media_id = str(logo_attachment.get("media_id") or logo_attachment.get("mediaId") or "").strip()
        if media_id:
            if user is None:
                raise ValidationError({"logo_attachment": "Logo upload is not supported in this context."})
            intent, decision = education_media.resolve_and_scan_education_media(
                user=user, institution=institution, media_id=media_id,
                expected_context=education_media.LOGO_CONTEXT,
            )
            if not education_media.is_blocked(decision):
                branding["logo_url"] = intent.object_key
                logo_resolved = True
            else:
                intent = None

    alias_map = {
        "logo_url": ("logo_url", "logoUrl", "logo", "avatar_url", "avatarUrl"),
        "image_url": ("image_url", "imageUrl", "institution_image_url", "institutionImageUrl"),
        "banner_image_url": ("banner_image_url", "bannerImageUrl", "cover_image_url", "coverImageUrl", "cover_url", "coverUrl"),
    }
    # A server-resolved logo (from logo_attachment.media_id) is
    # authoritative — a client cannot smuggle a second, unverified
    # logo_url/logoUrl/etc string in the same request to override it.
    for target_key, aliases in alias_map.items():
        if logo_resolved and target_key == "logo_url":
            continue
        value = _first_payload_value(payload, *aliases)
        if value is not None:
            branding[target_key] = normalize_media_reference(str(value).strip())

    for target_key in alias_map:
        if logo_resolved and target_key == "logo_url":
            continue
        if branding.get(target_key):
            branding[target_key] = normalize_media_reference(branding[target_key])

    if "image_url" not in branding and branding.get("logo_url"):
        branding["image_url"] = branding["logo_url"]
    if "logo_url" not in branding and branding.get("image_url"):
        branding["logo_url"] = branding["image_url"]

    # Preserve camelCase aliases for older frontend consumers.
    if branding.get("logo_url"):
        branding["logoUrl"] = branding["logo_url"]
    if branding.get("image_url"):
        branding["imageUrl"] = branding["image_url"]
    if branding.get("banner_image_url"):
        branding["bannerImageUrl"] = branding["banner_image_url"]
    return branding, intent


def _education_cover_image_from_payload(payload, *, user=None, institution=None):
    """Returns (cover_image_url, intent). Mirrors
    _education_material_media_payload's attachment-vs-free-text split: a
    `cover_image_attachment: {media_id}` is resolved server-side against a
    real, owned, confirmed upload (never a client-asserted url) — the
    caller must bind_education_media() the returned intent once the target
    row exists. A plain cover_image_url/imageUrl/etc string field remains
    free text, exactly as before (many callers paste an external image
    URL rather than uploading one)."""
    attachment = _first_payload_value(payload, "cover_image_attachment", "coverImageAttachment")
    if isinstance(attachment, dict):
        media_id = str(attachment.get("media_id") or attachment.get("mediaId") or "").strip()
        if media_id:
            if user is None:
                raise ValidationError({"cover_image_attachment": "Cover image upload is not supported in this context."})
            intent, decision = education_media.resolve_and_scan_education_media(
                user=user, institution=institution, media_id=media_id,
                expected_context=education_media.COVER_IMAGE_CONTEXT,
            )
            if education_media.is_blocked(decision):
                return "", None
            return intent.object_key, intent

    value = _first_payload_value(
        payload,
        "cover_image_url",
        "coverImageUrl",
        "cover_image",
        "coverImage",
        "cover_url",
        "coverUrl",
        "image_url",
        "imageUrl",
    )
    return normalize_media_reference(str(value or "").strip()), None


def _education_cover_image_in_payload(payload) -> bool:
    return any(
        key in payload
        for key in (
            "cover_image_url",
            "coverImageUrl",
            "cover_image",
            "coverImage",
            "cover_url",
            "coverUrl",
            "image_url",
            "imageUrl",
            "cover_image_attachment",
            "coverImageAttachment",
        )
    )


def _education_source_cover_image(
    *,
    program: EducationInstitutionProgram | None = None,
    course: EducationInstitutionCourse | None = None,
    lesson: EducationInstitutionLesson | None = None,
    class_session: EducationInstitutionClassSession | None = None,
    material: EducationInstitutionMaterial | None = None,
    assessment: EducationInstitutionAssessment | None = None,
    event: EducationInstitutionEvent | None = None,
) -> str:
    for entity in (program, course, lesson, class_session, material, assessment, event):
        value = normalize_media_reference(str(getattr(entity, "cover_image_url", "") or "").strip())
        if value:
            return value
    return ""


def _education_effective_broadcast_cover_image(broadcast: EducationInstitutionBroadcast) -> str:
    explicit_cover = normalize_media_reference(broadcast.cover_image_url)
    metadata = broadcast.metadata if isinstance(broadcast.metadata, dict) else {}
    manual_cover = bool(metadata.get("manual_cover_image"))
    if explicit_cover and manual_cover:
        return explicit_cover

    prioritized_entities: list[object | None] = []
    if broadcast.broadcast_kind == EducationBroadcastKind.PROGRAM:
        prioritized_entities = [broadcast.program, broadcast.course, broadcast.lesson, broadcast.class_session, broadcast.event]
    elif broadcast.broadcast_kind == EducationBroadcastKind.COURSE:
        prioritized_entities = [broadcast.course, broadcast.lesson, broadcast.class_session, broadcast.event, broadcast.program]
    elif broadcast.broadcast_kind == EducationBroadcastKind.LESSON:
        prioritized_entities = [broadcast.lesson, broadcast.class_session, broadcast.course, broadcast.event, broadcast.program]
    elif broadcast.broadcast_kind == EducationBroadcastKind.CLASS_SESSION:
        prioritized_entities = [broadcast.class_session, broadcast.lesson, broadcast.course, broadcast.event, broadcast.program]
    elif broadcast.broadcast_kind in {EducationBroadcastKind.EVENT, EducationBroadcastKind.TRAINING_SESSION}:
        prioritized_entities = [broadcast.event, broadcast.class_session, broadcast.lesson, broadcast.course, broadcast.program]
    else:
        prioritized_entities = [broadcast.program, broadcast.course, broadcast.lesson, broadcast.class_session, broadcast.event]

    for entity in prioritized_entities:
        value = normalize_media_reference(str(getattr(entity, "cover_image_url", "") or "").strip())
        if value:
            return value
    return explicit_cover or ""


def _sync_education_source_broadcasts(*entities: object) -> None:
    for entity in entities:
        broadcasts_manager = getattr(entity, "broadcasts", None)
        if broadcasts_manager is None:
            continue
        for broadcast in broadcasts_manager.all():
            _sync_education_broadcast_item(broadcast)


def _sync_course_pricing_to_broadcasts(course: "EducationInstitutionCourse") -> None:
    """Course.price_amount/price_currency/visibility are the source of
    truth the creator edits; any course-kind broadcast pointing at this
    course (the entity that actually makes it discoverable/enrollable —
    see EducationContentEnrollmentView) has its own price fields kept in
    lockstep here so the existing booking/payment machinery, which reads
    price off the broadcast, needs no changes at all."""
    for broadcast in course.broadcasts.all():
        broadcast.price_amount = course.price_amount
        broadcast.price_currency = course.price_currency
        broadcast.booking_enabled = bool(course.price_amount and course.price_amount > 0)
        broadcast.save(update_fields=["price_amount", "price_currency", "booking_enabled", "updated_at"])


def _education_booking_provider_user(booking: EducationInstitutionBooking) -> User:
    return booking.institution.owner


def _schedule_education_booking_auto_completion(booking_id: str) -> None:
    import importlib

    tasks_module = importlib.import_module("apps.broadcasts.tasks")
    auto_task = getattr(tasks_module, "auto_complete_education_booking", None)
    if auto_task:
        auto_task.apply_async(args=[str(booking_id)], countdown=3 * 24 * 60 * 60)


def _complete_education_booking(
    booking: EducationInstitutionBooking,
    *,
    satisfied_by: User | None = None,
    auto_release: bool = False,
) -> EducationInstitutionBooking:
    if booking.status == EducationBookingStatus.COMPLETED:
        return booking
    if booking.status not in {
        EducationBookingStatus.CONFIRMED,
        EducationBookingStatus.AWAITING_SATISFACTION,
    }:
        raise ValidationError({"detail": "Only confirmed bookings may be completed."})

    if booking.amount_cents > 0 and not booking.provider_credit_transaction_id:
        provider_user = _education_booking_provider_user(booking)
        reference = f"education-booking-payout-{booking.id}"
        release_meta = {
            "booking_id": str(booking.id),
            "broadcast_id": str(booking.broadcast_id),
            "institution_id": str(booking.institution_id),
            "source": "education_booking_payout",
            "auto_release": auto_release,
        }
        if booking.course_id:
            # Course purchase: split platform commission vs. institution
            # payout on this (legacy) wallet rail — the production
            # Flutterwave rail settles its split at the provider level
            # instead (see _education_course_split_subaccounts).
            release_locked_booking_funds_split(
                payer=booking.user,
                provider=provider_user,
                amount_cents=int(booking.amount_cents or 0),
                commission_pct=get_platform_commission_pct(provider_user),
                reference=reference,
                meta=release_meta,
            )
        else:
            release_locked_booking_funds(
                payer=booking.user,
                provider=provider_user,
                amount_cents=int(booking.amount_cents or 0),
                reference=reference,
                meta=release_meta,
            )
        provider_tx = WalletTransaction.objects.create(
            user=provider_user,
            provider="internal",
            method="education_booking_payout",
            amount_cents=int(booking.amount_cents or 0),
            currency=booking.currency or KIS_COIN_CODE,
            status="success",
            tx_ref=reference,
            processed_at=timezone.now(),
            meta={
                "booking_id": str(booking.id),
                "broadcast_id": str(booking.broadcast_id),
                "institution_id": str(booking.institution_id),
                "source": "education_booking_payout",
                "auto_release": auto_release,
            },
        )
        booking.provider_credit_transaction = provider_tx

    now = timezone.now()
    metadata = dict(booking.metadata) if isinstance(booking.metadata, dict) else {}
    if satisfied_by and not booking.payer_satisfied_at:
        booking.payer_satisfied_at = now
        metadata["satisfied_by_user_id"] = str(satisfied_by.id)
    if auto_release:
        metadata["auto_released_at"] = now.isoformat()
    booking.status = EducationBookingStatus.COMPLETED
    booking.metadata = metadata
    booking.save(
        update_fields=[
            "status",
            "provider_credit_transaction",
            "payer_satisfied_at",
            "metadata",
            "updated_at",
        ]
    )
    return booking


def _mark_education_booking_provider_completed(
    booking: EducationInstitutionBooking,
    *,
    completed_by: User,
) -> EducationInstitutionBooking:
    if booking.status not in {EducationBookingStatus.CONFIRMED, EducationBookingStatus.AWAITING_SATISFACTION}:
        raise ValidationError({"detail": "Only confirmed bookings can be marked completed by the provider."})
    now = timezone.now()
    deadline = now + timedelta(days=3)
    metadata = dict(booking.metadata) if isinstance(booking.metadata, dict) else {}
    metadata["provider_completed_by_user_id"] = str(completed_by.id)
    metadata["awaiting_satisfaction_until"] = deadline.isoformat()
    booking.status = EducationBookingStatus.AWAITING_SATISFACTION
    booking.provider_completed_at = now
    booking.satisfaction_deadline = deadline
    booking.metadata = metadata
    booking.save(
        update_fields=[
            "status",
            "provider_completed_at",
            "satisfaction_deadline",
            "metadata",
            "updated_at",
        ]
    )
    _schedule_education_booking_auto_completion(booking.id)
    return booking


