def _build_event_detail_payload(
    institution: EducationInstitution,
    event: EducationInstitutionEvent,
    request,
) -> dict[str, Any]:
    broadcasts_qs = institution.education_broadcasts.filter(event=event).order_by("-published_at", "-created_at")
    bookings_qs = institution.bookings.filter(event=event).order_by("-created_at")
    enrollments_qs = institution.enrollments.filter(event=event).order_by("-created_at")
    staff_assignments_qs = institution.staff_assignments.filter(event=event).select_related(
        "membership__user",
        "program",
        "course",
        "class_session",
        "assessment",
    ).order_by("-created_at")
    material_filter = Q()
    if event.program_id:
        material_filter |= _material_scope_q(program=event.program)
    if event.course_id:
        material_filter |= _material_scope_q(course=event.course)
    if event.class_session_id:
        material_filter |= _material_scope_q(class_session=event.class_session)
    related_materials_qs = (
        institution.materials.filter(material_filter).distinct().order_by("title", "-created_at")
        if material_filter
        else institution.materials.none()
    )
    event_payload = EducationInstitutionEventSerializer(event).data
    return _with_primary_detail_summary({
        "institution": EducationInstitutionSerializer(institution, context={"request": request}).data,
        "program": EducationInstitutionProgramSerializer(event.program).data if event.program else None,
        "course": EducationInstitutionCourseSerializer(event.course).data if event.course else None,
        "class_session": EducationInstitutionClassSessionSerializer(event.class_session).data if event.class_session else None,
        "event": event_payload,
        "metrics": {
            "broadcast_count": broadcasts_qs.count(),
            "booking_count": bookings_qs.count(),
            "enrollment_count": enrollments_qs.count(),
            "staff_assignment_count": staff_assignments_qs.count(),
            "related_material_count": related_materials_qs.count(),
        },
        "broadcasts": EducationInstitutionBroadcastSerializer(broadcasts_qs[:50], many=True, context={"request": request}).data,
        "bookings": EducationInstitutionBookingSerializer(bookings_qs[:50], many=True).data,
        "enrollments": EducationInstitutionEnrollmentSerializer(enrollments_qs[:50], many=True).data,
        "staff_assignments": EducationInstitutionStaffAssignmentSerializer(staff_assignments_qs[:50], many=True).data,
        "materials": EducationInstitutionMaterialSerializer(related_materials_qs[:50], many=True).data,
    }, "event")


def _build_broadcast_detail_payload(
    institution: EducationInstitution,
    broadcast: EducationInstitutionBroadcast,
    request,
) -> dict[str, Any]:
    enrollments_qs = broadcast.enrollments.select_related(
        "user",
        "program",
        "course",
        "lesson",
        "class_session",
        "event",
    ).order_by("-created_at")
    bookings_qs = broadcast.bookings.select_related(
        "user",
        "program",
        "course",
        "class_session",
        "event",
        "wallet_transaction",
    ).order_by("-created_at")
    if broadcast.class_session:
        target_staff_assignments_qs = institution.staff_assignments.filter(class_session=broadcast.class_session)
    elif broadcast.event:
        target_staff_assignments_qs = institution.staff_assignments.filter(event=broadcast.event)
    elif broadcast.lesson:
        target_staff_assignments_qs = institution.staff_assignments.filter(course=broadcast.course)
    elif broadcast.course:
        target_staff_assignments_qs = institution.staff_assignments.filter(course=broadcast.course)
    elif broadcast.program:
        target_staff_assignments_qs = institution.staff_assignments.filter(program=broadcast.program)
    else:
        target_staff_assignments_qs = institution.staff_assignments.none()
    target_staff_assignments_qs = target_staff_assignments_qs.select_related("membership__user").order_by("-created_at")
    payload = _with_primary_detail_summary({
        "institution": EducationInstitutionSerializer(institution, context={"request": request}).data,
        "program": EducationInstitutionProgramSerializer(broadcast.program).data if broadcast.program else None,
        "course": EducationInstitutionCourseSerializer(broadcast.course).data if broadcast.course else None,
        "lesson": EducationInstitutionLessonSerializer(broadcast.lesson).data if broadcast.lesson else None,
        "class_session": EducationInstitutionClassSessionSerializer(broadcast.class_session).data if broadcast.class_session else None,
        "event": EducationInstitutionEventSerializer(broadcast.event).data if broadcast.event else None,
        "broadcast": EducationInstitutionBroadcastSerializer(broadcast, context={"request": request}).data,
        "metrics": {
            "enrollment_count": enrollments_qs.count(),
            "booking_count": bookings_qs.count(),
            "confirmed_booking_count": _broadcast_confirmed_booking_count(broadcast),
            "staff_assignment_count": target_staff_assignments_qs.count(),
        },
        "enrollments": EducationInstitutionEnrollmentSerializer(enrollments_qs[:50], many=True).data,
        "bookings": EducationInstitutionBookingSerializer(bookings_qs[:50], many=True).data,
        "staff_assignments": EducationInstitutionStaffAssignmentSerializer(target_staff_assignments_qs[:50], many=True).data,
    }, "broadcast")
    payload["broadcast"]["viewer_state"] = _build_broadcast_viewer_state(broadcast, request.user)
    return payload


def _build_enrollment_detail_payload(
    institution: EducationInstitution,
    enrollment: EducationInstitutionEnrollment,
    request,
) -> dict[str, Any]:
    related_booking_filters: dict[str, Any] = {"user": enrollment.user}
    if enrollment.program_id:
        related_booking_filters["program"] = enrollment.program
    if enrollment.course_id:
        related_booking_filters["course"] = enrollment.course
    if enrollment.class_session_id:
        related_booking_filters["class_session"] = enrollment.class_session
    if enrollment.event_id:
        related_booking_filters["event"] = enrollment.event
    related_bookings_qs = institution.bookings.filter(**related_booking_filters).order_by("-created_at")
    assessment_submissions_qs = EducationInstitutionAssessmentSubmission.objects.filter(
        assessment__institution=institution,
        user=enrollment.user,
    )
    if enrollment.course_id:
        assessment_submissions_qs = assessment_submissions_qs.filter(assessment__course=enrollment.course)
    if enrollment.lesson_id:
        assessment_submissions_qs = assessment_submissions_qs.filter(assessment__lesson=enrollment.lesson)
    if enrollment.class_session_id:
        assessment_submissions_qs = assessment_submissions_qs.filter(
            assessment__class_session=enrollment.class_session
        )
    assessment_submissions_qs = assessment_submissions_qs.select_related("assessment").order_by(
        "-submitted_at", "-created_at"
    )
    member = institution.memberships.filter(user=enrollment.user).first()
    return {
        "institution": EducationInstitutionSerializer(institution, context={"request": request}).data,
        "membership": EducationInstitutionMembershipSerializer(member).data if member else None,
        "program": EducationInstitutionProgramSerializer(enrollment.program).data if enrollment.program else None,
        "course": EducationInstitutionCourseSerializer(enrollment.course).data if enrollment.course else None,
        "lesson": EducationInstitutionLessonSerializer(enrollment.lesson).data if enrollment.lesson else None,
        "class_session": EducationInstitutionClassSessionSerializer(enrollment.class_session).data if enrollment.class_session else None,
        "event": EducationInstitutionEventSerializer(enrollment.event).data if enrollment.event else None,
        "broadcast": EducationInstitutionBroadcastSerializer(enrollment.broadcast, context={"request": request}).data if enrollment.broadcast else None,
        "enrollment": EducationInstitutionEnrollmentSerializer(enrollment).data,
        "metrics": {
            "related_booking_count": related_bookings_qs.count(),
            "assessment_submission_count": assessment_submissions_qs.count(),
            "graded_assessment_count": assessment_submissions_qs.filter(
                status=EducationAssessmentSubmissionStatus.GRADED
            ).count(),
        },
        "bookings": EducationInstitutionBookingSerializer(related_bookings_qs[:50], many=True).data,
        "assessment_submissions": EducationInstitutionAssessmentSubmissionSerializer(
            assessment_submissions_qs[:50],
            many=True,
        ).data,
    }


def _build_booking_detail_payload(
    institution: EducationInstitution,
    booking: EducationInstitutionBooking,
    request,
) -> dict[str, Any]:
    related_enrollment_filters: dict[str, Any] = {"user": booking.user}
    if booking.program_id:
        related_enrollment_filters["program"] = booking.program
    if booking.course_id:
        related_enrollment_filters["course"] = booking.course
    if booking.class_session_id:
        related_enrollment_filters["class_session"] = booking.class_session
    if booking.event_id:
        related_enrollment_filters["event"] = booking.event
    related_enrollments_qs = institution.enrollments.filter(**related_enrollment_filters).order_by("-created_at")
    target_broadcast = booking.broadcast
    if not target_broadcast:
        target_broadcast_filters: dict[str, Any] = {}
        if booking.program_id:
            target_broadcast_filters["program"] = booking.program
        if booking.course_id:
            target_broadcast_filters["course"] = booking.course
        if booking.class_session_id:
            target_broadcast_filters["class_session"] = booking.class_session
        if booking.event_id:
            target_broadcast_filters["event"] = booking.event
        if target_broadcast_filters:
            target_broadcast = institution.education_broadcasts.filter(**target_broadcast_filters).order_by(
                "-published_at", "-created_at"
            ).first()
    member = institution.memberships.filter(user=booking.user).first()
    return {
        "institution": EducationInstitutionSerializer(institution, context={"request": request}).data,
        "membership": EducationInstitutionMembershipSerializer(member).data if member else None,
        "program": EducationInstitutionProgramSerializer(booking.program).data if booking.program else None,
        "course": EducationInstitutionCourseSerializer(booking.course).data if booking.course else None,
        "class_session": EducationInstitutionClassSessionSerializer(booking.class_session).data if booking.class_session else None,
        "event": EducationInstitutionEventSerializer(booking.event).data if booking.event else None,
        "broadcast": EducationInstitutionBroadcastSerializer(target_broadcast, context={"request": request}).data if target_broadcast else None,
        "booking": EducationInstitutionBookingSerializer(booking).data,
        "metrics": {
            "seat_count": int(booking.seat_count or 0),
            "related_enrollment_count": related_enrollments_qs.count(),
            "has_wallet_transaction": 1 if booking.wallet_transaction_id else 0,
        },
        "enrollments": EducationInstitutionEnrollmentSerializer(related_enrollments_qs[:50], many=True).data,
    }


def _serialize_health_institution_from_row(row: BroadcastHealthInstitution) -> dict:
    metadata = dict(row.metadata) if isinstance(row.metadata, dict) else {}
    blocked_medium_ids = _get_blocked_service_medium_ids()

    owner_contact = {
        "name": row.owner_name or "",
        "phone": row.owner_phone or "",
        "email": row.owner_email or "",
        "userId": str(row.owner_user_id or ""),
        "user_id": str(row.owner_user_id or ""),
    }

    members = []
    for member_row in row.member_rows.all().order_by("created_at"):
        member = {
            "id": member_row.member_uid or str(member_row.id),
            "name": member_row.name or "Worker",
            "role": member_row.role or "staff",
            "phone": member_row.phone or "",
            "email": member_row.email or "",
            "userId": str(member_row.user_id or ""),
            "user_id": str(member_row.user_id or ""),
        }
        if isinstance(member_row.metadata, dict):
            for key, value in member_row.metadata.items():
                if key not in member:
                    member[key] = _safe_json_value(value)
        members.append(member)

    services = []
    for service_row in row.service_rows.all().order_by("created_at"):
        medium_pairs, had_mediums, removed_any = filter_service_medium_pairs(
            service_row.medium_ids,
            service_row.medium_names,
            blocked_medium_ids=blocked_medium_ids,
        )
        if should_drop_service_after_medium_cleanup(
            had_mediums=had_mediums,
            removed_any=removed_any,
            remaining_pairs=medium_pairs,
        ):
            continue
        service = {
            "id": service_row.service_uid or str(service_row.id),
            "name": service_row.name,
            "description": service_row.description or "",
            "active": bool(service_row.active),
        }
        if service_row.base_price_cents is not None:
            service["basePriceCents"] = int(service_row.base_price_cents)
        medium_ids = [medium_id for medium_id, _medium_name in medium_pairs if medium_id]
        if medium_ids:
            service["medium_ids"] = medium_ids
            service["mediumIds"] = medium_ids
        medium_names = [medium_name for _medium_id, medium_name in medium_pairs if medium_name]
        if medium_names:
            service["medium_names"] = medium_names
            service["mediumNames"] = medium_names
        if isinstance(service_row.metadata, dict):
            for key, value in service_row.metadata.items():
                if key not in service:
                    service[key] = _safe_json_value(value)
        services.append(service)

    payload = dict(metadata)
    payload.update({
        "id": row.institution_uid,
        "institution_id": row.institution_uid,
        "institutionId": row.institution_uid,
        "type": row.institution_type,
        "name": row.name,
        "owner_contact": owner_contact,
        "ownerContact": owner_contact,
        "members_target_count": row.members_target_count,
        "membersTargetCount": row.members_target_count,
        "membership_open": bool(row.membership_open),
        "membershipOpen": bool(row.membership_open),
        "membership_discount_pct": int(row.membership_discount_pct),
        "membershipDiscountPct": int(row.membership_discount_pct),
        "membership_settings": {
            "open": bool(row.membership_open),
            "discountPercent": int(row.membership_discount_pct),
        },
        "membershipSettings": {
            "open": bool(row.membership_open),
            "discountPercent": int(row.membership_discount_pct),
        },
        "members": members,
        "employees": [
            {
                "id": _ensure_entry_id(member.get("id"), "worker"),
                "name": str(member.get("name") or "Worker"),
                "role": str(member.get("role") or "staff"),
                "phone": str(member.get("phone") or ""),
                "email": str(member.get("email") or ""),
                "user_id": str(member.get("userId") or member.get("user_id") or ""),
            }
            for member in members
        ],
        "services": services,
    })

    return _sanitize_institution(payload) or payload


def _build_health_institutions_from_tables(health_profile: BroadcastHealthProfile | None) -> list[dict]:
    if not health_profile:
        return []

    rows = (
        health_profile.institution_rows
        .all()
        .prefetch_related("member_rows", "service_rows")
        .order_by("created_at")
    )
    institutions: list[dict] = []
    for row in rows:
        parsed = _serialize_health_institution_from_row(row)
        if parsed:
            institutions.append(parsed)
    return _ensure_institution_data(institutions)


def _sync_health_profile_tables_from_payload(health_profile: BroadcastHealthProfile, health_payload: dict[str, Any]) -> list[dict]:
    institutions = _ensure_institution_data((health_payload or {}).get("institutions") or [])
    blocked_medium_ids = _get_blocked_service_medium_ids()
    existing_rows = {
        str(row.institution_uid): row
        for row in health_profile.institution_rows.all().prefetch_related("member_rows", "service_rows")
    }
    keep_institution_ids: set[str] = set()

    with transaction.atomic():
        for institution in institutions:
            institution_uid = str(
                institution.get("id")
                or institution.get("institution_id")
                or institution.get("institutionId")
                or ""
            ).strip()
            if not institution_uid:
                institution_uid = _ensure_entry_id(None, "inst")
            if institution_uid in keep_institution_ids:
                continue
            keep_institution_ids.add(institution_uid)

            owner_contact = institution.get("owner_contact") if isinstance(institution.get("owner_contact"), dict) else {}
            if not owner_contact and isinstance(institution.get("ownerContact"), dict):
                owner_contact = institution.get("ownerContact")

            profile_owner_user = getattr(getattr(health_profile, "profile", None), "user", None)
            owner_user_id = str(owner_contact.get("userId") or owner_contact.get("user_id") or "").strip()
            owner_user = User.objects.filter(id=owner_user_id).first() if owner_user_id else None
            if owner_user is None:
                owner_user = profile_owner_user
                if owner_user:
                    owner_user_id = str(owner_user.id)
                    owner_contact = {
                        **owner_contact,
                        "userId": owner_user_id,
                        "user_id": owner_user_id,
                        "name": str(
                            owner_contact.get("name")
                            or getattr(owner_user, "display_name", "")
                            or getattr(owner_user, "username", "")
                            or "Owner"
                        ),
                        "phone": str(owner_contact.get("phone") or getattr(owner_user, "phone", "") or ""),
                        "email": str(owner_contact.get("email") or getattr(owner_user, "email", "") or ""),
                    }
            membership = _sanitize_membership_settings(institution)

            institution_metadata = dict(institution)
            for key in (
                "id",
                "institution_id",
                "institutionId",
                "type",
                "name",
                "employees",
                "members",
                "services",
                "owner_contact",
                "ownerContact",
                "members_target_count",
                "membersTargetCount",
                "membership_open",
                "membershipOpen",
                "membership_discount_pct",
                "membershipDiscountPct",
                "membership_settings",
                "membershipSettings",
            ):
                institution_metadata.pop(key, None)

            defaults = {
                "institution_type": _normalize_health_institution_type(institution.get("type")),
                "name": str(institution.get("name") or "Health Institution").strip() or "Health Institution",
                "owner_user": owner_user,
                "owner_name": str(owner_contact.get("name") or "").strip(),
                "owner_phone": str(owner_contact.get("phone") or "").strip(),
                "owner_email": str(owner_contact.get("email") or "").strip(),
                "members_target_count": _parse_positive_int(
                    institution.get("members_target_count") or institution.get("membersTargetCount"),
                    1,
                ),
                "membership_open": bool(membership.get("open")),
                "membership_discount_pct": int(membership.get("discountPercent") or 10),
                "metadata": _safe_json_value(institution_metadata),
            }

            institution_row = existing_rows.get(institution_uid)
            if institution_row:
                for field, value in defaults.items():
                    setattr(institution_row, field, value)
                institution_row.save()
            else:
                institution_row = BroadcastHealthInstitution.objects.create(
                    health_profile=health_profile,
                    institution_uid=institution_uid,
                    **defaults,
                )

            raw_members = institution.get("members") if isinstance(institution.get("members"), list) else []
            raw_employees = institution.get("employees") if isinstance(institution.get("employees"), list) else []
            normalized_members = _sanitize_members(
                raw_members,
                raw_employees,
                str(institution.get("name") or "Institution"),
                owner_contact,
            )
            existing_members = {
                str(member.member_uid): member
                for member in institution_row.member_rows.all()
            }
            keep_member_ids: set[str] = set()
            for member in normalized_members:
                member_uid = _ensure_entry_id(member.get("id"), "worker")
                if member_uid in keep_member_ids:
                    continue
                keep_member_ids.add(member_uid)
                member_user_id = str(member.get("userId") or member.get("user_id") or "").strip()
                member_user = User.objects.filter(id=member_user_id).first() if member_user_id else None
                member_metadata = dict(member)
                for key in ("id", "name", "role", "phone", "email", "userId", "user_id"):
                    member_metadata.pop(key, None)
                member_defaults = {
                    "name": str(member.get("name") or "Worker"),
                    "role": _normalize_member_role(member.get("role")),
                    "phone": str(member.get("phone") or ""),
                    "email": str(member.get("email") or ""),
                    "user": member_user,
                    "metadata": _safe_json_value(member_metadata),
                }
                member_row = existing_members.get(member_uid)
                if member_row:
                    for field, value in member_defaults.items():
                        setattr(member_row, field, value)
                    member_row.save()
                else:
                    BroadcastHealthInstitutionMember.objects.create(
                        institution=institution_row,
                        member_uid=member_uid,
                        **member_defaults,
                    )
            institution_row.member_rows.exclude(member_uid__in=keep_member_ids).delete()

            normalized_services = _sanitize_services(
                institution.get("services"),
                blocked_medium_ids=blocked_medium_ids,
            )
            existing_services = {
                str(service.service_uid): service
                for service in institution_row.service_rows.all()
            }
            keep_service_ids: set[str] = set()
            for index, service in enumerate(normalized_services):
                service_uid = str(service.get("id") or service.get("service_id") or "").strip()
                if not service_uid:
                    service_uid = f"service_{index + 1}"
                if service_uid in keep_service_ids:
                    continue
                keep_service_ids.add(service_uid)

                service_metadata = dict(service)
                for key in (
                    "id",
                    "service_id",
                    "name",
                    "description",
                    "active",
                    "basePriceCents",
                    "medium_ids",
                    "mediumIds",
                    "medium_names",
                    "mediumNames",
                ):
                    service_metadata.pop(key, None)

                base_price_cents = service.get("basePriceCents")
                parsed_cents = None
                if base_price_cents is not None:
                    try:
                        parsed_cents = int(float(base_price_cents))
                    except (TypeError, ValueError):
                        parsed_cents = None

                medium_ids = [str(item or "").strip() for item in (service.get("medium_ids") or service.get("mediumIds") or []) if str(item or "").strip()]
                medium_names = [str(item or "").strip() for item in (service.get("medium_names") or service.get("mediumNames") or []) if str(item or "").strip()]

                service_defaults = {
                    "name": str(service.get("name") or f"Service {index + 1}").strip() or f"Service {index + 1}",
                    "description": str(service.get("description") or "").strip(),
                    "active": bool(service.get("active", True)),
                    "base_price_cents": parsed_cents if parsed_cents is not None and parsed_cents >= 0 else None,
                    "medium_ids": medium_ids,
                    "medium_names": medium_names,
                    "metadata": _safe_json_value(service_metadata),
                }
                service_row = existing_services.get(service_uid)
                if service_row:
                    for field, value in service_defaults.items():
                        setattr(service_row, field, value)
                    service_row.save()
                else:
                    BroadcastHealthInstitutionService.objects.create(
                        institution=institution_row,
                        service_uid=service_uid,
                        **service_defaults,
                    )
            institution_row.service_rows.exclude(service_uid__in=keep_service_ids).delete()

        health_profile.institution_rows.exclude(institution_uid__in=keep_institution_ids).delete()

    return institutions


def _compose_health_profile_payload(
    health_profile: BroadcastHealthProfile | None,
    base_payload: dict[str, Any] | None = None,
) -> dict[str, Any]:
    payload = {}
    if health_profile and isinstance(health_profile.payload, dict):
        payload.update(health_profile.payload)
    if isinstance(base_payload, dict):
        payload.update(base_payload)

    table_institutions = _build_health_institutions_from_tables(health_profile)
    if table_institutions:
        payload["institutions"] = table_institutions
    else:
        payload["institutions"] = _ensure_institution_data(payload.get("institutions") or [])

    return _ensure_health_profile_structure(payload)


def _resolve_core_patient_for_user(user):
    if not getattr(user, "is_authenticated", False):
        return None

    PatientMasterRecord = django_apps.get_model("core", "PatientMasterRecord")
    user_id = str(getattr(user, "id", "") or "").strip()
    email = str(getattr(user, "email", "") or "").strip()
    phone_candidates = [
        str(getattr(user, "phone", "") or "").strip(),
        str(getattr(user, "phone_number", "") or "").strip(),
    ]

    patient = PatientMasterRecord.objects.filter(primary_contact__user_id=user_id).order_by("-updated_at").first()
    if patient:
        return patient
    if email:
        patient = PatientMasterRecord.objects.filter(primary_contact__email__iexact=email).order_by("-updated_at").first()
        if patient:
            return patient
    for phone in phone_candidates:
        if not phone:
            continue
        patient = (
            PatientMasterRecord.objects.filter(primary_contact__phone=phone).order_by("-updated_at").first()
            or PatientMasterRecord.objects.filter(primary_contact__phone_number=phone).order_by("-updated_at").first()
        )
        if patient:
            return patient
    return None


def _default_primary_contact_for_user(user) -> dict[str, Any]:
    if not getattr(user, "is_authenticated", False):
        return {}
    return {
        "user_id": str(getattr(user, "id", "") or ""),
        "email": str(getattr(user, "email", "") or ""),
        "phone": str(getattr(user, "phone", "") or ""),
        "phone_number": str(getattr(user, "phone_number", "") or ""),
        "display_name": (
            str(getattr(user, "display_name", "") or "").strip()
            or str(getattr(user, "username", "") or "").strip()
            or str(getattr(user, "email", "") or "").strip()
        ),
    }


def _extract_identity_payload(health_payload: dict[str, Any]) -> dict[str, Any]:
    identity = health_payload.get("identity")
    if isinstance(identity, dict):
        return dict(identity)
    return {}


def _extract_emergency_payload(health_payload: dict[str, Any]) -> dict[str, Any]:
    emergency = health_payload.get("emergency")
    if isinstance(emergency, dict):
        return dict(emergency)
    return {}


def _merge_health_profile_core_fields(profile: dict[str, Any], updates: dict[str, Any]) -> dict[str, Any]:
    identity_updates = updates.get("identity")
    if isinstance(identity_updates, dict):
        existing_identity = profile.get("identity") if isinstance(profile.get("identity"), dict) else {}
        merged_identity = dict(existing_identity)
        for key in ("first_name", "last_name", "full_name", "dob", "gender", "primary_contact"):
            value = identity_updates.get(key)
            if value is not None:
                merged_identity[key] = value
        profile["identity"] = merged_identity

    emergency_updates = updates.get("emergency")
    if isinstance(emergency_updates, dict):
        existing_emergency = profile.get("emergency") if isinstance(profile.get("emergency"), dict) else {}
        merged_emergency = dict(existing_emergency)
        for key in ("emergency_contact", "blood_type", "medical_notes"):
            value = emergency_updates.get(key)
            if value is not None:
                merged_emergency[key] = value
        profile["emergency"] = merged_emergency

    for key in ("primary_contact", "emergency_contact", "blood_type", "medical_notes", "profile_name"):
        value = updates.get(key)
        if value is not None:
            profile[key] = value

    return profile


def _sync_core_patient_from_health_profile(user, health_payload: dict[str, Any]):
    PatientMasterRecord = django_apps.get_model("core", "PatientMasterRecord")

    patient = _resolve_core_patient_for_user(user)
    identity = _extract_identity_payload(health_payload)
    emergency = _extract_emergency_payload(health_payload)

    # Prefer the nested identity/emergency values (built from THIS update's
    # health_payload["identity"/"emergency"], just merged in by
    # _merge_health_profile_core_fields) over the top-level
    # primary_contact/emergency_contact keys, which are only a stale
    # denormalized mirror written by _merge_core_patient_into_health_profile
    # from the patient record's *pre-update* state (see _load_user_profiles,
    # which runs that merge before this update is even applied). Checking
    # the top-level mirror first — as this used to — meant a fresh
    # emergency_contact/primary_contact update could never take effect: the
    # old mirrored dict always satisfied isinstance(..., dict) first.
    primary_contact = identity.get("primary_contact")
    if not isinstance(primary_contact, dict):
        primary_contact = health_payload.get("primary_contact")
    if not isinstance(primary_contact, dict) or not primary_contact:
        primary_contact = _default_primary_contact_for_user(user)

    emergency_contact = emergency.get("emergency_contact")
    if not isinstance(emergency_contact, dict):
        emergency_contact = health_payload.get("emergency_contact")
    if not isinstance(emergency_contact, dict):
        emergency_contact = {}

    first_name = str(
        identity.get("first_name")
        or health_payload.get("first_name")
        or getattr(user, "display_name", "")
        or "Health"
    ).strip() or "Health"
    last_name = str(
        identity.get("last_name")
        or health_payload.get("last_name")
        or getattr(user, "username", "")
        or "Profile"
    ).strip() or "Profile"
    gender = str(
        identity.get("gender")
        or health_payload.get("gender")
        or PatientMasterRecord.GENDER_UNKNOWN
    ).strip() or PatientMasterRecord.GENDER_UNKNOWN
    dob_raw = identity.get("dob") or health_payload.get("dob")
    dob_value = dob_raw
    if isinstance(dob_raw, str):
        # health_payload/identity come straight off the request JSON, so
        # dob arrives as a plain string. PatientMasterRecord.dob is a real
        # DateField, but Django only coerces field values to Python types
        # when a row is loaded from the DB — assigning a raw string via
        # setattr()+save() below leaves this in-memory instance holding a
        # str, so any later patient.dob.isoformat() call (see
        # _merge_core_patient_into_health_profile) crashes with
        # AttributeError. Parse it up front instead.
        from django.utils.dateparse import parse_date

        dob_value = parse_date(dob_raw)

    metadata = dict(patient.metadata if patient and isinstance(patient.metadata, dict) else {})
    for key, value in {
        "blood_type": emergency.get("blood_type") or health_payload.get("blood_type"),
        "medical_notes": emergency.get("medical_notes") or health_payload.get("medical_notes"),
        "health_profile_name": health_payload.get("profile_name"),
    }.items():
        if value is not None:
            metadata[key] = value
    metadata["linked_health_profile_user_id"] = str(getattr(user, "id", "") or "")

    defaults = {
        "first_name": first_name,
        "last_name": last_name,
        "gender": gender,
        "primary_contact": primary_contact,
        "emergency_contact": emergency_contact,
        "metadata": metadata,
    }
    if dob_value:
        defaults["dob"] = dob_value

    if patient is None:
        patient = PatientMasterRecord.objects.create(
            mrn=f"KIS-HP-{uuid.uuid4().hex[:10].upper()}",
            **defaults,
        )
    else:
        for field, value in defaults.items():
            setattr(patient, field, value)
        patient.save()

    return patient


def _merge_core_patient_into_health_profile(health_payload: dict[str, Any], patient) -> dict[str, Any]:
    payload = dict(health_payload or {})
    patient_metadata = patient.metadata if isinstance(getattr(patient, "metadata", None), dict) else {}
    identity = payload.get("identity") if isinstance(payload.get("identity"), dict) else {}
    emergency = payload.get("emergency") if isinstance(payload.get("emergency"), dict) else {}

    identity.update(
        {
            "patient_id": str(getattr(patient, "id", "") or ""),
            "mrn": getattr(patient, "mrn", ""),
            "first_name": getattr(patient, "first_name", ""),
            "last_name": getattr(patient, "last_name", ""),
            "full_name": " ".join(
                part for part in [getattr(patient, "first_name", ""), getattr(patient, "last_name", "")] if part
            ).strip(),
            "dob": patient.dob.isoformat() if getattr(patient, "dob", None) else None,
            "gender": getattr(patient, "gender", ""),
            "primary_contact": patient.primary_contact if isinstance(getattr(patient, "primary_contact", None), dict) else {},
        }
    )
    emergency.update(
        {
            "emergency_contact": patient.emergency_contact if isinstance(getattr(patient, "emergency_contact", None), dict) else {},
            "blood_type": patient_metadata.get("blood_type"),
            "medical_notes": patient_metadata.get("medical_notes"),
        }
    )

    payload["identity"] = identity
    payload["emergency"] = emergency
    payload["primary_contact"] = identity.get("primary_contact") or {}
    payload["emergency_contact"] = emergency.get("emergency_contact") or {}
    payload["blood_type"] = emergency.get("blood_type")
    payload["medical_notes"] = emergency.get("medical_notes")
    payload["linked_patient_id"] = str(getattr(patient, "id", "") or "")
    payload["linked_patient_mrn"] = getattr(patient, "mrn", "")
    return payload


def _load_user_profiles(user, include_member_institutions: bool = False):
    prefs = dict(getattr(user, "preferences", {}) or {})
    profiles = dict(prefs.get("profiles") or {})
    account_profile, _ = Profile.objects.get_or_create(user=user)

    feed_profile = BroadcastFeedProfile.objects.filter(profile=account_profile).first()
    if feed_profile and isinstance(feed_profile.payload, dict):
        profiles["broadcast_feed"] = feed_profile.payload
    elif isinstance(profiles.get("broadcast_feed"), dict):
        BroadcastFeedProfile.objects.update_or_create(
            profile=account_profile,
            defaults={"payload": profiles["broadcast_feed"]},
        )

    health_profile = BroadcastHealthProfile.objects.filter(profile=account_profile).first()
    if not health_profile and isinstance(profiles.get("health"), dict):
        health_profile = BroadcastHealthProfile.objects.create(
            profile=account_profile,
            payload=_prepare_health_profile_for_storage(profiles.get("health") or {}),
        )
        _sync_health_profile_tables_from_payload(health_profile, profiles.get("health") or {})

    health_payload = _compose_health_profile_payload(
        health_profile,
        profiles.get("health") if isinstance(profiles.get("health"), dict) else None,
    )
    linked_patient = _resolve_core_patient_for_user(user)
    if linked_patient:
        health_payload = _merge_core_patient_into_health_profile(health_payload, linked_patient)

    local_institutions = _ensure_institution_data(health_payload.get("institutions") or [])
    owned_institutions = [inst for inst in local_institutions if _is_user_owner_of_institution(user, inst)]
    authoritative_owned = _collect_owner_accessible_health_institutions(user)
    if authoritative_owned:
        owned_institutions = authoritative_owned
    if health_payload:
        health_payload["institutions"] = owned_institutions

    if include_member_institutions:
        member_institutions = _collect_member_accessible_health_institutions(
            user,
            exclude_owner_user_id=str(getattr(user, "id", "") or ""),
        )
        merged_institutions = _merge_health_institutions(owned_institutions, member_institutions)
        merged_health = dict(health_payload or {})
        merged_health["institutions"] = merged_institutions
        merged_health["owned_institutions"] = owned_institutions
        merged_health["member_institutions"] = member_institutions
        has_owner_profile = len(owned_institutions) > 0
        merged_health["has_owner_profile"] = has_owner_profile
        merged_health["hasOwnerProfile"] = has_owner_profile
        merged_health["viewer_access_mode"] = "owner" if has_owner_profile else "member"
        profiles["health"] = _ensure_health_profile_structure(merged_health)
    elif health_payload:
        profiles["health"] = _ensure_health_profile_structure(health_payload)

    market_profile = BroadcastMarketProfile.objects.filter(profile=account_profile).first()
    if market_profile and isinstance(market_profile.payload, dict):
        profiles["market"] = market_profile.payload
    elif isinstance(profiles.get("market"), dict):
        BroadcastMarketProfile.objects.update_or_create(
            profile=account_profile,
            defaults={"payload": profiles["market"]},
        )

    education_profiles = _serialize_education_profiles(user)
    profiles["education_profiles"] = education_profiles
    if education_profiles:
        default_profile = next((p for p in education_profiles if p.get("is_default")), education_profiles[0])
        profiles["education"] = _build_education_summary(default_profile)
    return profiles


def _prepare_health_profile_for_storage(health_payload: dict[str, Any]) -> dict[str, Any]:
    persisted = dict(health_payload or {})
    for key in (
        "institutions",
        "employees_total",
        "owned_institutions",
        "ownedInstitutions",
        "member_institutions",
        "memberInstitutions",
        "viewer_access_mode",
        "viewerAccessMode",
        "has_owner_profile",
        "hasOwnerProfile",
    ):
        persisted.pop(key, None)
    return _safe_json_value(persisted) if isinstance(_safe_json_value(persisted), dict) else {}


def _save_user_profiles(user, profiles):
    persisted_profiles = dict(profiles or {})
    account_profile, _ = Profile.objects.get_or_create(user=user)

    feed_payload = persisted_profiles.get("broadcast_feed")
    if isinstance(feed_payload, dict):
        BroadcastFeedProfile.objects.update_or_create(
            profile=account_profile,
            defaults={"payload": feed_payload},
        )

    health_payload = persisted_profiles.get("health")
    if isinstance(health_payload, dict):
        health_profile, _ = BroadcastHealthProfile.objects.update_or_create(
            profile=account_profile,
            defaults={"payload": _prepare_health_profile_for_storage(health_payload)},
        )
        _sync_health_profile_tables_from_payload(health_profile, health_payload)
        linked_patient = _sync_core_patient_from_health_profile(user, health_payload)
        persisted_profiles["health"] = _merge_core_patient_into_health_profile(
            _compose_health_profile_payload(health_profile),
            linked_patient,
        )

    market_payload = persisted_profiles.get("market")
    if isinstance(market_payload, dict):
        BroadcastMarketProfile.objects.update_or_create(
            profile=account_profile,
            defaults={"payload": market_payload},
        )

    prefs = dict(getattr(user, "preferences", {}) or {})
    profile_cache = dict(persisted_profiles)
    if isinstance(profile_cache.get("health"), dict):
        slim_health = dict(profile_cache["health"])
        slim_health["institutions"] = []
        slim_health["employees_total"] = 0
        for key in (
            "owned_institutions",
            "ownedInstitutions",
            "member_institutions",
            "memberInstitutions",
        ):
            slim_health.pop(key, None)
        profile_cache["health"] = slim_health
    prefs["profiles"] = profile_cache
    user.preferences = prefs
    user.save(update_fields=["preferences"])

def _write_broadcast_moderation_audit(
    *,
    actor: User,
    action: str,
    item: BroadcastItem | None = None,
    target_id: Any | None = None,
    metadata: dict[str, Any] | None = None,
) -> None:
    try:
        resolved_target_id = target_id or (item.id if item else None)
        if not resolved_target_id:
            return
        payload = dict(metadata or {})
        if item is not None:
            payload.setdefault("source_type", item.source_type)
            payload.setdefault("source_id", str(item.source_id))
            payload.setdefault("broadcasted_by_id", str(item.broadcasted_by_id) if item.broadcasted_by_id else "")
        ModerationAuditLog.objects.create(
            actor_id=actor.id,
            action=action,
            target_type="POST",
            target_id=resolved_target_id,
            metadata=payload,
        )
    except Exception:
        logger.exception("[broadcasts] failed to write moderation audit action=%s", action)


def _delete_user_broadcast(user, entry_id):
    updated = BroadcastItem.objects.filter(
        source_id=entry_id,
        broadcasted_by=user,
        is_deleted=False,
    ).update(is_deleted=True, expires_at=timezone.now())
    return updated


def _store_upload(file_obj, user=None) -> tuple[str, int]:
    if user and getattr(user, "is_authenticated", False):
        features = get_user_tier_features(user)
        limit_mb = normalize_limit_value(features.get("media_storage_mb"), default=None)
        if limit_mb is not None:
            limit_bytes = int(limit_mb) * 1024 * 1024
            if file_obj.size > limit_bytes:
                raise ValidationError({"detail": "Media file exceeds your tier storage limit."})
    rel_name = f"{uuid.uuid4().hex}{os.path.splitext(file_obj.name or '')[1] or '.mp4'}"
    rel_path = os.path.join(MEDIA_SUBDIRECTORY, rel_name).replace(os.sep, "/")
    # Route through default_storage (not a raw open()/os.path.join(MEDIA_ROOT, ...)
    # write) so this respects OBJECT_STORAGE_PROVIDER the same way profile/
    # commerce ImageFields already do — otherwise broadcast/feed/education/
    # health/market/partner uploads always land on local disk regardless of
    # S3/Supabase config.
    saved_path = default_storage.save(rel_path, file_obj)
    return saved_path, file_obj.size


HEALTH_INSTITUTION_TYPES = {
    "clinic",
    "hospital",
    "lab",
    "wellness_center",
    "pharmacy",
    "diagnostics",
}


def _ensure_entry_id(value: str | None, prefix: str) -> str:
    candidate = str(value).strip() if value else ""
    if candidate:
        return candidate
    return f"{prefix}-{uuid.uuid4().hex}"


def _sanitize_profile_course_entry(entry: object | None) -> dict | None:
    if not isinstance(entry, dict):
        return None
    title = str(entry.get("title") or "").strip()
    if not title:
        return None
    summary = str(entry.get("summary") or entry.get("description") or "").strip()
    metadata = entry.get("metadata") if isinstance(entry.get("metadata"), dict) else {}
    return {"title": title, "summary": summary, "metadata": metadata}


def _sanitize_profile_module_entry(entry: object | None) -> dict | None:
    if not isinstance(entry, dict):
        return None
    title = str(entry.get("title") or "").strip()
    if not title:
        return None
    summary = str(entry.get("summary") or "").strip()
    resource_url = entry.get("resource_url") or entry.get("resourceUrl")
    return {"title": title, "summary": summary, "resource_url": resource_url}


def _sanitize_profile_role_entry(entry: object | None) -> dict | None:
    if not isinstance(entry, dict):
        return None
    name = str(entry.get("name") or "").strip()
    if not name:
        return None
    permissions = entry.get("permissions") or entry.get("permission_list") or []
    if not isinstance(permissions, list):
        permissions = []
    assignments = entry.get("assignments") or entry.get("collaborators") or []
    return {"name": name, "permissions": permissions, "assignments": assignments}


