def _encode_feed_cursor(offset: int | None) -> str | None:
    if offset is None:
        return None
    return f"o:{max(int(offset), 0)}"


def _decode_feed_cursor(value: Any, default: int = 0) -> int:
    text = str(value or "").strip()
    if not text:
        return default
    if text.startswith("o:"):
        text = text[2:]
    try:
        return max(int(text), 0)
    except (TypeError, ValueError):
        return default


_BROADCAST_ENGAGEMENT_WINDOWS = {
    BroadcastEngagementEventType.IMPRESSION: 300,
    BroadcastEngagementEventType.VIEW: 300,
    BroadcastEngagementEventType.SHARE: 3600,
}


def _broadcast_engagement_window_key(
    event_type: str,
    *,
    platform: str = "",
    idempotency_key: Any = "",
    at: Any = None,
) -> str:
    explicit_key = str(idempotency_key or "").strip()
    platform_key = re.sub(r"[^a-z0-9_.:-]+", "-", str(platform or "").strip().lower())[:48]
    if explicit_key:
        return f"id:{platform_key}:{explicit_key[:72]}"
    window_seconds = max(int(_BROADCAST_ENGAGEMENT_WINDOWS.get(event_type, 300) or 300), 1)
    event_time = at or timezone.now()
    timestamp = int(event_time.timestamp())
    return f"w:{platform_key}:{timestamp // window_seconds}"


def _record_broadcast_engagement(
    *,
    item: BroadcastItem,
    user: User,
    event_type: str,
    platform: str = "",
    metadata: dict[str, Any] | None = None,
    idempotency_key: Any = "",
) -> tuple[BroadcastEngagementEvent, bool]:
    window_key = _broadcast_engagement_window_key(
        event_type,
        platform=platform,
        idempotency_key=idempotency_key,
    )
    return BroadcastEngagementEvent.objects.get_or_create(
        broadcast_item=item,
        user=user,
        event_type=event_type,
        window_key=window_key,
        defaults={
            "platform": str(platform or "")[:64],
            "metadata": metadata or {},
        },
    )


def _broadcast_engagement_counts(broadcast_ids: list[Any]) -> dict[str, dict[str, int]]:
    ids = [item_id for item_id in broadcast_ids if item_id]
    counts: dict[str, dict[str, int]] = {
        str(item_id): {
            "share_count": 0,
            "view_count": 0,
            "impression_count": 0,
        }
        for item_id in ids
    }
    if not ids:
        return counts
    rows = (
        BroadcastEngagementEvent.objects.filter(broadcast_item_id__in=ids)
        .values("broadcast_item_id", "event_type")
        .annotate(total=models.Count("id"))
    )
    key_map = {
        BroadcastEngagementEventType.SHARE: "share_count",
        BroadcastEngagementEventType.VIEW: "view_count",
        BroadcastEngagementEventType.IMPRESSION: "impression_count",
    }
    for row in rows:
        broadcast_id = str(row["broadcast_item_id"])
        count_key = key_map.get(row["event_type"])
        if count_key:
            counts.setdefault(
                broadcast_id,
                {"share_count": 0, "view_count": 0, "impression_count": 0},
            )[count_key] = int(row["total"] or 0)
    return counts


def _apply_broadcast_engagement_counts(
    items: list[dict[str, Any]],
    counts: dict[str, dict[str, int]],
) -> None:
    # Collect comment conversation IDs to bulk-fetch message counts
    conv_ids = [
        str(item["comment_conversation_id"])
        for item in items
        if item.get("comment_conversation_id")
    ]
    conv_seq_map: dict[str, int] = {}
    if conv_ids:
        from apps.chat.models import Conversation as _Conv
        for row in _Conv.objects.filter(id__in=conv_ids).values("id", "last_message_seq"):
            conv_seq_map[str(row["id"])] = int(row["last_message_seq"] or 0)

    for item in items:
        broadcast_id = str(item.get("id") or "")
        item_counts = counts.get(broadcast_id, {})
        item["share_count"] = int(item_counts.get("share_count") or item.get("share_count") or 0)
        item["view_count"] = int(item_counts.get("view_count") or item.get("view_count") or 0)
        item["impression_count"] = int(item_counts.get("impression_count") or item.get("impression_count") or 0)
        conv_id = str(item.get("comment_conversation_id") or "")
        item["comment_count"] = conv_seq_map.get(conv_id) or int(item.get("comment_count") or 0)


class BroadcastFeedView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request):
        # Server-authoritative responsible-engagement limit (2h/day
        # default) - this is the one place it's actually enforced; the
        # heartbeat/status endpoints (apps.accounts.responsible_feed) are
        # just the ledger the client polls to know when it's coming.
        # Empty results + a limit_reached flag rather than an error status,
        # so any client that doesn't understand this yet still degrades to
        # "no more posts" instead of breaking. Deliberately only this
        # endpoint - messaging, calls, the user's own profile, and settings
        # are untouched.
        feed_status = get_today_feed_status(request.user)
        if feed_status["limit_reached"]:
            return Response(
                {"results": [], "count": 0, "next": None, "previous": None, "feed_limit": feed_status},
                status=status.HTTP_200_OK,
            )

        cleaned = cleanup_expired_broadcast_items()
        if cleaned:
            logger.info("Purged %d expired broadcast items before listing the feed.", cleaned)

        def _parse_positive_int(value: Any, default: int) -> int:
            try:
                return max(int(value), 0)
            except (TypeError, ValueError):
                return default

        def _build_page_url(offset_value: int | None) -> str | None:
            if offset_value is None:
                return None
            params = request.query_params.copy()
            params["limit"] = str(limit)
            params["offset"] = str(max(offset_value, 0))
            params["cursor"] = _encode_feed_cursor(offset_value) or ""
            query = params.urlencode()
            return build_absolute_url(request, f"{request.path}?{query}")

        limit = int(request.query_params.get("limit", 50))
        limit = max(1, min(limit, 200))
        if "offset" in request.query_params:
            offset = _parse_positive_int(request.query_params.get("offset", 0), 0)
        else:
            offset = _decode_feed_cursor(request.query_params.get("cursor"), 0)
        since = timezone.now() - timedelta(days=10)
        now = timezone.now()
        query = str(request.query_params.get("q") or "").strip().lower()

        source_param = (
            request.query_params.get("source_type")
            or request.query_params.get("code")
            or ""
        ).strip().lower()
        raw_tokens = [token.strip() for token in source_param.split(",") if token.strip()]
        source_type_map = {
            "market": BroadcastSourceType.MARKET_PRODUCT,
            "market_product": BroadcastSourceType.MARKET_PRODUCT,
            "market_service": BroadcastSourceType.MARKET_SERVICE,
            "market_all": [BroadcastSourceType.MARKET_PRODUCT, BroadcastSourceType.MARKET_SERVICE],
            "broadcast_feed_entry": BroadcastSourceType.BROADCAST_FEED_ENTRY,
            "broadcast_channel": BroadcastSourceType.BROADCAST_CHANNEL,
            "channel_content": BroadcastSourceType.CHANNEL_CONTENT,
            "channel": [BroadcastSourceType.BROADCAST_CHANNEL, BroadcastSourceType.CHANNEL_CONTENT, BroadcastSourceType.CHANNEL_MESSAGE],
            "education": BroadcastSourceType.EDUCATION_BROADCAST,
            "education_broadcast": BroadcastSourceType.EDUCATION_BROADCAST,
            "healthcare": BroadcastSourceType.COMMUNITY_POST,  # ensure fallback
        }
        resolved_sources: list[str] = []
        for token in raw_tokens:
            value = source_type_map.get(token)
            if isinstance(value, (list, tuple)):
                resolved_sources.extend(value)
            elif value:
                resolved_sources.append(value)
        resolved_source_set = set(resolved_sources)

        def _include_source(source_type: str) -> bool:
            return not resolved_source_set or source_type in resolved_source_set
        hidden_ids = {
            str(value).strip()
            for value in ((getattr(request.user, "preferences", {}) or {}).get("hidden_broadcast_ids") or [])
            if str(value).strip()
        }
        muted_author_ids = {
            str(value).strip()
            for value in UserBlock.objects.filter(blocker=request.user).values_list(
                "blocked_id",
                flat=True,
            )
            if str(value).strip()
        }

        def _is_muted_author(raw_user_id: Any) -> bool:
            user_id = str(raw_user_id or "").strip()
            return bool(user_id and user_id in muted_author_ids)

        saved_ids = {
            str(value).strip()
            for value in ((getattr(request.user, "preferences", {}) or {}).get("saved_broadcast_ids") or [])
            if str(value).strip()
        }
        broadcast_items_qs = (
            BroadcastItem.objects
            .select_related("broadcasted_by", "broadcasted_by__profile")
            .filter(is_deleted=False, expires_at__gt=now)
        )
        if hidden_ids:
            broadcast_items_qs = broadcast_items_qs.exclude(id__in=list(hidden_ids))
        if muted_author_ids:
            broadcast_items_qs = broadcast_items_qs.exclude(broadcasted_by_id__in=list(muted_author_ids))
        if resolved_sources:
            broadcast_items_qs = broadcast_items_qs.filter(source_type__in=resolved_sources)
        else:
            broadcast_items_qs = broadcast_items_qs.exclude(source_type=BroadcastSourceType.MARKET_PRODUCT)


        broadcast_items = list(broadcast_items_qs.order_by("-broadcasted_at"))

        def _absolutize_avatar(value: Any) -> str | None:
            if value is None:
                return None
            text = str(value).strip()
            if not text:
                return None
            if text.startswith("http://") or text.startswith("https://"):
                return text
            if text.startswith("//"):
                return f"https:{text}"
            if text.startswith("/"):
                return build_absolute_url(request, text)
            media_url = str(getattr(settings, "MEDIA_URL", "/media/") or "/media/").strip()
            if not media_url.endswith("/"):
                media_url = f"{media_url}/"
            return build_absolute_url(request, f"{media_url}{text.lstrip('/')}")

        def _absolutize_media_url(value: Any) -> str | None:
            if value is None:
                return None
            text = str(value).strip()
            if not text:
                return None
            if text.startswith("http://") or text.startswith("https://"):
                return text
            if text.startswith("//"):
                return f"https:{text}"
            if text.startswith("/"):
                return build_absolute_url(request, text)
            media_url = str(getattr(settings, "MEDIA_URL", "/media/") or "/media/").strip()
            if not media_url.endswith("/"):
                media_url = f"{media_url}/"
            return build_absolute_url(request, f"{media_url}{text.lstrip('/')}")

        def _collect_product_images(prod: Product) -> list[str]:
            urls: list[str] = []
            seen: set[str] = set()

            def _add(raw: Any | None) -> None:
                if raw is None:
                    return
                abs_url = _absolutize_media_url(raw)
                if abs_url and abs_url not in seen:
                    seen.add(abs_url)
                    urls.append(abs_url)

            primary = getattr(prod, "effective_image_url", None)
            if primary:
                _add(primary)

            gallery_manager = getattr(prod, "gallery_images", None)
            iterable = gallery_manager.all() if gallery_manager is not None else []
            for img in iterable:
                try:
                    _add(img.image_file.url)
                except Exception:
                    continue
            return urls

        def _collect_service_images(service_obj: ShopService) -> list[str]:
            urls: list[str] = []
            seen: set[str] = set()

            def _add(raw: Any | None) -> None:
                if raw is None:
                    return
                abs_url = _absolutize_media_url(raw)
                if abs_url and abs_url not in seen:
                    seen.add(abs_url)
                    urls.append(abs_url)

            primary = getattr(service_obj, "effective_image_url", None)
            if primary:
                _add(primary)

            for img in getattr(service_obj, "images", []).all():
                try:
                    _add(img.image_file.url)
                except Exception:
                    continue
            return urls

        def _build_author_payload(user: User | None) -> dict[str, Any]:
            if not user:
                return {}
            profile = getattr(user, "profile", None)
            avatar_from_profile = ""
            if profile is not None:
                avatar_from_profile = str(getattr(profile, "avatar_url", "") or "").strip()
                if not avatar_from_profile and getattr(profile, "avatar_file", None):
                    try:
                        avatar_from_profile = str(profile.avatar_file.url or "").strip()
                    except Exception:
                        avatar_from_profile = ""
            display_name = (
                str(getattr(user, "display_name", "") or "").strip()
                or str(getattr(user, "username", "") or "").strip()
                or str(getattr(user, "phone", "") or "").strip()
                or "KIS user"
            )
            bio = ""
            profile_id = ""
            if profile is not None:
                bio = str(getattr(profile, "bio", "") or "").strip()
                profile_id = str(getattr(profile, "id", "") or "").strip()
            payload: dict[str, Any] = {
                "id": str(user.id),
                "display_name": display_name,
            }
            if profile_id:
                payload["profile_id"] = profile_id
            avatar_url = _absolutize_avatar(avatar_from_profile)
            if avatar_url:
                payload["avatar_url"] = avatar_url
            if bio:
                payload["bio"] = bio
            return payload

        author_user_cache: dict[str, User | None] = {}

        def _build_author_payload_from_id(raw_user_id: Any) -> dict[str, Any]:
            user_id = str(raw_user_id or "").strip()
            if not user_id:
                return {}
            if user_id not in author_user_cache:
                user_qs = User.objects
                if hasattr(User, "profile"):
                    user_qs = user_qs.select_related("profile")
                author_user_cache[user_id] = user_qs.filter(id=user_id).first()
            return _build_author_payload(author_user_cache.get(user_id))

        broadcast_ids = [item.id for item in broadcast_items]
        broadcast_item_map = {str(item.id): item for item in broadcast_items}
        reaction_counts = {
            row["broadcast_item_id"]: row["total"]
            for row in BroadcastReaction.objects.filter(broadcast_item_id__in=broadcast_ids)
            .values("broadcast_item_id")
            .annotate(total=models.Count("id"))
        }
        viewer_reactions = {
            row.broadcast_item_id: row.emoji
            for row in BroadcastReaction.objects.filter(
                broadcast_item_id__in=broadcast_ids,
                user=request.user,
            )
        }

        community_broadcasts = [
            item for item in broadcast_items
            if item.source_type == BroadcastSourceType.COMMUNITY_POST and _include_source(BroadcastSourceType.COMMUNITY_POST)
        ]
        partner_broadcasts = [
            item for item in broadcast_items
            if item.source_type == BroadcastSourceType.PARTNER_POST and _include_source(BroadcastSourceType.PARTNER_POST)
        ]
        channel_broadcasts = [
            item for item in broadcast_items
            if item.source_type == BroadcastSourceType.CHANNEL_MESSAGE and _include_source(BroadcastSourceType.CHANNEL_MESSAGE)
        ]
        market_broadcasts = [
            item for item in broadcast_items
            if item.source_type == BroadcastSourceType.MARKET_PRODUCT and _include_source(BroadcastSourceType.MARKET_PRODUCT)
        ]
        service_broadcasts = [
            item for item in broadcast_items
            if item.source_type == BroadcastSourceType.MARKET_SERVICE and _include_source(BroadcastSourceType.MARKET_SERVICE)
        ]
        profile_broadcasts = [
            item for item in broadcast_items
            if item.source_type == BroadcastSourceType.BROADCAST_FEED_ENTRY and _include_source(BroadcastSourceType.BROADCAST_FEED_ENTRY)
        ]
        promoted_channel_broadcasts = [
            item for item in broadcast_items
            if item.source_type == BroadcastSourceType.BROADCAST_CHANNEL and _include_source(BroadcastSourceType.BROADCAST_CHANNEL)
        ]
        channel_content_broadcasts = [
            item for item in broadcast_items
            if item.source_type == BroadcastSourceType.CHANNEL_CONTENT and _include_source(BroadcastSourceType.CHANNEL_CONTENT)
        ]

        channel_conversation_ids = list({str(item.conversation_id) for item in channel_broadcasts if item.conversation_id})
        channel_map = {}
        channel_members = set()
        if channel_conversation_ids:
            channels = Channel.objects.filter(
                conversation_id__in=channel_conversation_ids,
                is_archived=False,
            ).select_related("partner", "community")
            channel_map = {str(ch.conversation_id): ch for ch in channels}
            channel_members = set(
                ConversationMember.objects.filter(
                    user=request.user,
                    left_at__isnull=True,
                    is_blocked=False,
                    conversation_id__in=channel_conversation_ids,
                ).values_list("conversation_id", flat=True)
            )

        channel_message_ids = [item.source_id for item in channel_broadcasts]
        channel_messages = []
        if channel_conversation_ids and channel_message_ids:
            channel_messages = _fetch_channel_messages(
                channel_conversation_ids,
                since,
                limit,
                message_ids=channel_message_ids,
            )
        channel_message_map = {
            str(msg.get("id") or msg.get("_id")): msg
            for msg in channel_messages
        }
        channel_items = []
        for item in channel_broadcasts:
            msg = channel_message_map.get(str(item.source_id))
            if not msg:
                continue
            conversation_id = str(item.conversation_id or msg.get("conversationId") or "")
            channel = channel_map.get(conversation_id)
            if not channel:
                continue
            is_subscribed = str(conversation_id) in channel_members
            text_value = msg.get("text") or ""
            text_doc = msg.get("textDoc") or build_plain_text_document(text_value)
            text_plain = msg.get("textPlain") or text_value
            text_preview = msg.get("textPreview") or text_plain[:200]
            if _is_muted_author(msg.get("senderId")):
                continue
            channel_items.append(
                {
                    "id": str(item.id),
                    "source_type": "channel",
                    "source_id": str(item.source_id),
                    "conversation_id": conversation_id,
                    "title": channel.name,
                    "text": text_value,
                    "text_doc": text_doc,
                    "text_plain": text_plain,
                    "text_preview": text_preview,
                    "kind": msg.get("kind"),
                    "attachments": msg.get("attachments") or [],
                    "poll": msg.get("poll"),
                    "event": msg.get("event"),
                    "author": {"id": msg.get("senderId")},
                    "created_at": msg.get("createdAt"),
                    "broadcasted_at": item.broadcasted_at.isoformat(),
                    "expires_at": item.expires_at.isoformat(),
                    "comment_conversation_id": str(item.comment_conversation_id) if item.comment_conversation_id else None,
                    "reaction_count": reaction_counts.get(item.id, 0),
                    "viewer_reaction": viewer_reactions.get(item.id),
                    "source": {
                        "type": "channel",
                        "id": str(channel.id),
                        "name": channel.name,
                        "conversation_id": str(channel.conversation_id),
                        "allow_subscribe": True,
                        "is_subscribed": is_subscribed,
                        "can_open": is_subscribed,
                    },
                }
            )

        promoted_channel_items = []
        if promoted_channel_broadcasts:
            promoted_channel_ids = [item.source_id for item in promoted_channel_broadcasts]
            promoted_channels = BroadcastChannel.objects.filter(id__in=promoted_channel_ids, is_deleted=False, is_public=True)
            promoted_channel_map = {str(channel.id): channel for channel in promoted_channels}
            for item in promoted_channel_broadcasts:
                promoted_channel = promoted_channel_map.get(str(item.source_id))
                if not promoted_channel:
                    continue
                summary_text = promoted_channel.description or f"Explore @{promoted_channel.handle} on KIS Channels."
                attachments = []
                if promoted_channel.banner_url:
                    attachments.append({"url": promoted_channel.banner_url, "media_type": "image"})
                elif promoted_channel.avatar_url:
                    attachments.append({"url": promoted_channel.avatar_url, "media_type": "image"})
                promoted_channel_items.append(
                    {
                        "id": str(item.id),
                        "source_type": "broadcast_channel",
                        "source_id": str(promoted_channel.id),
                        "title": promoted_channel.display_name,
                        "text": summary_text,
                        "text_doc": summary_text,
                        "text_plain": summary_text,
                        "text_preview": summary_text[:200],
                        "attachments": attachments,
                        "created_at": promoted_channel.created_at.isoformat() if promoted_channel.created_at else item.created_at.isoformat(),
                        "broadcasted_at": item.broadcasted_at.isoformat(),
                        "expires_at": item.expires_at.isoformat(),
                        "comment_conversation_id": str(item.comment_conversation_id) if item.comment_conversation_id else None,
                        "reaction_count": reaction_counts.get(item.id, 0),
                        "viewer_reaction": viewer_reactions.get(item.id),
                        "source": {
                            "type": "broadcast_channel",
                            "id": str(promoted_channel.id),
                            "name": promoted_channel.display_name,
                            "handle": promoted_channel.handle,
                            "avatar_url": promoted_channel.avatar_url,
                            "banner_url": promoted_channel.banner_url,
                            "subscriber_count": promoted_channel.subscriber_count,
                            "content_count": promoted_channel.content_count,
                            "allow_subscribe": True,
                            "can_open": True,
                        },
                    }
                )

        channel_content_items = []
        if channel_content_broadcasts:
            channel_content_ids = [item.source_id for item in channel_content_broadcasts]
            contents = (
                ChannelContent.objects.select_related("channel")
                .prefetch_related("assets")
                .filter(
                    id__in=channel_content_ids,
                    is_deleted=False,
                    status=ChannelContent.Status.PUBLISHED,
                    visibility=ChannelContent.Visibility.PUBLIC,
                    channel__is_deleted=False,
                    channel__is_public=True,
                )
            )
            content_map = {str(content.id): content for content in contents}
            for item in channel_content_broadcasts:
                content = content_map.get(str(item.source_id))
                if not content:
                    continue
                payload = broadcast_item_payload_from_channel_content(content)
                attachments = payload.get("attachments") or []
                if not attachments and payload.get("attachment"):
                    attachments = [payload.get("attachment")]
                text_plain = payload.get("text_plain") or payload.get("summary") or ""
                channel_content_items.append(
                    {
                        "id": str(item.id),
                        "source_type": "channel_content",
                        "source_id": str(content.id),
                        "channel_content_id": str(content.id),
                        "title": payload.get("title") or content.channel.display_name,
                        "text": text_plain,
                        "text_doc": payload.get("text_doc") or text_plain,
                        "text_plain": text_plain,
                        "text_preview": payload.get("text_preview") or text_plain[:200],
                        "attachments": attachments,
                        "poll": (content.metadata or {}).get("poll"),
                        "event": (content.metadata or {}).get("event"),
                        "link": (content.metadata or {}).get("link"),
                        "composer_type": (content.metadata or {}).get("composer_type"),
                        "created_at": content.created_at.isoformat() if content.created_at else item.created_at.isoformat(),
                        "broadcasted_at": item.broadcasted_at.isoformat(),
                        "expires_at": item.expires_at.isoformat(),
                        "comment_conversation_id": str(item.comment_conversation_id) if item.comment_conversation_id else None,
                        "reaction_count": reaction_counts.get(item.id, 0),
                        "viewer_reaction": viewer_reactions.get(item.id),
                        "source": {
                            "type": "channel_content",
                            "id": str(content.channel_id),
                            "name": content.channel.display_name,
                            "handle": content.channel.handle,
                            "can_open": True,
                        },
                    }
                )

        community_post_ids = [item.source_id for item in community_broadcasts]
        community_posts = []
        if community_post_ids:
            community_posts = (
                CommunityPost.objects.select_related("community", "author")
                .filter(
                    id__in=community_post_ids,
                    status=CommunityPostStatus.PUBLISHED,
                    is_deleted=False,
                )
            )
        community_post_map = {str(post.id): post for post in community_posts}
        community_ids = {str(post.community_id) for post in community_posts}
        community_members = set()
        if community_ids:
            community_members = set(
                CommunityMembership.objects.filter(
                    user=request.user,
                    left_at__isnull=True,
                    is_banned=False,
                    community_id__in=community_ids,
                ).values_list("community_id", flat=True)
            )

        community_items = []
        for item in community_broadcasts:
            post = community_post_map.get(str(item.source_id))
            if not post:
                continue
            if _is_muted_author(post.author_id):
                continue
            is_member = str(post.community_id) in community_members
            text_plain = post.text_plain or ""
            community_items.append(
                {
                    "id": str(item.id),
                    "source_type": "community",
                    "source_id": str(post.id),
                    "title": post.community.name,
                    "text": text_plain,
                    "text_doc": post.text,
                    "text_plain": text_plain,
                    "text_preview": post.text_preview or text_plain[:200],
                    "attachments": post.attachments or [],
                    "poll": post.poll or None,
                    "event": post.event or None,
                    "author": {
                        "id": str(post.author_id),
                        "display_name": post.author.display_name or post.author.username,
                    },
                    "created_at": post.created_at.isoformat(),
                    "broadcasted_at": item.broadcasted_at.isoformat(),
                    "expires_at": item.expires_at.isoformat(),
                    "comment_conversation_id": str(item.comment_conversation_id) if item.comment_conversation_id else None,
                    "reaction_count": reaction_counts.get(item.id, 0),
                    "viewer_reaction": viewer_reactions.get(item.id),
                    "source": {
                        "type": "community",
                        "id": str(post.community_id),
                        "name": post.community.name,
                        "join_policy": post.community.join_policy,
                        "allow_subscribe": True,
                        "is_subscribed": is_member,
                        "is_member": is_member,
                        "can_open": is_member,
                    },
                }
            )

        partner_post_ids = [item.source_id for item in partner_broadcasts]
        partner_posts = []
        if partner_post_ids:
            partner_posts = (
                PartnerPost.objects.select_related("partner", "author")
                .filter(
                    id__in=partner_post_ids,
                    is_deleted=False,
                )
            )
        partner_post_map = {str(post.id): post for post in partner_posts}
        partner_ids = {str(post.partner_id) for post in partner_posts}
        partner_membership_status = {}
        partner_map = {}
        if partner_ids:
            partner_membership_status = {
                str(row["partner_id"]): row["status"]
                for row in PartnerMembership.objects.filter(
                    user=request.user,
                    partner_id__in=partner_ids,
                    status__in=[PartnerMembershipStatus.MEMBER, PartnerMembershipStatus.SUBSCRIBER],
                ).values("partner_id", "status")
            }
            partners = Partner.objects.filter(id__in=partner_ids).select_related("join_config")
            partner_map = {str(p.id): p for p in partners}

        partner_items = []
        for item in partner_broadcasts:
            post = partner_post_map.get(str(item.source_id))
            if not post:
                continue
            if _is_muted_author(post.author_id):
                continue
            partner = partner_map.get(str(post.partner_id))
            if not partner:
                continue
            membership_status = partner_membership_status.get(str(partner.id))
            is_member = membership_status in [PartnerMembershipStatus.MEMBER, PartnerMembershipStatus.SUBSCRIBER]
            is_subscribed = membership_status == PartnerMembershipStatus.SUBSCRIBER
            join_cfg = getattr(partner, "join_config", None)
            text_plain = post.text_plain or ""
            partner_items.append(
                {
                    "id": str(item.id),
                    "source_type": "partner",
                    "source_id": str(post.id),
                    "title": partner.name,
                    "text": text_plain,
                    "text_doc": post.text,
                    "text_plain": text_plain,
                    "text_preview": post.text_preview or text_plain[:200],
                    "attachments": post.attachments or [],
                    "poll": post.poll or None,
                    "event": post.event or None,
                    "author": {
                        "id": str(post.author_id),
                        "display_name": post.author.display_name or post.author.username,
                    },
                    "created_at": post.created_at.isoformat(),
                    "broadcasted_at": item.broadcasted_at.isoformat(),
                    "expires_at": item.expires_at.isoformat(),
                    "comment_conversation_id": str(item.comment_conversation_id) if item.comment_conversation_id else None,
                    "reaction_count": reaction_counts.get(item.id, 0),
                    "viewer_reaction": viewer_reactions.get(item.id),
                    "source": {
                        "type": "partner",
                        "id": str(partner.id),
                        "name": partner.name,
                        "is_member": is_member,
                        "is_subscribed": is_subscribed,
                        "can_open": is_member,
                        "allow_apply": bool(getattr(join_cfg, "allow_apply", True)) if join_cfg else True,
                        "allow_subscribe": (bool(getattr(join_cfg, "allow_subscribe", True)) if join_cfg else True)
                        and membership_status != PartnerMembershipStatus.MEMBER,
                        "auto_approve": bool(getattr(join_cfg, "auto_approve", False)) if join_cfg else False,
                        "methods": getattr(join_cfg, "methods", []) if join_cfg else [],
                    },
                }
            )

        token_set = set(raw_tokens)
        include_product_items = bool(token_set & {"market", "market_product", "market_all"})
        include_service_items = bool(token_set & {"market_service", "market_all"})

        market_ids = [item.source_id for item in market_broadcasts]
        market_products = []
        if market_ids and include_product_items:
            market_products = (
                Product.objects.filter(id__in=market_ids, is_deleted=False)
                .select_related("shop__landing_page")
                .prefetch_related("gallery_images")
            )
        market_map = {str(product.id): product for product in market_products}

        product_items = []
        for item in market_broadcasts:
            product = market_map.get(str(item.source_id))
            if not product:
                continue
            shop = product.shop
            if shop and _is_muted_author(shop.owner_id):
                continue
            text_plain = product.name or ""
            membership_discount_pct = getattr(shop, 'membership_discount_pct', 10) if shop else 10
            viewer_is_member = False
            if shop and request.user.is_authenticated:
                if request.user.id == shop.owner_id:
                    viewer_is_member = True
                else:
                    viewer_is_member = ShopTeamMember.objects.filter(shop=shop, user=request.user, is_active=True).exists()
            product_images = _collect_product_images(product)
            landing_page = getattr(shop, 'landing_page', None)
            landing_public = bool(landing_page and landing_page.is_public)
            landing_published = bool(landing_page and landing_page.is_published)

            serialized_product = ProductSerializer(product, context={'request': request}).data
            serialized_product['images'] = product_images
            try:
                serializable_product = json.loads(json.dumps(serialized_product, default=str))
            except (TypeError, ValueError):
                serializable_product = serialized_product
            product_items.append(
                {
                    "id": str(item.id),
                    "source_type": "market_product",
                    "source_id": str(product.id),
                    "title": shop.name if shop else "Market",
                    "text": text_plain,
                    "text_doc": build_plain_text_document(text_plain),
                    "text_plain": text_plain,
                    "text_preview": text_plain[:200],
                    # product_images was already computed above but never
                    # wired into the item the generic feed card actually
                    # reads (BroadcastFeedCard.tsx resolves its displayed
                    # image from item.attachments, not item.product.images)
                    # — images configured on the product never showed up in
                    # the feed even though they render fine on the shop's
                    # own product page, which reads product.images directly.
                    "attachments": [{"url": url, "type": "image"} for url in product_images],
                    "author": {"id": str(shop.owner_id) if shop else None},
                    "created_at": product.created_at.isoformat(),
                    "broadcasted_at": item.broadcasted_at.isoformat(),
                    "expires_at": item.expires_at.isoformat(),
                    "comment_conversation_id": str(item.comment_conversation_id) if item.comment_conversation_id else None,
                    "reaction_count": reaction_counts.get(item.id, 0),
                    "viewer_reaction": viewer_reactions.get(item.id),
                    "source": {
                        "type": "market",
                        "id": str(shop.id) if shop else None,
                        "name": shop.name if shop else "Market",
                        "can_open": True,
                        "viewer_is_member": viewer_is_member,
                        "membership_open": bool(getattr(shop, 'membership_public', False)),
                        "membership_discount_pct": membership_discount_pct,
                        "landing_is_public": landing_public,
                        "landing_is_published": landing_published,
                        "landing_page_is_public": landing_public,
                        "landing_page_is_published": landing_published,
                        "landingIsPublished": landing_published,
                        "landingPageIsPublished": landing_published,
                        "landing_page": {
                            "is_public": landing_public,
                            "is_published": landing_published,
                            "isPublished": landing_published,
                            "public": landing_public,
                        },
                    },
                    "product": serializable_product,
                }
            )

        service_items = []
        if service_broadcasts and include_service_items:
            service_ids = [item.source_id for item in service_broadcasts]
            market_services = (
                ShopService.objects.filter(id__in=service_ids, is_active=True)
                .select_related("shop__landing_page")
                .prefetch_related("images")
            )
            service_map = {str(service.id): service for service in market_services}
            booking_map: dict[str, dict[str, any]] = {}
            if request.user.is_authenticated:
                booking_qs = ServiceBooking.objects.filter(
                    service_id__in=service_ids,
                    user=request.user,
                    status__in=[
                        ServiceBooking.STATUS_PENDING,
                        ServiceBooking.STATUS_CONFIRMED,
                        ServiceBooking.STATUS_AWAITING_SATISFACTION,
                        ServiceBooking.STATUS_COMPLETED,
                        ServiceBooking.STATUS_DISPUTE,
                    ],
                ).select_related("escrow")
                for booking in booking_qs:
                    serialized = ServiceBookingSerializer(booking, context={"request": request}).data
                    booking_map[str(booking.service_id)] = serialized
            for item in service_broadcasts:
                service = service_map.get(str(item.source_id))
                if not service:
                    continue
                shop = service.shop
                if shop and _is_muted_author(shop.owner_id):
                    continue
                text_plain = service.name or ""
                membership_discount_pct = getattr(shop, 'membership_discount_pct', 10) if shop else 10
                viewer_is_member = False
                if shop and request.user.is_authenticated:
                    if request.user.id == shop.owner_id:
                        viewer_is_member = True
                    else:
                        viewer_is_member = ShopTeamMember.objects.filter(shop=shop, user=request.user, is_active=True).exists()
                service_images = _collect_service_images(service)
                landing_page = getattr(shop, 'landing_page', None)
                landing_public = bool(landing_page and landing_page.is_public)
                landing_published = bool(landing_page and landing_page.is_published)
                service_payload = {
                    "id": str(item.id),
                    "source_type": "market_service",
                    "source_id": str(service.id),
                        "title": shop.name if shop else "Market",
                        "text": text_plain,
                        "text_doc": build_plain_text_document(text_plain),
                        "text_plain": text_plain,
                        "text_preview": text_plain[:200],
                        # Same fix as market_product above — service_images
                        # was already computed but never reached
                        # item.attachments, which is what the feed card
                        # actually reads for its displayed image.
                        "attachments": [{"url": url, "type": "image"} for url in service_images],
                        "author": {"id": str(shop.owner_id) if shop else None},
                        "created_at": service.created_at.isoformat(),
                        "broadcasted_at": item.broadcasted_at.isoformat(),
                        "expires_at": item.expires_at.isoformat(),
                        "comment_conversation_id": str(item.comment_conversation_id) if item.comment_conversation_id else None,
                        "reaction_count": reaction_counts.get(item.id, 0),
                        "viewer_reaction": viewer_reactions.get(item.id),
                        "source": {
                            "type": "market",
                            "id": str(shop.id) if shop else None,
                            "name": shop.name if shop else "Market",
                            "can_open": True,
                            "viewer_is_member": viewer_is_member,
                            "membership_open": bool(getattr(shop, 'membership_public', False)),
                            "membership_discount_pct": membership_discount_pct,
                            "landing_is_public": landing_public,
                            "landing_is_published": landing_published,
                            "landing_page_is_public": landing_public,
                            "landing_page_is_published": landing_published,
                            "landingIsPublished": landing_published,
                            "landingPageIsPublished": landing_published,
                            "landing_page": {
                                "is_public": landing_public,
                                "is_published": landing_published,
                                "isPublished": landing_published,
                                "public": landing_public,
                            },
                        },
                    "service": {
                        "id": str(service.id),
                        "name": service.name,
                    "short_summary": service.short_summary,
                    "description": service.description,
                    "price": str(service.price),
                    "currency": KIS_COIN_CODE,
                    "delivery_modes": service.delivery_modes,
                    "duration_minutes": service.duration_minutes,
                    "compare_at_price": str(service.compare_at_price) if service.compare_at_price is not None else None,
                    "coverage": service.coverage,
                    "availability_rules": service.availability_rules,
                    "status": service.status,
                    "visibility": service.visibility,
                    "rating_avg": service.rating_avg,
                    "rating_count": service.rating_count,
                    "images": service_images,
                    "membership_discount_pct": membership_discount_pct,
                    },
                    "booking": booking_map.get(str(service.id)),
                }
                service_items.append(service_payload)

        market_items = []
        if include_product_items:
            market_items.extend(product_items)
        if include_service_items:
            market_items.extend(service_items)
        market_items.sort(key=lambda entry: entry.get("broadcasted_at") or "", reverse=True)

        profile_items = []
        healthcare_items = []
        for item in profile_broadcasts:
            metadata = item.metadata or {}
            entry = metadata.get("entry") or {}
            # _normalize_feed_attachments already merges entry.attachment +
            # entry.attachments and de-duplicates by path/video_id/url/name/id
            # (see _feed_attachment_identity) — building this list by hand
            # here duplicated the primary attachment whenever it also
            # appeared in entry.attachments (the common case: callers set
            # both attachment and attachments to the same item).
            attachments = _normalize_feed_attachments(request, entry)
            text_plain = entry.get("text_plain") or entry.get("summary") or entry.get("title") or ""
            profile_id = metadata.get("profile_id") or "main"
            profile_name = metadata.get("profile_name") or "My broadcast feed"
            author_payload = _build_author_payload(getattr(item, "broadcasted_by", None))
            if not author_payload:
                fallback_author_id = (
                    metadata.get("author_id")
                    or metadata.get("authorId")
                    or entry.get("author_id")
                    or entry.get("user_id")
                )
                author_payload = _build_author_payload_from_id(fallback_author_id)
            if not author_payload and isinstance(metadata.get("author"), dict):
                metadata_author = metadata.get("author") or {}
                metadata_author_from_user = _build_author_payload_from_id(
                    metadata_author.get("id") or metadata_author.get("user_id")
                )
                metadata_name = str(
                    metadata_author.get("display_name")
                    or metadata_author.get("name")
                    or ""
                ).strip()
                metadata_avatar = _absolutize_avatar(metadata_author.get("avatar_url"))
                metadata_bio = str(metadata_author.get("bio") or "").strip()
                author_payload = {
                    "id": str(metadata_author.get("id") or "") or None,
                    "display_name": metadata_name or "KIS user",
                }
                metadata_profile_id = str(metadata_author.get("profile_id") or metadata_author.get("profileId") or "").strip()
                if metadata_profile_id:
                    author_payload["profile_id"] = metadata_profile_id
                if metadata_avatar:
                    author_payload["avatar_url"] = metadata_avatar
                if metadata_bio:
                    author_payload["bio"] = metadata_bio
                if not author_payload.get("id"):
                    author_payload.pop("id", None)
                if metadata_author_from_user:
                    author_payload = {
                        **author_payload,
                        **metadata_author_from_user,
                    }
            if not author_payload and isinstance(entry.get("author"), dict):
                entry_author = entry.get("author") or {}
                entry_author_from_user = _build_author_payload_from_id(
                    entry_author.get("id") or entry_author.get("user_id")
                )
                entry_name = str(entry_author.get("display_name") or entry_author.get("name") or "").strip()
                entry_avatar = _absolutize_avatar(entry_author.get("avatar_url"))
                entry_bio = str(entry_author.get("bio") or "").strip()
                author_payload = {
                    "id": str(entry_author.get("id") or "") or None,
                    "display_name": entry_name or "KIS user",
                }
                entry_profile_id = str(entry_author.get("profile_id") or entry_author.get("profileId") or "").strip()
                if entry_profile_id:
                    author_payload["profile_id"] = entry_profile_id
                if entry_avatar:
                    author_payload["avatar_url"] = entry_avatar
                if entry_bio:
                    author_payload["bio"] = entry_bio
                if not author_payload.get("id"):
                    author_payload.pop("id", None)
                if entry_author_from_user:
                    author_payload = {
                        **author_payload,
                        **entry_author_from_user,
                    }
            if _is_muted_author(author_payload.get("id")):
                continue

            health_card = metadata.get("health_card") if isinstance(metadata.get("health_card"), dict) else {}
            if health_card:
                institution_id = str(health_card.get("institution_id") or "").strip()
                card_id = _normalize_health_card_id(health_card.get("card_id"))
                card_exists = False
                institution = None
                if institution_id and card_id:
                    _, _, _, _, institution = _find_health_institution_owner_context(institution_id)
                    if institution:
                        card_exists = any(
                            _health_card_ids_match(card.get('id'), card_id)
                            for card in _build_health_cards_from_institution(institution)
                        )

                if not card_exists:
                    BroadcastItem.objects.filter(id=item.id).update(is_deleted=True)
                    continue

                membership = _resolve_institution_membership_settings(institution or {})
                owner_contact = institution.get('owner_contact') if isinstance(institution.get('owner_contact'), dict) else {}
                owner_user_id = str(owner_contact.get('userId') or owner_contact.get('user_id') or '').strip()
                role, is_member, _ = _resolve_institution_member_role(request.user, institution or {}, owner_user_id=owner_user_id)
                can_manage = role in {'owner', 'admin', 'manager'}

                logo_url = ''
                if isinstance(institution, dict):
                    logo_url = str(
                        institution.get('landingLogoUrl')
                        or (institution.get('profile_editor') or {}).get('landingLogoUrl')
                        or (institution.get('profileEditor') or {}).get('landingLogoUrl')
                        or ''
                    ).strip()

                enriched_health_card = {
                    **health_card,
                    'card_id': card_id,
                    'membership_open': bool(membership.get('open')),
                    'membership_discount_pct': int(membership.get('discountPercent') or 10),
                    'viewer_is_member': bool(is_member),
                    'viewer_can_manage': bool(can_manage),
                    'institution_logo_url': logo_url,
                }

                service_name = str(health_card.get("service_name") or entry.get("title") or "Health Service")
                service_description = str(health_card.get("service_description") or text_plain or "")
                healthcare_items.append(
                    {
                        "id": str(item.id),
                        "broadcasted_by_id": str(item.broadcasted_by_id) if item.broadcasted_by_id else None,
                        "source_type": "healthcare",
                        "source_id": str(entry.get("id") or item.source_id),
                    "title": service_name,
                    "text": service_description,
                    "text_doc": _extract_rich_text_doc(entry),
                    "text_plain": service_description,
                    "text_preview": entry.get("text_preview") or service_description[:200],
                    "attachments": attachments,
                    "poll": entry.get("poll") or None,
                    "event": entry.get("event") or None,
                    "link": entry.get("link") or None,
                    "composer_type": entry.get("composer_type") or None,
                        "created_at": entry.get("created_at") or entry.get("updated_at") or item.broadcasted_at.isoformat(),
                        "broadcasted_at": item.broadcasted_at.isoformat(),
                        "expires_at": item.expires_at.isoformat(),
                        "comment_conversation_id": str(item.comment_conversation_id) if item.comment_conversation_id else None,
                        "reaction_count": reaction_counts.get(item.id, 0),
                        "viewer_reaction": viewer_reactions.get(item.id),
                        "health_card": enriched_health_card,
                        "source": {
                            "type": "healthcare",
                            "id": str(health_card.get("institution_id") or profile_id),
                            "name": str(health_card.get("institution_name") or profile_name),
                            "is_subscribed": True,
                            "can_open": True,
                        },
                    }
                )
                continue

            profile_items.append(
                {
                    "id": str(item.id),
                    "broadcasted_by_id": str(item.broadcasted_by_id) if item.broadcasted_by_id else None,
                    "source_type": "broadcast_profile",
                    "source_id": str(entry.get("id") or item.source_id),
                    "title": entry.get("title") or profile_name,
                    "text": text_plain,
                    "text_doc": _extract_rich_text_doc(entry),
                    "text_plain": text_plain,
                    "text_preview": entry.get("text_preview") or text_plain[:200],
                    "attachments": attachments,
                    "poll": entry.get("poll") or None,
                    "event": entry.get("event") or None,
                    "link": entry.get("link") or None,
                    "composer_type": entry.get("composer_type") or None,
                    "created_at": entry.get("created_at") or entry.get("updated_at") or item.broadcasted_at.isoformat(),
                    "broadcasted_at": item.broadcasted_at.isoformat(),
                    "expires_at": item.expires_at.isoformat(),
                    "comment_conversation_id": str(item.comment_conversation_id) if item.comment_conversation_id else None,
                    "reaction_count": reaction_counts.get(item.id, 0),
                    "viewer_reaction": viewer_reactions.get(item.id),
                    "author": author_payload,
                    "source": {
                        "type": "broadcast_profile",
                        "id": profile_id,
                        "name": profile_name,
                        "is_subscribed": True,
                        "can_open": True,
                    },
                }
            )

        education_profile_broadcasts = [
            item for item in broadcast_items
            if item.source_type == BroadcastSourceType.EDUCATION_PROFILE and _include_source(BroadcastSourceType.EDUCATION_PROFILE)
        ]
        course_broadcasts = [
            item for item in broadcast_items
            if item.source_type == BroadcastSourceType.EDUCATION_COURSE and _include_source(BroadcastSourceType.EDUCATION_COURSE)
        ]
        education_broadcasts = [
            item for item in broadcast_items
            if item.source_type == BroadcastSourceType.EDUCATION_BROADCAST and _include_source(BroadcastSourceType.EDUCATION_BROADCAST)
        ]
        course_items = []
        education_profile_items = []
        education_broadcast_items = []
        for item in education_profile_broadcasts:
            metadata = item.metadata or {}
            profile_id = metadata.get("profile_id") or ""
            profile_name = metadata.get("profile_name") or "Education Profile"
            summary_parts = []
            course_count = metadata.get("course_count")
            module_count = metadata.get("module_count")
            if course_count:
                summary_parts.append(f"{course_count} courses")
            if module_count:
                summary_parts.append(f"{module_count} modules")
            summary_text = metadata.get("description") or ", ".join(summary_parts) or profile_name
            education_profile_items.append(
                {
                    "id": str(item.id),
                    "source_type": "education_profile",
                    "source_id": profile_id or str(item.source_id),
                    "title": profile_name,
                    "text": summary_text,
                    "text_doc": summary_text,
                    "text_plain": summary_text,
                    "attachments": [],
                    "created_at": item.created_at.isoformat(),
                    "broadcasted_at": item.broadcasted_at.isoformat(),
                    "expires_at": item.expires_at.isoformat(),
                    "comment_conversation_id": str(item.comment_conversation_id) if item.comment_conversation_id else None,
                    "reaction_count": reaction_counts.get(item.id, 0),
                    "viewer_reaction": viewer_reactions.get(item.id),
                    "courses": metadata.get("courses") or [],
                    "modules": metadata.get("modules") or [],
                    "source": {
                        "type": "education_profile",
                        "id": profile_id,
                        "name": profile_name,
                        "can_open": True,
                    },
                }
            )
        for item in course_broadcasts:
            metadata = item.metadata or {}
            cover_url = metadata.get("cover_image") or metadata.get("cover_url")
            attachments = []
            if cover_url:
                attachments.append({"url": cover_url})
            course_items.append(
                {
                    "id": str(item.id),
                    "source_type": "education_course",
                    "source_id": str(item.source_id),
                    "title": metadata.get("title") or "Course",
                    "text": metadata.get("summary") or "",
                    "text_doc": metadata.get("summary") or "",
                    "text_plain": metadata.get("summary") or "",
                    "attachments": attachments,
                    "created_at": item.created_at.isoformat(),
                    "broadcasted_at": item.broadcasted_at.isoformat(),
                    "expires_at": item.expires_at.isoformat(),
                    "comment_conversation_id": str(item.comment_conversation_id) if item.comment_conversation_id else None,
                    "reaction_count": reaction_counts.get(item.id, 0),
                    "viewer_reaction": viewer_reactions.get(item.id),
                    "source": {
                        "type": metadata.get("source") or "education_profile",
                        "id": metadata.get("partner_id"),
                        "name": metadata.get("partner_name") or "Education",
                    },
                    "course": {
                        "id": metadata.get("id") or item.source_id,
                        "partner_id": metadata.get("partner_id"),
                        "partner_name": metadata.get("partner_name"),
                        "price_amount": metadata.get("price_amount"),
                        "price_currency": metadata.get("price_currency"),
                    },
                }
            )
        for item in education_broadcasts:
            metadata = item.metadata or {}
            cover_url = metadata.get("cover_image_url") or ""
            attachments = [{"url": cover_url}] if cover_url else []
            title = metadata.get("title") or "Education Broadcast"
            summary_text = metadata.get("summary") or metadata.get("description") or ""
            education_broadcast_items.append(
                {
                    "id": str(item.id),
                    "source_type": "education_broadcast",
                    "source_id": str(item.source_id),
                    "title": title,
                    "text": summary_text,
                    "text_doc": summary_text,
                    "text_plain": summary_text,
                    "attachments": attachments,
                    "created_at": item.created_at.isoformat(),
                    "broadcasted_at": item.broadcasted_at.isoformat(),
                    "expires_at": item.expires_at.isoformat(),
                    "comment_conversation_id": str(item.comment_conversation_id) if item.comment_conversation_id else None,
                    "reaction_count": reaction_counts.get(item.id, 0),
                    "viewer_reaction": viewer_reactions.get(item.id),
                    "source": {
                        "type": "education_institution",
                        "id": metadata.get("institution_id"),
                        "name": metadata.get("institution_name") or "Education Institution",
                        "can_open": True,
                    },
                    "education_broadcast": {
                        "id": metadata.get("broadcast_id") or item.source_id,
                        "kind": metadata.get("broadcast_kind"),
                        "institution_id": metadata.get("institution_id"),
                        "institution_name": metadata.get("institution_name"),
                        "source_entity_id": metadata.get("source_entity_id"),
                        "source_entity_type": metadata.get("source_entity_type"),
                        "starts_at": metadata.get("starts_at"),
                        "ends_at": metadata.get("ends_at"),
                        "timezone_name": metadata.get("timezone_name"),
                        "seat_limit": metadata.get("seat_limit"),
                        "booking_enabled": metadata.get("booking_enabled"),
                        "price_amount": metadata.get("price_amount"),
                        "price_currency": metadata.get("price_currency"),
                        "membership_policy": metadata.get("membership_policy"),
                        "status": metadata.get("status"),
                        "metadata": metadata.get("metadata") or {},
                    },
                }
            )

        items = (
            channel_items
            + community_items
            + partner_items
            + market_items
            + promoted_channel_items
            + channel_content_items
            + profile_items
            + healthcare_items
            + education_profile_items
            + course_items
            + education_broadcast_items
        )
        for item in items:
            item["viewer_saved"] = str(item.get("id") or "").strip() in saved_ids
        if query:
            def _matches_query(entry: dict[str, Any]) -> bool:
                haystack = " ".join(
                    [
                        str(entry.get("title") or ""),
                        str(entry.get("text_plain") or entry.get("text") or ""),
                        str((entry.get("source") or {}).get("name") or ""),
                        str((entry.get("author") or {}).get("display_name") or ""),
                    ]
                ).lower()
                return query in haystack

            items = [item for item in items if _matches_query(item)]
        # Feed-level duration filter (applies to channel_content items only)
        feed_min_duration = request.query_params.get("min_duration")
        feed_max_duration = request.query_params.get("max_duration")
        if feed_min_duration is not None or feed_max_duration is not None:
            def _duration_ok(entry: dict) -> bool:
                if entry.get("source_type") != "channel_content":
                    return True
                dur = int(entry.get("duration_seconds") or 0)
                if feed_min_duration is not None:
                    try:
                        if dur < int(feed_min_duration):
                            return False
                    except (TypeError, ValueError):
                        pass
                if feed_max_duration is not None:
                    try:
                        if dur > int(feed_max_duration):
                            return False
                    except (TypeError, ValueError):
                        pass
                return True
            items = [item for item in items if _duration_ok(item)]
        engagement_counts = _broadcast_engagement_counts([item.get("id") for item in items])
        _apply_broadcast_engagement_counts(items, engagement_counts)
        feed_sort = str(request.query_params.get("sort") or "new").strip().lower()
        profile = get_affinity_profile(request.user)
        metadata = {item["id"]: {"profile": profile} for item in items}

        def _engagement_score(item: dict) -> float:
            counts = item.get("engagement_counts") or {}
            raw = (
                (counts.get("views") or 0) * 1
                + (counts.get("reactions") or 0) * 3
                + (counts.get("comments") or 0) * 5
                + (counts.get("shares") or 0) * 4
            )
            created_raw = item.get("created_at") or item.get("broadcasted_at") or ""
            try:
                from django.utils.dateparse import parse_datetime
                dt = parse_datetime(str(created_raw))
                if dt:
                    age_hours = max(0.0, (timezone.now() - dt).total_seconds() / 3600)
                else:
                    age_hours = 24.0
            except Exception:
                age_hours = 24.0
            decay = (age_hours + 2.0) ** 1.5
            return raw / decay if decay > 0 else 0.0

        if feed_sort == "oldest":
            ranked_items = sorted(items, key=lambda e: e.get("broadcasted_at") or e.get("created_at") or "")
        elif feed_sort == "top":
            ranked_items = sorted(items, key=lambda e: (e.get("engagement_counts") or {}).get("reactions") or int(e.get("reaction_count") or 0), reverse=True)
        elif feed_sort == "trending":
            ranked_items = sorted(items, key=_engagement_score, reverse=True)
        else:
            ranked_items = rank_feed_items(items, request.user, feed_type="broadcast", metadata_map=metadata)
        log_feed_interaction(request.user, "broadcast", "feed_impression", weight=0.05)
        count = len(ranked_items)
        results = ranked_items[offset : offset + limit]
        for result in results:
            item = broadcast_item_map.get(str(result.get("id") or ""))
            if not item:
                continue
            try:
                _, created = _record_broadcast_engagement(
                    item=item,
                    user=request.user,
                    event_type=BroadcastEngagementEventType.IMPRESSION,
                    metadata={"source_type": result.get("source_type") or ""},
                )
                if created:
                    result["impression_count"] = int(result.get("impression_count") or 0) + 1
            except Exception:
                logger.exception("[broadcasts] failed to record feed impression for %s", item.id)
        next_offset = offset + limit if offset + limit < count else None
        previous_offset = offset - limit if offset > 0 else None
        current_cursor = _encode_feed_cursor(offset)
        next_cursor = _encode_feed_cursor(next_offset)
        previous_cursor = _encode_feed_cursor(previous_offset)

        return Response(
            {
                "count": count,
                "next": _build_page_url(next_offset),
                "previous": _build_page_url(previous_offset),
                "cursor": current_cursor,
                "next_cursor": next_cursor,
                "previous_cursor": previous_cursor,
                "results": results,
            }
        )


class BroadcastChannelMessageView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request):
        conversation_id = request.data.get("conversation_id") or request.data.get("conversationId")
        message_ids = request.data.get("message_ids") or request.data.get("messageIds") or []
        if not conversation_id or not isinstance(message_ids, list) or not message_ids:
            return Response({"detail": "conversation_id and message_ids are required."}, status=400)

        try:
            conversation = Conversation.objects.get(id=conversation_id)
        except Conversation.DoesNotExist:
            return Response({"detail": "Conversation not found."}, status=404)

        if conversation.type != ConversationType.CHANNEL:
            return Response({"detail": "Only channel conversations can broadcast messages."}, status=400)

        member = ConversationMember.objects.filter(
            conversation=conversation,
            user=request.user,
            left_at__isnull=True,
            is_blocked=False,
        ).first()
        if not member:
            return Response({"detail": "Join the channel to broadcast messages."}, status=403)

        conv_settings = ConversationSettings.objects.filter(conversation=conversation).first()
        if conv_settings and conv_settings.send_policy == ConversationSendPolicy.ADMINS_ONLY:
            if member.base_role not in (BaseConversationRole.OWNER, BaseConversationRole.ADMIN):
                return Response({"detail": "Only admins can broadcast from this channel."}, status=403)

        channel = Channel.objects.filter(conversation=conversation).first()

        valid_message_ids = [str(mid) for mid in message_ids if mid]
        if getattr(settings, "NEST_INTERNAL_URL", "") and getattr(settings, "NEST_INTERNAL_TOKEN", ""):
            fetched = _fetch_channel_messages(
                [str(conversation_id)],
                timezone.now() - timedelta(days=30),
                limit=len(valid_message_ids),
                message_ids=valid_message_ids,
                conversation_id=str(conversation_id),
            )
            valid_message_ids = [
                str(msg.get("id") or msg.get("_id"))
                for msg in fetched
                if str(msg.get("id") or msg.get("_id")) in valid_message_ids
            ]

        if not valid_message_ids:
            return Response({"detail": "No valid messages found for broadcast."}, status=400)

        created = []
        expires_at = timezone.now() + timedelta(days=10)
        for msg_id in valid_message_ids:
            item, _ = BroadcastItem.objects.update_or_create(
                source_type=BroadcastSourceType.CHANNEL_MESSAGE,
                source_id=str(msg_id),
                defaults={
                    "conversation_id": conversation.id,
                    "channel": channel,
                    "broadcasted_by": request.user,
                    "broadcasted_at": timezone.now(),
                    "expires_at": expires_at,
                    "is_deleted": False,
                },
            )
            created.append(str(item.id))

        return Response({"broadcast_ids": created}, status=200)


class BroadcastReactView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, pk=None):
        try:
            item = BroadcastItem.objects.get(id=pk, is_deleted=False)
        except BroadcastItem.DoesNotExist:
            return Response({"detail": "Broadcast item not found."}, status=404)

        emoji = request.data.get("emoji") or "❤️"
        existing = BroadcastReaction.objects.filter(broadcast_item=item, user=request.user).first()
        reacted = True
        if existing:
            if existing.emoji == emoji:
                existing.delete()
                reacted = False
            else:
                existing.emoji = emoji
                existing.save(update_fields=["emoji"])
        else:
            BroadcastReaction.objects.create(broadcast_item=item, user=request.user, emoji=emoji)

        count = BroadcastReaction.objects.filter(broadcast_item=item).count()
        return Response(
            {"reacted": reacted, "emoji": emoji, "count": count},
            status=200,
        )


