class BroadcastSaveView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, pk=None):
        try:
            item = BroadcastItem.objects.get(id=pk, is_deleted=False)
        except BroadcastItem.DoesNotExist:
            return Response({"detail": "Broadcast item not found."}, status=404)

        action = str(request.query_params.get("action") or request.data.get("action") or "save").strip().lower()
        prefs = dict(getattr(request.user, "preferences", {}) or {})
        saved_ids = [
            str(value).strip()
            for value in (prefs.get("saved_broadcast_ids") or [])
            if str(value).strip()
        ]
        item_id = str(item.id)

        if action == "unsave":
            saved_ids = [value for value in saved_ids if value != item_id]
            saved = False
        else:
            if item_id not in saved_ids:
                saved_ids.append(item_id)
            saved = True

        prefs["saved_broadcast_ids"] = saved_ids
        request.user.preferences = prefs
        request.user.save(update_fields=["preferences"])

        return Response({"saved": saved, "broadcast_id": item_id}, status=status.HTTP_200_OK)


class BroadcastHideView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, pk=None):
        try:
            item = BroadcastItem.objects.get(id=pk, is_deleted=False)
        except BroadcastItem.DoesNotExist:
            return Response({"detail": "Broadcast item not found."}, status=404)

        prefs = dict(getattr(request.user, "preferences", {}) or {})
        hidden_ids = [
            str(value).strip()
            for value in (prefs.get("hidden_broadcast_ids") or [])
            if str(value).strip()
        ]
        item_id = str(item.id)
        if item_id not in hidden_ids:
            hidden_ids.append(item_id)
            prefs["hidden_broadcast_ids"] = hidden_ids
            request.user.preferences = prefs
            request.user.save(update_fields=["preferences"])
        _write_broadcast_moderation_audit(
            actor=request.user,
            action="broadcast.hide",
            item=item,
            metadata={"hidden_for_user_id": str(request.user.id)},
        )

        return Response({"hidden": True, "broadcast_id": item_id}, status=status.HTTP_200_OK)


class BroadcastReportView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, pk=None):
        try:
            item = BroadcastItem.objects.get(id=pk, is_deleted=False)
        except BroadcastItem.DoesNotExist:
            return Response({"detail": "Broadcast item not found."}, status=404)

        reason = str(request.data.get("reason") or request.data.get("details") or "").strip()
        category = str(request.data.get("category") or request.data.get("type") or "broadcast_feed").strip()
        severity = str(request.data.get("severity") or "MEDIUM").strip().upper()
        valid_severities = {choice[0] for choice in ModerationFlag.SEVERITY}
        if severity not in valid_severities:
            severity = "MEDIUM"
        if not reason:
            raise ValidationError({"reason": "A report reason is required."})

        flag = ModerationFlag.objects.create(
            source="USER",
            target_type="POST",
            target_id=item.id,
            reporter_id=request.user.id,
            reason=reason,
            severity=severity,
            escalation_level="MODERATOR",
            tags={
                "surface": "broadcast_feed",
                "category": category[:64],
                "source_type": item.source_type,
                "source_id": str(item.source_id),
            },
        )
        _write_broadcast_moderation_audit(
            actor=request.user,
            action="broadcast.report",
            item=item,
            metadata={
                "flag_id": str(flag.id),
                "severity": severity,
                "category": category[:64],
            },
        )
        return Response(
            {
                "reported": True,
                "flag_id": str(flag.id),
                "status": flag.status,
            },
            status=status.HTTP_201_CREATED,
        )


