class BroadcastVideoUploadView(APIView):
    permission_classes = [IsAuthenticated]
    parser_classes = [MultiPartParser, FormParser]

    def post(self, request):
        serializer = BroadcastVideoUploadSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        file_obj = serializer.validated_data["file"]
        safety_decision, safety_scan = _record_upload_safety(request, file_obj, context="broadcast")
        title = serializer.validated_data.get("title") or os.path.splitext(file_obj.name or "")[0] or "Broadcast video"
        description = serializer.validated_data.get("description", "")
        thumbnail_url = serializer.validated_data.get("thumbnail_url", "")
        thumbnail_file = serializer.validated_data.get("thumbnail")
        if thumbnail_file:
            thumbnail_url = _store_thumbnail_upload(thumbnail_file)
        channel = None
        channel_id = serializer.validated_data.get("channel_id")
        if channel_id:
            channel = Channel.objects.filter(id=channel_id).first()
        relative_path, _ = _store_upload(file_obj, user=request.user)
        duration = _probe_video_duration_from_storage(relative_path)
        video_type = "short" if duration < LONG_VIDEO_MIN_SECONDS else "video"
        transcript_segments = _sanitize_transcript_segments(serializer.validated_data.get("transcript_segments", []))
        video = BroadcastVideo.objects.create(
            title=title,
            description=description,
            channel=channel,
            creator=request.user,
            video_url="",
            thumbnail_url=thumbnail_url or "",
            mime_type=file_obj.content_type or "",
            storage_path=relative_path,
            type=video_type,
            duration_seconds=int(round(duration)),
            transcript_segments=transcript_segments,
        )
        video.video_url = "" if safety_decision.quarantine else build_media_url(request, relative_path)
        ensure_local_thumbnail(video)
        video.save(update_fields=["video_url"])
        payload = BroadcastVideoSerializer(video, context={"request": request}).data
        payload["scan_status"] = safety_decision.status
        payload["quarantined"] = safety_decision.quarantine
        payload["requires_review"] = safety_decision.requires_review
        payload["safety_scan_id"] = str(safety_scan.id)
        payload["safety"] = user_safe_upload_response(safety_decision)
        payload["processing_status"] = "pending_review" if safety_decision.requires_review or safety_decision.quarantine else "ready"
        payload["pipeline"] = prepare_channel_asset_payload(
            {
                "asset_type": "short_video" if video.type == "short" else "video",
                "url": payload.get("video_url") or "",
                "storage_path": relative_path,
                "mime_type": file_obj.content_type or "",
                "size_bytes": getattr(file_obj, "size", 0) or 0,
                "duration_seconds": video.duration_seconds,
                "thumbnail_url": payload.get("thumbnail_url") or "",
                "processing_status": payload["processing_status"],
                "metadata": {
                    "safety": payload["safety"],
                    "safety_scan_id": str(safety_scan.id),
                    "transcript_segments": transcript_segments,
                },
            },
            content_type="short_video" if video.type == "short" else "video",
        ).get("metadata", {}).get("pipeline", {})
        return Response(payload, status=status.HTTP_201_CREATED)


class BroadcastVideoStreamView(APIView):
    permission_classes = [AllowAny]
    authentication_classes = []

    def get(self, request, video_id):
        video = get_object_or_404(BroadcastVideo, id=video_id, is_active=True)

        # Remote backends (S3/Supabase) have no local filesystem path — hand
        # the client a direct (signed, if private) URL instead of proxying
        # bytes through Django. S3 GetObject natively honors Range headers,
        # so seeking still works without reimplementing range-serving here.
        if not isinstance(default_storage, FileSystemStorage):
            if not default_storage.exists(video.storage_path):
                raise Http404("Video not found.")
            return HttpResponseRedirect(default_storage.url(video.storage_path))

        # Local dev fallback: real filesystem path (for open/exists).
        file_path = os.path.join(settings.MEDIA_ROOT, video.storage_path)

        if not os.path.exists(file_path):
            raise Http404("Video not found.")

        return self._serve_video(request, file_path, video)

    def _serve_video(self, request, file_path, video):
        file_size = os.path.getsize(file_path)
        range_header = request.headers.get("Range", "").strip()
        mime_type = video.mime_type or "video/mp4"

        if not range_header:
            resp = FileResponse(
                open(file_path, "rb"),
                content_type=mime_type,
            )
            resp["Content-Length"] = str(file_size)
            resp["Content-Disposition"] = f'inline; filename="{os.path.basename(file_path)}"'
            resp["X-Video-URL"] = build_media_url(request, video.storage_path)
            resp["Accept-Ranges"] = "bytes"
            return resp

        match = re.match(r"bytes=(\d+)-(\d*)", range_header)
        if not match:
            raise Http404("Invalid range header.")

        start = int(match.group(1))
        end = int(match.group(2)) if match.group(2) else file_size - 1
        if end >= file_size:
            end = file_size - 1
        length = end - start + 1

        with open(file_path, "rb") as fh:
            fh.seek(start)
            chunk = fh.read(length)

        resp = HttpResponse(
            chunk,
            status=206,
            content_type=mime_type,
        )
        resp["Content-Length"] = str(length)
        resp["Content-Range"] = f"bytes {start}-{end}/{file_size}"
        resp["Accept-Ranges"] = "bytes"
        resp["Content-Disposition"] = f'inline; filename="{os.path.basename(file_path)}"'
        resp["X-Video-URL"] = build_media_url(request, video.storage_path)
        return resp

