class LessonEnrollmentActionView(APIView):
    permission_classes = [IsAuthenticated]

    def get_lesson(self, lesson_id):
        return get_object_or_404(BroadcastLesson, id=lesson_id, is_public=True)

    def ensure_lesson_memberships(self, lesson, user, enrollment):
        modified_fields = set()
        if lesson.partner:
            membership, created = PartnerMembership.objects.get_or_create(
                partner=lesson.partner,
                user=user,
                defaults={
                    "status": PartnerMembershipStatus.MEMBER,
                    "lesson_access_only": True,
                },
            )
            if created and not membership.lesson_access_only:
                membership.lesson_access_only = True
                membership.save(update_fields=["lesson_access_only"])
            if enrollment.partner_membership_id != membership.id:
                enrollment.partner_membership_id = membership.id
                modified_fields.add("partner_membership_id")

        if lesson.community:
            membership, created = CommunityMembership.objects.get_or_create(
                community=lesson.community,
                user=user,
                defaults={
                    "role": CommunityRole.MEMBER,
                    "lesson_access_only": True,
                },
            )
            if created and not membership.lesson_access_only:
                membership.lesson_access_only = True
                membership.save(update_fields=["lesson_access_only"])
            if enrollment.community_membership_id != membership.id:
                enrollment.community_membership_id = membership.id
                modified_fields.add("community_membership_id")

        if modified_fields:
            enrollment.save(update_fields=list(modified_fields))

    def post(self, request, lesson_id):
        lesson = self.get_lesson(lesson_id)
        enrollment, created = LessonEnrollment.objects.get_or_create(
            lesson=lesson,
            user=request.user,
            defaults={"status": LessonEnrollmentStatus.ENROLLED},
        )
        self.ensure_lesson_memberships(lesson, request.user, enrollment)
        serializer = LessonEnrollmentSerializer(enrollment, context={"request": request})
        return Response(serializer.data, status=status.HTTP_201_CREATED if created else status.HTTP_200_OK)

    def delete(self, request, lesson_id):
        enrollment = get_object_or_404(
            LessonEnrollment,
            lesson_id=lesson_id,
            user=request.user,
        )
        enrollment.status = LessonEnrollmentStatus.CANCELLED
        enrollment.save(update_fields=["status"])
        return Response(status=status.HTTP_204_NO_CONTENT)


class EducationUploadInitiateView(APIView):
    """POST /api/v1/broadcasts/education/uploads/initiate/

    Education-specific entry point to the shared direct-to-S3 presigned
    upload handshake (apps/media/upload_intent.py) — see
    apps/broadcasts/education_media.py for why this needs its own initiate
    view rather than reusing the generic one: institution-management
    authorization (owner/manager/administrator membership) must be checked
    against a specific institution BEFORE a presigned URL is ever issued.

    Confirmation still goes through the existing, unmodified
    POST /api/v1/media/uploads/<uuid:upload_id>/confirm/.
    """

    permission_classes = [IsAuthenticated]

    def post(self, request):
        body = request.data
        result = education_media.initiate_education_upload(
            user=request.user,
            context=str(body.get("context") or "").strip(),
            filename=body.get("filename"),
            content_type=body.get("contentType") or body.get("content_type"),
            size_bytes=body.get("sizeBytes") or body.get("size_bytes"),
            institution_id=body.get("institutionId") or body.get("institution_id"),
        )
        return Response(result, status=status.HTTP_201_CREATED)


class EducationInstitutionListView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request):
        institutions = _education_institution_qs_for_user(request.user)
        serializer = EducationInstitutionSerializer(
            institutions,
            many=True,
            context={"request": request},
        )
        return Response({"institutions": serializer.data}, status=status.HTTP_200_OK)

    @transaction.atomic
    def post(self, request):
        edu_limit = _resolve_profile_limit(
            request.user,
            "education_profiles",
            legacy_required_tier="business pro",
            permission_message="Education institution profiles require Business Pro tier or higher.",
        )
        if edu_limit is not None:
            existing_count = EducationInstitution.objects.filter(owner=request.user).count()
            if existing_count >= edu_limit:
                raise ValidationError(
                    {"detail": f"Your current plan allows up to {edu_limit} education institution profile{'s' if edu_limit != 1 else ''}. Upgrade to create more."}
                )

        name = str(request.data.get("name") or "").strip()
        if not name:
            raise ValidationError({"name": "Institution name is required."})

        account_profile, _ = Profile.objects.get_or_create(user=request.user)
        branding, logo_intent = _normalize_education_branding_payload(request.data, user=request.user, institution=None)
        institution = EducationInstitution.objects.create(
            owner=request.user,
            profile=account_profile,
            name=name,
            description=str(request.data.get("description") or "").strip(),
            institution_type=_normalize_institution_type(request.data.get("institution_type")),
            membership_policy=_normalize_institution_membership_policy(request.data.get("membership_policy")),
            contact_email=str(request.data.get("contact_email") or "").strip(),
            contact_phone=str(request.data.get("contact_phone") or "").strip(),
            branding=branding,
            settings=request.data.get("settings") if isinstance(request.data.get("settings"), dict) else {},
            metadata=request.data.get("metadata") if isinstance(request.data.get("metadata"), dict) else {},
        )
        if logo_intent is not None:
            education_media.bind_education_media(intent=logo_intent, target_type="broadcasts.EducationInstitution", target_id=str(institution.id))
        EducationInstitutionMembership.objects.create(
            institution=institution,
            user=request.user,
            role=EducationInstitutionMembershipRole.OWNER,
            status=EducationInstitutionMembershipStatus.ACTIVE,
            created_by=request.user,
            decided_by=request.user,
            decided_at=timezone.now(),
        )
        institution = _get_education_institution_or_404(request.user, str(institution.id))
        serializer = EducationInstitutionSerializer(institution, context={"request": request})
        return Response({"institution": serializer.data}, status=status.HTTP_201_CREATED)


