class EducationInstitutionDetailView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request, institution_id: str):
        institution = _get_education_institution_or_404(request.user, institution_id)
        serializer = EducationInstitutionSerializer(institution, context={"request": request})
        return Response(
            _with_primary_detail_summary({"institution": serializer.data}, "institution"),
            status=status.HTTP_200_OK,
        )

    @transaction.atomic
    def patch(self, request, institution_id: str):
        institution = _get_education_institution_or_404(request.user, institution_id)
        _require_manage_institution_membership(request.user, institution)

        name = request.data.get("name")
        if isinstance(name, str) and name.strip():
            institution.name = name.strip()
        description = request.data.get("description")
        if isinstance(description, str):
            institution.description = description.strip()
        institution.institution_type = _normalize_institution_type(
            request.data.get("institution_type") or institution.institution_type
        )
        institution.membership_policy = _normalize_institution_membership_policy(
            request.data.get("membership_policy") or institution.membership_policy
        )
        contact_email = request.data.get("contact_email")
        if isinstance(contact_email, str):
            institution.contact_email = contact_email.strip()
        contact_phone = request.data.get("contact_phone")
        if isinstance(contact_phone, str):
            institution.contact_phone = contact_phone.strip()
        if isinstance(request.data.get("branding"), dict) or any(
            key in request.data
            for key in (
                "logo_url",
                "logoUrl",
                "logo_attachment",
                "logoAttachment",
                "image_url",
                "imageUrl",
                "institution_image_url",
                "institutionImageUrl",
                "banner_image_url",
                "bannerImageUrl",
                "cover_image_url",
                "coverImageUrl",
            )
        ):
            institution.branding, logo_intent = _normalize_education_branding_payload(
                request.data, existing=institution.branding or {}, user=request.user, institution=institution,
            )
            if logo_intent is not None:
                education_media.bind_education_media(intent=logo_intent, target_type="broadcasts.EducationInstitution", target_id=str(institution.id))
        if isinstance(request.data.get("settings"), dict):
            institution.settings = request.data.get("settings")
        if isinstance(request.data.get("metadata"), dict):
            institution.metadata = request.data.get("metadata")
        if "is_active" in request.data:
            institution.is_active = _to_bool(request.data.get("is_active"), default=True)
        institution.save()
        serializer = EducationInstitutionSerializer(institution, context={"request": request})
        return Response({"institution": serializer.data}, status=status.HTTP_200_OK)

    @transaction.atomic
    def delete(self, request, institution_id: str):
        institution = _get_education_institution_or_404(request.user, institution_id)
        membership = _require_manage_institution_membership(request.user, institution)
        if membership.role not in {
            EducationInstitutionMembershipRole.OWNER,
            EducationInstitutionMembershipRole.MANAGER,
        }:
            raise PermissionDenied("You do not have permission to delete this institution.")
        institution.delete()
        return Response(status=status.HTTP_204_NO_CONTENT)


class EducationInstitutionPayoutAccountConnectView(APIView):
    """Connects the institution's Flutterwave subaccount for paid-course
    settlement splitting. Only the platform's own FLW_SECRET_KEY is ever
    used (see _education_flutterwave_headers) — the institution never
    provides or stores a provider secret key, matching Flutterwave's
    Subaccounts API (https://developer.flutterwave.com/docs/subaccounts):
    creating a subaccount on our platform account returns a subaccount id
    that later payment links can reference in their `subaccounts` split
    array. Only that id (and display-safe fields) are persisted; the raw
    bank account number submitted here is never stored."""

    permission_classes = [IsAuthenticated]

    @transaction.atomic
    def post(self, request, institution_id: str):
        institution = _get_education_institution_or_404(request.user, institution_id)
        _require_manage_institution_membership(request.user, institution)
        if not getattr(settings, "FLW_SECRET_KEY", None):
            raise ValidationError({"detail": "Payment provider is not configured."})

        account_bank = str(request.data.get("account_bank") or "").strip()
        account_number = str(request.data.get("account_number") or "").strip()
        business_name = str(request.data.get("business_name") or institution.name).strip()
        country = str(request.data.get("country") or "NG").strip().upper()
        if not account_bank or not account_number:
            raise ValidationError({"detail": "Bank and account number are required."})

        institution.payout_account_status = EducationInstitutionPayoutAccountStatus.PENDING
        institution.save(update_fields=["payout_account_status", "updated_at"])

        try:
            response = requests.post(
                f"{FLW_BASE_URL}/subaccounts",
                json={
                    "account_bank": account_bank,
                    "account_number": account_number,
                    "business_name": business_name,
                    "business_email": institution.contact_email or request.user.email or "",
                    "country": country,
                    "split_type": "percentage",
                    # Flutterwave's own share of each split transaction;
                    # the platform's cut is applied per-transaction via the
                    # `subaccounts[].transaction_charge` on the payment
                    # link itself (see _create_flutterwave_payment_link),
                    # not here, so this default doesn't double-charge.
                    "split_value": 0,
                },
                headers=_education_flutterwave_headers(),
                timeout=30,
            )
            payload = response.json() if response.content else {}
        except (requests.RequestException, ValueError) as exc:
            institution.payout_account_status = EducationInstitutionPayoutAccountStatus.NOT_CONNECTED
            institution.save(update_fields=["payout_account_status", "updated_at"])
            raise ValidationError({"detail": f"Could not reach the payment provider: {exc}"})

        if response.status_code >= 400 or payload.get("status") != "success":
            institution.payout_account_status = EducationInstitutionPayoutAccountStatus.NOT_CONNECTED
            institution.save(update_fields=["payout_account_status", "updated_at"])
            message = payload.get("message") or "Unable to connect payout account."
            raise ValidationError({"detail": message})

        data = payload.get("data") or {}
        subaccount_id = str(data.get("subaccount_id") or data.get("id") or "")
        if not subaccount_id:
            institution.payout_account_status = EducationInstitutionPayoutAccountStatus.NOT_CONNECTED
            institution.save(update_fields=["payout_account_status", "updated_at"])
            raise ValidationError({"detail": "Payment provider did not return a subaccount id."})

        institution.flutterwave_subaccount_id = subaccount_id
        institution.payout_account_status = EducationInstitutionPayoutAccountStatus.ACTIVE
        institution.payout_account_name = business_name
        institution.payout_bank_last4 = account_number[-4:] if len(account_number) >= 4 else account_number
        institution.save(
            update_fields=[
                "flutterwave_subaccount_id",
                "payout_account_status",
                "payout_account_name",
                "payout_bank_last4",
                "updated_at",
            ]
        )
        return Response(
            {
                "payout_account_status": institution.payout_account_status,
                "payout_account_name": institution.payout_account_name,
                "payout_bank_last4": institution.payout_bank_last4,
            },
            status=status.HTTP_200_OK,
        )


class EducationInstitutionStripeConnectAccountView(APIView):
    """Connects the institution's Stripe Express account — the second
    supported payout rail alongside
    EducationInstitutionPayoutAccountConnectView's Flutterwave subaccount,
    using the shared apps.billing.stripe_connect helpers (unlike that
    Flutterwave view, which predates and duplicates the equivalent shared
    Flutterwave helper — this one uses the shared module from the start)."""

    permission_classes = [IsAuthenticated]

    def get(self, request, institution_id: str):
        from apps.billing.stripe_connect import refresh_account_status

        institution = _get_education_institution_or_404(request.user, institution_id)
        _require_manage_institution_membership(request.user, institution)

        if institution.stripe_account_id:
            fields = refresh_account_status(institution.stripe_account_id)
            for field_name, value in fields.items():
                setattr(institution, field_name, value)
            institution.save(update_fields=[*fields.keys(), "updated_at"])

        return Response(
            {
                "stripe_account_id": institution.stripe_account_id,
                "stripe_charges_enabled": institution.stripe_charges_enabled,
                "stripe_payouts_enabled": institution.stripe_payouts_enabled,
                "stripe_details_submitted": institution.stripe_details_submitted,
            }
        )

    @transaction.atomic
    def post(self, request, institution_id: str):
        from apps.billing.stripe_connect import create_account_onboarding_link, create_stripe_express_account, onboarding_redirect_urls

        institution = _get_education_institution_or_404(request.user, institution_id)
        _require_manage_institution_membership(request.user, institution)

        if not institution.stripe_account_id:
            country = str(request.data.get("country") or "US").strip().upper()
            institution.stripe_account_id = create_stripe_express_account(
                email=institution.contact_email or request.user.email or "", country=country,
            )
            institution.save(update_fields=["stripe_account_id", "updated_at"])

        refresh_url, return_url = onboarding_redirect_urls()
        onboarding_url = create_account_onboarding_link(
            account_id=institution.stripe_account_id, refresh_url=refresh_url, return_url=return_url,
        )
        return Response(
            {"onboarding_url": onboarding_url, "stripe_account_id": institution.stripe_account_id},
            status=status.HTTP_200_OK,
        )


class EducationInstitutionPartnerConnectView(APIView):
    """Attaches/detaches this institution to a Partner organization.
    Requires the caller to be able to manage BOTH the institution and the
    target partner - mirrors ShopPartnerConnectView (apps/commerce/views.py)
    and HealthInstitutionPartnerConnectView (apps/health_ops/views.py)
    exactly."""

    permission_classes = [IsAuthenticated]

    def post(self, request, institution_id: str):
        from apps.partners.models import Partner
        from apps.partners.services import partner_user_can_manage

        institution = _get_education_institution_or_404(request.user, institution_id)
        _require_manage_institution_membership(request.user, institution)

        partner_id = str(request.data.get("partner_id") or "").strip()
        if not partner_id:
            raise ValidationError({"partner_id": "This field is required."})
        partner = get_object_or_404(Partner, id=partner_id)
        if not partner_user_can_manage(partner, request.user):
            raise PermissionDenied("You do not have permission to attach institutions to this partner.")

        institution.partner = partner
        institution.save(update_fields=["partner"])
        return Response(EducationInstitutionSerializer(institution, context={"request": request}).data, status=status.HTTP_200_OK)

    def delete(self, request, institution_id: str):
        institution = _get_education_institution_or_404(request.user, institution_id)
        _require_manage_institution_membership(request.user, institution)

        institution.partner = None
        institution.save(update_fields=["partner"])
        return Response(EducationInstitutionSerializer(institution, context={"request": request}).data, status=status.HTTP_200_OK)


