# Moved to apps.accounts.tiers (shared by apps.websites too) — re-exported
# here under the original private name so every existing call site in
# this file keeps working unchanged.
from apps.accounts.tiers import resolve_profile_limit as _resolve_profile_limit


class ProfileCreationView(APIView):
    permission_classes = [IsAuthenticated]
    throttle_classes = [ScopedRateThrottle]
    throttle_scope = "broadcast_profile_create"

    def get(self, request):
        profiles = _load_user_profiles(request.user, include_member_institutions=True)
        return Response({'profiles': profiles}, status=status.HTTP_200_OK)

    def _charge_credits(self, user, amount, reference):
        if amount <= 0:
            return
        credit_account = get_credit_account(user)
        if credit_account.credits < amount:
            raise ValidationError({'credits': 'Insufficient credits to cover profile extras.'})
        record_ledger(
            user=user,
            kind='profile_create',
            amount_cents=0,
            credits_delta=-int(amount),
            reference=reference,
        )

    def _handle_broadcast_feed(self, user, profiles, payload):
        now = timezone.now()
        expires_at = now + timedelta(days=10)
        existing = profiles.get('broadcast_feed') or {}
        profiles['broadcast_feed'] = {
            'title': payload.get('title') or existing.get('title') or 'Scheduled broadcast feed',
            'profile_name': existing.get('profile_name') or payload.get('profile_name') or 'Broadcast feed',
            'notes': payload.get('notes') or existing.get('notes') or 'Feeds expire after 10 days.',
            'created_at': existing.get('created_at') or now.isoformat(),
            'updated_at': now.isoformat(),
            'expires_at': expires_at.isoformat(),
            'max_duration_days': 10,
            'feeds': existing.get('feeds', []),
        }
        return profiles['broadcast_feed']

    def _handle_health_profile(self, user, profiles, payload):
        institution_limit = _resolve_profile_limit(
            user,
            "health_profiles",
            legacy_required_tier="business pro",
            permission_message="Health profiles require Market Pro / Business Pro access.",
        )

        health = dict(profiles.get('health') or {})
        existing_institutions = _ensure_institution_data(health.get('institutions', []))
        institutions_payload = payload.get('institutions') or []
        if not institutions_payload:
            raise ValidationError({'institutions': 'At least one institution is required.'})

        sanitized_institutions = [inst for inst in [_sanitize_institution(entry) for entry in institutions_payload] if inst]
        if not sanitized_institutions:
            raise ValidationError({'institutions': 'Provide valid institution data.'})
        if institution_limit is not None:
            total_after_create = len(existing_institutions) + len(sanitized_institutions)
            if total_after_create > institution_limit:
                raise ValidationError(
                    {
                        "institutions": (
                            f"Your current tier allows up to {institution_limit} health institution profile"
                            f"{'' if institution_limit == 1 else 's'}."
                        )
                    }
                )

        extras_cost = max(0, len(existing_institutions) + len(sanitized_institutions) - 2) * 10
        employees_cost = sum(
            max(0, len(inst.get('employees', [])) - 5) * 5 for inst in sanitized_institutions
        )
        total_cost = extras_cost + employees_cost
        if total_cost > 0:
            self._charge_credits(user, total_cost, 'health_profile_extras')

        updated_institutions = existing_institutions + sanitized_institutions
        health['institutions'] = updated_institutions
        health = _merge_health_profile_core_fields(health, payload)
        health = _ensure_health_profile_structure(health)
        health['profile_name'] = payload.get('profile_name') or health.get('profile_name') or 'Health Profile'
        health['features'] = HEALTH_SYSTEM_FEATURES
        health['updated_at'] = timezone.now().isoformat()
        profiles['health'] = health
        return {
            'profile': health,
            'credit_spent': total_cost,
        }

    def _handle_market_profile(self, user, profiles, payload):
        _resolve_profile_limit(
            user,
            "market_profiles",
            legacy_required_tier="business",
            permission_message="Market profiles require Business tier or higher.",
        )
        market = dict(profiles.get('market') or {})
        existing_shops = _ensure_shop_data(market.get('shops', []))
        shop_entries = payload.get('shops') or []
        if not shop_entries:
            raise ValidationError({'shops': 'At least one shop is required to build a market profile.'})

        sanitized_shops = [shop for shop in (_sanitize_shop(entry) for entry in shop_entries) if shop]
        if not sanitized_shops:
            raise ValidationError({'shops': 'Provide at least one valid shop.'})

        product_cost = sum(max(0, _count_shop_products(shop) - 20) * 2 for shop in sanitized_shops)
        total_shops = len(existing_shops) + len(sanitized_shops)
        extras_cost = max(0, total_shops - 5) * 5
        total_cost = extras_cost + product_cost
        if total_cost > 0:
            self._charge_credits(user, total_cost, 'market_profile_slots')

        market['shops'] = existing_shops + sanitized_shops
        market = _apply_landing_builder_updates(market, payload)
        market = _ensure_market_profile_structure(market)
        market['profile_name'] = payload.get('profile_name') or market.get('profile_name') or 'Market Profile'
        market['updated_at'] = timezone.now().isoformat()
        profiles['market'] = market
        return {
            'profile': market,
            'credit_spent': total_cost,
        }

    def _handle_education_profile(self, user, profiles, payload):
        _resolve_profile_limit(
            user,
            "education_profiles",
            legacy_required_tier="business pro",
            permission_message="Education profiles require Business Pro tier or higher.",
        )
        education = dict(profiles.get('education') or {})
        existing_courses = _ensure_course_data(education.get('courses', []))
        course_entries = payload.get('courses') or []
        valid_courses = [course for course in (_sanitize_course(entry) for entry in course_entries) if course]
        if not valid_courses:
            raise ValidationError({'courses': 'Provide at least one course title.'})

        total_courses = len(existing_courses) + len(valid_courses)
        extra_courses = max(0, total_courses - 10)
        total_cost = extra_courses * 2
        if total_cost > 0:
            self._charge_credits(user, total_cost, 'education_profile_expand')

        education['courses'] = existing_courses + valid_courses
        education = _apply_landing_builder_updates(education, payload)
        education = _ensure_education_profile_structure(education)
        education['profile_name'] = payload.get('profile_name') or education.get('profile_name') or 'Education Profile'
        education['updated_at'] = timezone.now().isoformat()
        profiles['education'] = education
        return {
            'profile': education,
            'credit_spent': total_cost,
        }

    def post(self, request):
        profile_type = (request.data.get('profile_type') or '').strip().lower()
        payload = request.data.get('payload') or {}
        if not profile_type:
            raise ValidationError({'profile_type': 'Required.'})

        handler_mapping = {
            'broadcast_feed': self._handle_broadcast_feed,
            'health_profile': self._handle_health_profile,
            'market_profile': self._handle_market_profile,
            'education_profile': self._handle_education_profile,
        }
        handler = handler_mapping.get(profile_type)
        if not handler:
            raise ValidationError({'profile_type': 'Unknown profile type.'})

        profiles = _load_user_profiles(request.user)
        result = handler(request.user, profiles, payload)
        _save_user_profiles(request.user, profiles)
        profiles['health'] = _ensure_health_profile_structure(profiles.get('health') or {})
        profiles['market'] = _ensure_market_profile_structure(profiles.get('market') or {})
        profiles['education'] = _ensure_education_profile_structure(profiles.get('education') or {})
        return Response({'profiles': profiles, 'result': result}, status=status.HTTP_200_OK)


def _guess_media_type_from_mime(mime: str | None) -> str:
    if not mime:
        return 'file'
    mime = mime.lower()
    if mime.startswith('video/'):
        return 'video'
    if mime.startswith('audio/'):
        return 'audio'
    if mime.startswith('image/'):
        return 'image'
    if mime in {'application/pdf', 'text/plain', 'application/msword'}:
        return 'file'
    return 'file'


def _media_type_from_extension(name: str | None) -> str:
    ext = os.path.splitext(str(name or "").lower())[1]
    for media_type, rule in FEED_MEDIA_RULES.items():
        if ext in rule["extensions"]:
            return media_type
    return "file"


def _validate_feed_media_file(file_obj) -> str:
    name = str(getattr(file_obj, "name", "") or "")
    ext = os.path.splitext(name.lower())[1]
    mime = str(getattr(file_obj, "content_type", "") or "").lower()
    guessed_type = _guess_media_type_from_mime(mime)
    if guessed_type == "file" and ext:
        guessed_type = _media_type_from_extension(name)
    rule = FEED_MEDIA_RULES.get(guessed_type, FEED_MEDIA_RULES["file"])
    if ext not in rule["extensions"]:
        raise ValidationError({"detail": f"Unsupported {guessed_type} file extension."})
    if mime and mime not in rule["mimes"]:
        raise ValidationError({"detail": f"Unsupported {guessed_type} MIME type."})
    size = int(getattr(file_obj, "size", 0) or 0)
    if size > rule["max_bytes"]:
        raise ValidationError({"detail": f"{guessed_type.title()} file exceeds the allowed size."})
    return guessed_type


def _validate_remote_feed_attachment(attachment: dict[str, Any]) -> dict[str, Any]:
    normalized = dict(attachment)
    url = str(normalized.get("url") or normalized.get("uri") or "").strip()
    if url and not re.match(r"^https?://", url, flags=re.IGNORECASE):
        raise ValidationError({"detail": "Remote feed attachments must use http or https URLs."})
    media_type = str(
        normalized.get("media_type")
        or normalized.get("kind")
        or normalized.get("type")
        or normalized.get("mimeType")
        or normalized.get("mime_type")
        or ""
    ).lower()
    mime = str(normalized.get("mime_type") or normalized.get("mimeType") or "").lower()
    name = str(normalized.get("name") or normalized.get("originalName") or url or "").lower()
    if media_type == "short_video":
        normalized["kind"] = "short_video"
        media_type = "video"
    if media_type not in FEED_MEDIA_RULES:
        media_type = _guess_media_type_from_mime(mime)
    if media_type == "file" and name:
        media_type = _media_type_from_extension(name)
    rule = FEED_MEDIA_RULES.get(media_type, FEED_MEDIA_RULES["file"])
    ext = os.path.splitext(urlparse(name).path.lower())[1]
    if ext and ext not in rule["extensions"]:
        raise ValidationError({"detail": f"Unsupported remote {media_type} file extension."})
    if mime and mime not in rule["mimes"]:
        raise ValidationError({"detail": f"Unsupported remote {media_type} MIME type."})
    size = int(normalized.get("size") or 0)
    if size and size > min(rule["max_bytes"], FEED_REMOTE_ATTACHMENT_MAX_BYTES):
        raise ValidationError({"detail": f"Remote {media_type} attachment exceeds the allowed size."})
    raw_duration = (
        normalized.get("duration_seconds")
        or normalized.get("durationSeconds")
        or normalized.get("duration")
        or 0
    )
    try:
        duration_seconds = int(float(raw_duration or 0))
    except (TypeError, ValueError):
        duration_seconds = 0
    if normalized.get("kind") == "short_video" and duration_seconds > SHORT_VIDEO_MAX_SECONDS:
        raise ValidationError({"detail": "Short video attachments must be under 4 minutes."})
    thumbnail_url = (
        normalized.get("thumbnail_url")
        or normalized.get("thumbnailUrl")
        or normalized.get("thumbUrl")
        or normalized.get("poster_url")
        or normalized.get("posterUrl")
    )
    if thumbnail_url:
        thumbnail_url = str(thumbnail_url).strip()
        if thumbnail_url and not re.match(r"^https?://", thumbnail_url, flags=re.IGNORECASE):
            raise ValidationError({"detail": "Remote thumbnail URLs must use http or https."})
        normalized["thumbnail_url"] = thumbnail_url
        normalized["thumbUrl"] = thumbnail_url
    normalized["media_type"] = media_type
    normalized["validation_status"] = "validated"
    normalized["scan_status"] = normalized.get("scan_status") or "not_configured"
    if duration_seconds:
        normalized["duration_seconds"] = duration_seconds
    if mime:
        normalized["mime_type"] = mime
    return normalized


def _build_feed_attachment(request, file_obj):
    if not file_obj:
        return None
    media_type = _validate_feed_media_file(file_obj)
    safety_decision, safety_scan = _record_upload_safety(request, file_obj, context=request.data.get("context") or "broadcast")
    upload_user = request.user if request and getattr(request, "user", None) else None
    rel_path, bytes_written = _store_upload(file_obj, user=upload_user)
    url = "" if safety_decision.quarantine else (build_media_url(request, rel_path) if request else rel_path)

    attachment = {
        'url': url,
        'path': rel_path,
        'mime_type': file_obj.content_type or '',
        'name': file_obj.name,
        'size': bytes_written,
        'media_type': media_type,
        'validation_status': 'validated',
        'scan_status': safety_decision.status,
        'quarantined': safety_decision.quarantine,
        'requires_review': safety_decision.requires_review,
        'safety_scan_id': str(safety_scan.id),
        'safety': user_safe_upload_response(safety_decision),
    }

    if media_type == 'video' and request and getattr(request, 'user', None) and not safety_decision.quarantine:
        video = BroadcastVideo.objects.create(
            title=file_obj.name or 'Broadcast video',
            description='',
            channel=None,
            creator=request.user if request.user.is_authenticated else None,
            video_url=url,
            thumbnail_url='',
            mime_type=file_obj.content_type or '',
            storage_path=rel_path,
            type='video',
            duration_seconds=int(round(_probe_video_duration_from_storage(rel_path))),
        )
        attachment['stream_url'] = build_absolute_url(
            request,
            reverse('broadcasts:video-stream', kwargs={'video_id': str(video.id)}),
        )
        attachment['video_id'] = str(video.id)
        attachment['duration_seconds'] = video.duration_seconds
        attachment['thumbnail_url'] = video.thumbnail_url or ''

    attachment['processing_status'] = 'pending_review' if safety_decision.requires_review or safety_decision.quarantine else 'ready'
    attachment['pipeline'] = prepare_channel_asset_payload(
        {
            'asset_type': media_type,
            'url': attachment.get('url') or '',
            'storage_path': rel_path,
            'mime_type': file_obj.content_type or '',
            'size_bytes': bytes_written,
            'duration_seconds': attachment.get('duration_seconds'),
            'thumbnail_url': attachment.get('thumbnail_url') or attachment.get('thumbUrl') or '',
            'processing_status': attachment['processing_status'],
            'metadata': attachment,
        },
        content_type=media_type,
    ).get('metadata', {}).get('pipeline', {})

    return attachment


def _build_profile_attachment(request, file_obj):
    attachment = _build_feed_attachment(request, file_obj)
    if attachment:
        attachment['profile_attachment'] = True
    return attachment


def _collect_feed_files(request):
    files = []
    if hasattr(request.FILES, 'getlist'):
        files.extend(request.FILES.getlist('attachments'))
    else:
        files.extend(request.FILES.get('attachments') or [])
    media_file = request.FILES.get('media_file')
    if media_file:
        files.append(media_file)
    return [file for file in files if file]


def _parse_media_options(value: object | None) -> dict:
    if value is None:
        return {}
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
            if isinstance(parsed, dict):
                return parsed
        except (TypeError, ValueError):
            return {}
    if isinstance(value, dict):
        return value
    return {}


def _extract_rich_text_doc(entry: dict) -> dict | None:
    for key in ("text_doc", "text"):
        candidate = entry.get(key)
        if isinstance(candidate, dict) and candidate.get("type") == "doc":
            return candidate
    return None


def _parse_json_payload(value: object | None, fallback):
    if value is None:
        return fallback
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
            return parsed
        except (TypeError, ValueError):
            return fallback
    return value


def _normalize_composer_media_type(value: str, attachments: list[dict[str, Any]]) -> str:
    normalized = str(value or "").strip().lower()
    if normalized in {"image", "video", "audio", "file", "text"}:
        return normalized
    if normalized in {"document", "pdf", "doc", "docx"}:
        return "file"
    if normalized == "short_video":
        return "video"
    if normalized in {"poll", "event", "link"}:
        return "text"
    if attachments:
        return str(attachments[0].get("media_type") or "file").lower()
    return "text"


def _merge_client_attachments(
    uploaded: list[dict[str, Any]],
    client_payload: object | None,
) -> list[dict[str, Any]]:
    parsed = _parse_json_payload(client_payload, [])
    if not isinstance(parsed, list):
        return uploaded
    normalized_client = [
        _validate_remote_feed_attachment(item)
        for item in parsed
        if isinstance(item, dict)
    ]
    validate_attachment_metadata_for_safe_messaging(normalized_client)
    return uploaded + normalized_client


def _build_composer_fields(data) -> dict[str, Any]:
    text_doc = _parse_json_payload(data.get("text"), None)
    poll = _parse_json_payload(data.get("poll"), None)
    event = _parse_json_payload(data.get("event"), None)
    link = str(data.get("link") or "").strip()
    composer_type = str(data.get("composer_type") or data.get("composerType") or "").strip()
    channel_id = str(data.get("channel_id") or data.get("channelId") or "").strip()
    content_type = str(data.get("content_type") or data.get("contentType") or "").strip()
    visibility = str(data.get("visibility") or "").strip().lower()
    scheduled_at = str(data.get("scheduled_at") or data.get("scheduledAt") or "").strip()
    thumbnail_url = str(data.get("thumbnail_url") or data.get("thumbnail") or data.get("thumbnailUrl") or "").strip()
    playlist_ids = _parse_json_payload(data.get("playlist_ids") or data.get("playlistIds"), None)
    captions = _parse_json_payload(data.get("captions"), None)
    embed_allowed_raw = str(data.get("embed_allowed") or data.get("embedAllowed") or "").strip().lower()
    text_plain = str(data.get("text_plain") or data.get("textPlain") or "").strip()
    text_preview = str(data.get("text_preview") or data.get("textPreview") or "").strip()
    fields: dict[str, Any] = {}
    if text_doc is not None:
        fields["text"] = text_doc
        fields["text_doc"] = text_doc
    if text_plain:
        fields["text_plain"] = text_plain
    if text_preview:
        fields["text_preview"] = text_preview
    if isinstance(poll, dict):
        fields["poll"] = poll
    if isinstance(event, dict):
        fields["event"] = event
    if link:
        fields["link"] = link
    if composer_type:
        fields["composer_type"] = composer_type
    if channel_id:
        fields["channel_id"] = channel_id
    if content_type:
        fields["content_type"] = content_type
    if visibility:
        fields["visibility"] = visibility
    if scheduled_at:
        fields["scheduled_at"] = scheduled_at
    if thumbnail_url:
        fields["thumbnail_url"] = thumbnail_url
    if isinstance(playlist_ids, list):
        fields["playlist_ids"] = playlist_ids
    if captions is not None:
        fields["captions"] = captions
    if embed_allowed_raw in {"1", "true", "yes", "on"}:
        fields["embed_allowed"] = True
    elif embed_allowed_raw in {"0", "false", "no", "off"}:
        fields["embed_allowed"] = False
    return fields


def _build_feed_attachments(request, file_objects):
    attachments = []
    for file_obj in file_objects:
        attachment = _build_feed_attachment(request, file_obj)
        if attachment:
            attachments.append(attachment)
    return attachments


def _normalize_feed_attachment(request, attachment: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(attachment, dict):
        return None

    normalized = dict(attachment)
    rel_path = str(normalized.get("path") or "").strip()
    raw_url = str(normalized.get("url") or "").strip()
    media_type = str(normalized.get("media_type") or "").strip().lower()
    video_id = str(normalized.get("video_id") or "").strip()

    if rel_path:
        normalized["url"] = build_media_url(request, rel_path)
    elif raw_url:
        parsed = urlparse(raw_url)
        candidate_path = parsed.path or raw_url
        normalized["url"] = build_absolute_url(request, candidate_path)

    if media_type == "video" and video_id:
        normalized["stream_url"] = build_absolute_url(
            request,
            reverse("broadcasts:video-stream", kwargs={"video_id": video_id}),
        )

    return normalized


def _feed_attachment_identity(attachment: dict[str, Any] | None) -> str:
    if not isinstance(attachment, dict):
        return ""
    return str(
        attachment.get("path")
        or attachment.get("video_id")
        or attachment.get("url")
        or attachment.get("name")
        or attachment.get("id")
        or ""
    ).strip()


def _normalize_feed_attachments(request, entry: dict[str, Any] | None) -> list[dict[str, Any]]:
    if not isinstance(entry, dict):
        return []

    normalized_items: list[dict[str, Any]] = []
    seen: set[str] = set()
    raw_items: list[dict[str, Any]] = []
    primary_attachment = entry.get("attachment")
    if isinstance(primary_attachment, dict):
        raw_items.append(primary_attachment)
    raw_items.extend(item for item in (entry.get("attachments") or []) if isinstance(item, dict))

    for raw_item in raw_items:
        normalized_attachment = _normalize_feed_attachment(request, raw_item)
        if not normalized_attachment:
            continue
        identity = _feed_attachment_identity(normalized_attachment)
        if identity and identity in seen:
            continue
        if identity:
            seen.add(identity)
        normalized_items.append(normalized_attachment)
    return normalized_items


def _normalize_feed_entry(request, entry: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(entry, dict):
        return None

    normalized = dict(entry)
    normalized_attachments = _normalize_feed_attachments(request, normalized)
    normalized["attachments"] = normalized_attachments
    normalized["attachment"] = normalized_attachments[0] if normalized_attachments else None
    entry_id = str(normalized.get("id") or "").strip()
    if entry_id and not normalized.get("channel_content_id"):
        try:
            content = ChannelContent.objects.only("id").filter(legacy_feed_entry_id=entry_id).first()
        except (TypeError, ValueError):
            content = None
        if content:
            normalized["channel_content_id"] = str(content.id)

    return normalized


MEDIA_OPTION_DEFAULTS: dict[str, dict] = {
    'video': {
        'thumbnailAttachmentKey': '',
        'thumbnailLabel': '',
        'autoPlay': False,
        'showBadge': True,
    },
    'audio': {
        'waveformStyle': 'classic',
        'episodeNotes': '',
        'audioMood': 'uplifting',
        'hasTranscript': True,
    },
    'image': {
        'borderStyle': 'none',
        'layout': 'portrait',
        'captionTone': '',
        'overlayColor': 'transparent',
    },
    'file': {
        'categoryLabel': 'General resources',
        'secureDownload': False,
        'visibilityNote': '',
        'expiryDays': '7',
    },
    'text': {
        'bold': False,
        'italic': False,
        'underline': False,
        'strikethrough': False,
        'alignment': 'left',
        'fontSize': 'md',
        'highlightColor': 'transparent',
    },
}


def _merge_media_options(media_type: str, existing: dict | None) -> dict:
    defaults = dict(MEDIA_OPTION_DEFAULTS.get(media_type, MEDIA_OPTION_DEFAULTS['text']))
    if not isinstance(existing, dict):
        return defaults
    for key, value in existing.items():
        if key in defaults:
            defaults[key] = value
    return defaults


def _resolve_feed_entry(user, entry_id: str) -> dict:
    profiles = _load_user_profiles(user)
    profile = profiles.get('broadcast_feed')
    if not profile:
        raise ValidationError({'detail': 'Create a broadcast feed profile first.'})
    resolved = resolve_feed_entry(profile, entry_id)
    return {
        'profiles': profiles,
        'profile': resolved.profile,
        'feeds': resolved.feeds,
        'index': resolved.index,
        'entry': resolved.entry,
    }


def _resolve_feed_entry_for_request(request, entry_id: str) -> dict:
    resolved = _resolve_feed_entry(request.user, entry_id)
    normalized_entry = _normalize_feed_entry(request, resolved["entry"])
    if normalized_entry:
        resolved["entry"] = normalized_entry
        profile, feeds, _ = replace_feed_entry(
            resolved["profile"],
            entry_id,
            lambda _entry: normalized_entry,
        )
        resolved["feeds"] = feeds
        resolved["profile"] = profile
        profiles = dict(resolved["profiles"])
        profiles["broadcast_feed"] = profile
        resolved["profiles"] = profiles
    return resolved


def _sync_broadcast_feed_entry_snapshot(user, profile: dict | None, entry: dict | None):
    if not user or not entry:
        return None
    entry_id = str((entry or {}).get("id") or "").strip()
    if not entry_id:
        return None

    profile_row = getattr(user, "profile", None)
    profile_id = str(getattr(profile_row, "id", "") or "").strip() if profile_row is not None else ""
    avatar_url = str(getattr(profile_row, "avatar_url", "") or "").strip() if profile_row is not None else ""
    if profile_row is not None and not avatar_url and getattr(profile_row, "avatar_file", None):
        try:
            avatar_url = str(profile_row.avatar_file.url or "").strip()
        except Exception:
            avatar_url = ""

    item = BroadcastItem.objects.filter(
        source_type=BroadcastSourceType.BROADCAST_FEED_ENTRY,
        source_id=entry_id,
        broadcasted_by=user,
        is_deleted=False,
    ).first()
    if not item:
        return None

    content = sync_channel_content_from_feed_entry(user, profile, entry, broadcast_item=item)
    if content:
        entry = {**entry, "channel_content_id": str(content.id)}

    item.metadata = {
        "entry": entry,
        "profile_id": str((profile or {}).get("id") or "main"),
        "profile_name": (profile or {}).get("name") or (profile or {}).get("label") or "My broadcast feed",
        "author": {
            "id": str(user.id),
            "profile_id": profile_id or None,
            "display_name": str(user.display_name or user.username or user.phone or "KIS user"),
            "avatar_url": avatar_url,
            "bio": str(getattr(profile_row, "bio", "") or "").strip() if profile_row is not None else "",
            },
    }
    if content:
        item.metadata["channel_content_id"] = str(content.id)
    item.save(update_fields=["metadata", "updated_at"])
    return item


def _bootstrap_broadcast_feed_profile(user, profiles: dict[str, Any]) -> dict[str, Any]:
    now = timezone.now()
    profile = profiles.get('broadcast_feed') or {}
    bootstrapped = {
        'title': profile.get('title') or 'Scheduled broadcast feed',
        'profile_name': profile.get('profile_name') or 'Broadcast feed',
        'notes': profile.get('notes') or 'Feeds expire after 10 days.',
        'created_at': profile.get('created_at') or now.isoformat(),
        'updated_at': now.isoformat(),
        'expires_at': profile.get('expires_at') or (now + timedelta(days=10)).isoformat(),
        'max_duration_days': profile.get('max_duration_days') or 10,
        'feeds': list(profile.get('feeds') or []),
    }
    profiles['broadcast_feed'] = bootstrapped
    return bootstrapped


def _resolve_channel_lookup(handle_or_id: str, *, include_private: bool = False) -> BroadcastChannel:
    value = str(handle_or_id or "").strip().lstrip("@")
    query = BroadcastChannel.objects.select_related("owner_user").filter(is_deleted=False)
    if not include_private:
        query = query.filter(is_public=True)
    try:
        lookup_id = uuid.UUID(value)
    except (TypeError, ValueError):
        lookup_id = None
    if lookup_id:
        try:
            return query.get(id=lookup_id)
        except BroadcastChannel.DoesNotExist:
            pass
    return get_object_or_404(query, handle__iexact=value)


def _user_channel_role(user, channel: BroadcastChannel) -> str:
    if not getattr(user, "is_authenticated", False):
        return ""
    if getattr(user, "is_staff", False) or getattr(user, "is_superuser", False):
        return "staff"
    if channel.owner_user_id and str(channel.owner_user_id) == str(getattr(user, "id", "")):
        return BroadcastChannelRole.Role.OWNER
    return (
        BroadcastChannelRole.objects.filter(channel=channel, user=user)
        .order_by("created_at")
        .values_list("role", flat=True)
        .first()
        or ""
    )


def _user_can_manage_channel(user, channel: BroadcastChannel) -> bool:
    return _user_channel_role(user, channel) in {
        "staff",
        BroadcastChannelRole.Role.OWNER,
        BroadcastChannelRole.Role.MANAGER,
    }


class ChannelPayoutAccountConnectView(APIView):
    """Connects the channel's Flutterwave subaccount for direct-to-creator
    settlement splitting on tips/memberships/PPV — mirrors
    EducationInstitutionPayoutAccountConnectView above, using the shared
    apps.billing.payout_accounts helper. Only meaningful for
    owner_type=USER channels; institution-owned channels settle via their
    owning Shop/HealthInstitution/EducationInstitution's own payout
    account instead."""

    permission_classes = [IsAuthenticated]

    @transaction.atomic
    def post(self, request, channel_id: str):
        from apps.billing.payout_accounts import create_flutterwave_subaccount

        channel = get_object_or_404(BroadcastChannel, id=channel_id, is_deleted=False)
        if not _user_can_manage_channel(request.user, channel):
            raise PermissionDenied("You do not have permission to manage this channel.")
        if channel.owner_type != BroadcastChannel.OwnerType.USER:
            raise ValidationError(
                {"detail": "This channel settles through its owning organization's payout account instead."}
            )

        account_bank = str(request.data.get("account_bank") or "").strip()
        account_number = str(request.data.get("account_number") or "").strip()
        business_name = str(request.data.get("business_name") or channel.display_name).strip()
        country = str(request.data.get("country") or "NG").strip().upper()
        if not account_bank or not account_number:
            raise ValidationError({"detail": "Bank and account number are required."})

        channel.payout_account_status = BroadcastChannelPayoutAccountStatus.PENDING
        channel.save(update_fields=["payout_account_status", "updated_at"])

        owner_email = channel.owner_user.email if channel.owner_user else ""
        try:
            subaccount_id = create_flutterwave_subaccount(
                account_bank=account_bank,
                account_number=account_number,
                business_name=business_name,
                business_email=owner_email or "",
                country=country,
            )
        except ValidationError:
            channel.payout_account_status = BroadcastChannelPayoutAccountStatus.NOT_CONNECTED
            channel.save(update_fields=["payout_account_status", "updated_at"])
            raise

        channel.flutterwave_subaccount_id = subaccount_id
        channel.payout_account_status = BroadcastChannelPayoutAccountStatus.ACTIVE
        channel.payout_account_name = business_name
        channel.payout_bank_last4 = account_number[-4:] if len(account_number) >= 4 else account_number
        channel.save(
            update_fields=[
                "flutterwave_subaccount_id",
                "payout_account_status",
                "payout_account_name",
                "payout_bank_last4",
                "updated_at",
            ]
        )
        return Response(
            {
                "payout_account_status": channel.payout_account_status,
                "payout_account_name": channel.payout_account_name,
                "payout_bank_last4": channel.payout_bank_last4,
            },
            status=status.HTTP_200_OK,
        )


class ChannelStripeConnectAccountView(APIView):
    """Connects the channel's Stripe Express account — the second
    supported payout rail alongside ChannelPayoutAccountConnectView's
    Flutterwave subaccount, using the shared apps.billing.stripe_connect
    helpers. Same owner_type=USER-only scope as the Flutterwave view —
    institution-owned channels settle via their owning institution."""

    permission_classes = [IsAuthenticated]

    def get(self, request, channel_id: str):
        from apps.billing.stripe_connect import refresh_account_status

        channel = get_object_or_404(BroadcastChannel, id=channel_id, is_deleted=False)
        if not _user_can_manage_channel(request.user, channel):
            raise PermissionDenied("You do not have permission to manage this channel.")

        if channel.stripe_account_id:
            fields = refresh_account_status(channel.stripe_account_id)
            for field_name, value in fields.items():
                setattr(channel, field_name, value)
            channel.save(update_fields=[*fields.keys(), "updated_at"])

        return Response(
            {
                "stripe_account_id": channel.stripe_account_id,
                "stripe_charges_enabled": channel.stripe_charges_enabled,
                "stripe_payouts_enabled": channel.stripe_payouts_enabled,
                "stripe_details_submitted": channel.stripe_details_submitted,
            }
        )

    @transaction.atomic
    def post(self, request, channel_id: str):
        from apps.billing.stripe_connect import create_account_onboarding_link, create_stripe_express_account, onboarding_redirect_urls

        channel = get_object_or_404(BroadcastChannel, id=channel_id, is_deleted=False)
        if not _user_can_manage_channel(request.user, channel):
            raise PermissionDenied("You do not have permission to manage this channel.")
        if channel.owner_type != BroadcastChannel.OwnerType.USER:
            raise ValidationError(
                {"detail": "This channel settles through its owning organization's payout account instead."}
            )

        if not channel.stripe_account_id:
            country = str(request.data.get("country") or "US").strip().upper()
            owner_email = channel.owner_user.email if channel.owner_user else ""
            channel.stripe_account_id = create_stripe_express_account(email=owner_email or "", country=country)
            channel.save(update_fields=["stripe_account_id", "updated_at"])

        refresh_url, return_url = onboarding_redirect_urls()
        onboarding_url = create_account_onboarding_link(
            account_id=channel.stripe_account_id, refresh_url=refresh_url, return_url=return_url,
        )
        return Response(
            {"onboarding_url": onboarding_url, "stripe_account_id": channel.stripe_account_id},
            status=status.HTTP_200_OK,
        )


def _user_can_edit_content(user, content: ChannelContent) -> bool:
    return _user_channel_role(user, content.channel) in {
        "staff",
        BroadcastChannelRole.Role.OWNER,
        BroadcastChannelRole.Role.MANAGER,
        BroadcastChannelRole.Role.EDITOR,
    }


def _channel_broadcast_metadata(channel: BroadcastChannel) -> dict[str, Any]:
    return {
        "channel_id": str(channel.id),
        "handle": channel.handle,
        "display_name": channel.display_name,
        "description": channel.description,
        "avatar_url": _safe_public_media_url(channel.avatar_url),
        "banner_url": _safe_public_media_url(channel.banner_url),
        "category": channel.category,
        "subscriber_count": int(channel.subscriber_count or 0),
        "content_count": int(channel.content_count or 0),
    }


def _broadcast_channel_for_feed(channel: BroadcastChannel, user) -> BroadcastItem:
    item, _ = BroadcastItem.objects.update_or_create(
        source_type=BroadcastSourceType.BROADCAST_CHANNEL,
        source_id=str(channel.id),
        defaults={
            "metadata": _channel_broadcast_metadata(channel),
            "broadcasted_by": user,
            "broadcasted_at": timezone.now(),
            "expires_at": timezone.now() + timedelta(days=10),
            "is_deleted": False,
        },
    )
    return item


def _unbroadcast_channel_for_feed(channel: BroadcastChannel) -> int:
    return BroadcastItem.objects.filter(
        source_type=BroadcastSourceType.BROADCAST_CHANNEL,
        source_id=str(channel.id),
        is_deleted=False,
    ).update(is_deleted=True, expires_at=timezone.now())


def _broadcast_channel_content_for_feed(content: ChannelContent, user) -> BroadcastItem:
    metadata = broadcast_item_payload_from_channel_content(content)
    item, _ = BroadcastItem.objects.update_or_create(
        source_type=BroadcastSourceType.CHANNEL_CONTENT,
        source_id=str(content.id),
        defaults={
            "metadata": metadata,
            "broadcasted_by": user,
            "broadcasted_at": timezone.now(),
            "expires_at": timezone.now() + timedelta(days=10),
            "is_deleted": False,
        },
    )
    content.legacy_broadcast_item = item
    content.save(update_fields=["legacy_broadcast_item", "updated_at"])
    return item


def _unbroadcast_channel_content_for_feed(content: ChannelContent) -> int:
    updated = BroadcastItem.objects.filter(
        Q(id=content.legacy_broadcast_item_id) |
        Q(source_type=BroadcastSourceType.CHANNEL_CONTENT, source_id=str(content.id)),
        is_deleted=False,
    ).update(is_deleted=True, expires_at=timezone.now())
    if content.legacy_broadcast_item_id:
        content.legacy_broadcast_item = None
        content.save(update_fields=["legacy_broadcast_item", "updated_at"])
    return updated


def _user_can_view_content(user, content: ChannelContent) -> bool:
    if content.is_deleted:
        return False
    if content.visibility == ChannelContent.Visibility.PUBLIC and content.status == ChannelContent.Status.PUBLISHED:
        return content.channel.is_public and not content.channel.is_deleted
    return _user_can_edit_content(user, content)


def _safe_channel_handle_from_value(value: object) -> str:
    candidate = str(value or "").strip().lstrip("@").lower()
    candidate = re.sub(r"[^a-z0-9_-]+", "-", candidate).strip("-_")
    return candidate[:80]


def _content_type_from_request(value: object) -> str:
    raw = str(value or ChannelContentType.TEXT).strip().lower()
    if raw == "post":
        raw = ChannelContentType.TEXT
    if raw in ChannelContentType.values:
        return raw
    return ChannelContentType.TEXT


def _content_datetime_from_request(value: object):
    if not value:
        return None
    if isinstance(value, datetime):
        return value
    try:
        parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
        if timezone.is_naive(parsed):
            return timezone.make_aware(parsed, timezone.get_current_timezone())
        return parsed
    except (TypeError, ValueError):
        raise ValidationError({"scheduled_at": "Invalid date/time."})


def _live_stream_provider() -> str:
    return str(getattr(settings, "LIVE_STREAM_PROVIDER", os.getenv("LIVE_STREAM_PROVIDER", "disabled")) or "disabled").strip().lower()


def _live_provider_sandbox_enabled() -> bool:
    value = getattr(settings, "LIVE_STREAM_PROVIDER_SANDBOX_ENABLED", os.getenv("LIVE_STREAM_PROVIDER_SANDBOX_ENABLED", "False"))
    return str(value).strip().lower() in {"1", "true", "yes", "on"}


def _safe_live_dev_payload(channel_id, stream_id) -> dict[str, str]:
    if _live_stream_provider() != "disabled" and not _live_provider_sandbox_enabled():
        return {}
    base = str(getattr(settings, "LIVE_STREAM_DEV_BASE_URL", os.getenv("LIVE_STREAM_DEV_BASE_URL", "rtmp://localhost/live"))).rstrip("/")
    playback = str(getattr(settings, "LIVE_STREAM_DEV_PLAYBACK_BASE_URL", os.getenv("LIVE_STREAM_DEV_PLAYBACK_BASE_URL", "https://localhost/live"))).rstrip("/")
    return {
        "provider": "disabled",
        "provider_stream_id": str(stream_id),
        "ingest_url": f"{base}/{channel_id}",
        "playback_url": f"{playback}/{stream_id}.m3u8",
    }


def _hash_stream_key(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def _embeds_enabled() -> bool:
    value = getattr(settings, "KIS_EMBEDS_ENABLED", os.getenv("KIS_EMBEDS_ENABLED", "False"))
    return str(value).strip().lower() in {"1", "true", "yes", "on"}


def _embed_public_base_url(request=None) -> str:
    configured = str(getattr(settings, "KIS_PUBLIC_EMBED_BASE_URL", os.getenv("KIS_PUBLIC_EMBED_BASE_URL", "")) or "").strip().rstrip("/")
    if configured:
        return configured
    if request is not None:
        return request.build_absolute_uri("/").rstrip("/")
    return ""


# Moved to apps.core.public_web (shared by apps.websites too) — re-exported
# here under the original private names so every existing call site in
# this file, and any test patching `apps.broadcasts.views._safe_public_*`,
# keeps working unchanged.
from apps.core.public_web import (
    public_web_enabled as _public_web_enabled,
    public_web_base_url as _public_web_base_url,
    public_indexing_enabled as _public_indexing_enabled,
    safe_public_description as _safe_public_description,
    safe_public_media_url as _safe_public_media_url_raw,
    resolve_stale_media_url as _resolve_stale_media_url,
)


def _safe_public_media_url(value: str) -> str:
    """Wraps safe_public_media_url with resolve_stale_media_url so every
    public broadcasts payload (channel avatar/banner, content thumbnail,
    asset url/thumbnail) re-signs a fresh URL from a frozen presigned one
    on every read instead of trusting whatever TTL-limited URL was stored
    at upload time. Same fix apps.websites.kis_content_resolvers already
    applies when resolving broadcast content into website-builder pages —
    this file's own public endpoints (what KISTube's unauthenticated
    lib/kistube-api.ts fetchers hit) had been calling safe_public_media_url
    alone, which only validates/rejects, never refreshes, so any content
    older than the presigned URL's ~1hr TTL silently stopped rendering on
    KISTube specifically (the authenticated app-facing serializers resolve
    fresh some other way, e.g. ProfileSerializer's default_storage.url()
    pattern, which is why the app never showed this symptom)."""
    return _safe_public_media_url_raw(_resolve_stale_media_url(value))


def _content_is_public_web_safe(content: ChannelContent) -> bool:
    metadata = content.metadata if isinstance(content.metadata, dict) else {}
    if metadata.get("child_sensitive") or metadata.get("private_context") or metadata.get("contains_private_data"):
        return False
    return (
        content.visibility == ChannelContent.Visibility.PUBLIC
        and content.status == ChannelContent.Status.PUBLISHED
        and not content.is_deleted
        and content.channel.is_public
        and not content.channel.is_deleted
    )


def _public_channel_url(request, channel: BroadcastChannel) -> str:
    return f"{_public_web_base_url(request)}/channels/{channel.handle}"


def _public_content_url(request, content: ChannelContent) -> str:
    return f"{_public_web_base_url(request)}/channels/{content.channel.handle}/content/{content.id}"


def _safe_public_content_asset(content: ChannelContent) -> dict:
    asset = content.assets.order_by("sort_order", "created_at").first()
    if not asset:
        return {}
    return {
        "asset_type": asset.asset_type,
        "url": _safe_public_media_url(asset.url),
        "thumbnail_url": _safe_public_media_url(asset.thumbnail_url),
        "mime_type": asset.mime_type,
        "caption": asset.caption[:220],
        "width": asset.width,
        "height": asset.height,
        "duration_seconds": asset.duration_seconds,
    }


def _public_content_card(request, content: ChannelContent) -> dict:
    asset = _safe_public_content_asset(content)
    thumbnail = _safe_public_media_url(content.thumbnail_url) or asset.get("thumbnail_url") or asset.get("url") or ""
    title = content.title or content.text_plain[:80] or "KIS content"
    return {
        "id": str(content.id),
        "title": title[:220],
        "description": _safe_public_description(content.description, content.text_plain),
        "content_type": content.content_type,
        "thumbnail_url": thumbnail,
        "url": _public_content_url(request, content),
        "published_at": content.published_at.isoformat() if content.published_at else None,
        "stats": {
            "views": int((content.stats or {}).get("views") or 0),
            "shares": int((content.stats or {}).get("shares") or 0),
            "comments": int((content.stats or {}).get("comments") or 0),
        },
    }


def _public_channel_payload(request, channel: BroadcastChannel, *, include_contents: bool = True) -> dict:
    public_url = _public_channel_url(request, channel)
    description = _safe_public_description(channel.description)
    latest = []
    if include_contents:
        latest = [
            _public_content_card(request, item)
            for item in ChannelContent.objects.filter(
                channel=channel,
                status=ChannelContent.Status.PUBLISHED,
                visibility=ChannelContent.Visibility.PUBLIC,
                is_deleted=False,
            ).order_by("-published_at", "-created_at")[:12]
            if _content_is_public_web_safe(item)
        ]
    return {
        "type": "channel",
        "id": str(channel.id),
        "handle": channel.handle,
        "display_name": channel.display_name,
        "description": description,
        "avatar_url": _safe_public_media_url(channel.avatar_url),
        "banner_url": _safe_public_media_url(channel.banner_url),
        "category": channel.category,
        "language": channel.language,
        "country": channel.country,
        "subscriber_count": channel.subscriber_count,
        "content_count": channel.content_count,
        "trust_badges": channel.verification_badges if isinstance(channel.verification_badges, list) else [],
        "url": public_url,
        "seo": {
            "title": f"{channel.display_name} (@{channel.handle}) on KIS",
            "description": description or f"Watch and follow {channel.display_name} on KIS.",
            "canonical_url": public_url,
            "robots": "index,follow" if _public_indexing_enabled() else "noindex,nofollow",
        },
        "share_card": {
            "title": channel.display_name,
            "description": description,
            "image": _safe_public_media_url(channel.banner_url) or _safe_public_media_url(channel.avatar_url),
            "url": public_url,
        },
        "growth": {
            "referrals_enabled": bool(getattr(settings, "KIS_PUBLIC_REFERRALS_ENABLED", False)),
            "invite_url": f"{public_url}?ref=share",
        },
        "report": {
            "method": "POST",
            "url": request.build_absolute_uri(reverse("broadcasts:broadcast-channel-report", args=[channel.id])),
        },
        "latest_contents": latest,
    }


def _public_content_payload(request, content: ChannelContent) -> dict:
    if not _content_is_public_web_safe(content):
        raise Http404
    asset = _safe_public_content_asset(content)
    thumbnail = _safe_public_media_url(content.thumbnail_url) or asset.get("thumbnail_url") or asset.get("url") or ""
    public_url = _public_content_url(request, content)
    title = content.title or content.text_plain[:80] or "KIS content"
    description = _safe_public_description(content.description, content.text_plain)
    embed_url = request.build_absolute_uri(reverse("broadcasts:broadcast-channel-content-oembed", args=[content.id]))
    return {
        "type": "content",
        "id": str(content.id),
        "title": title[:220],
        "description": description,
        "content_type": content.content_type,
        "thumbnail_url": thumbnail,
        "asset": asset,
        "channel": _public_channel_payload(request, content.channel, include_contents=False),
        "url": public_url,
        "seo": {
            "title": f"{title[:160]} | KIS",
            "description": description,
            "canonical_url": public_url,
            "robots": "index,follow" if _public_indexing_enabled() else "noindex,nofollow",
        },
        "share_card": {
            "title": title[:220],
            "description": description,
            "image": thumbnail,
            "url": public_url,
        },
        "embed": {
            "oembed_url": embed_url,
            "enabled": _embeds_enabled(),
            "requires_policy_check": True,
        },
        "report": {
            "method": "POST",
            "url": request.build_absolute_uri(reverse("broadcasts:broadcast-channel-content-report", args=[content.id])),
        },
    }


def _embed_signing_secret() -> str:
    return str(getattr(settings, "KIS_EMBED_SIGNING_SECRET", os.getenv("KIS_EMBED_SIGNING_SECRET", "")) or "").strip()


def _embed_token_hash(token: str) -> str:
    secret = _embed_signing_secret()
    return hashlib.sha256(f"{secret}:{token}".encode("utf-8")).hexdigest()


def _request_domain(request) -> str:
    origin = request.headers.get("Origin") or request.headers.get("Referer") or ""
    parsed = urlparse(origin)
    return (parsed.hostname or "").lower()


def _domain_matches(domain: str, patterns: list) -> bool:
    if not domain:
        return False
    for raw in patterns or []:
        pattern = str(raw or "").strip().lower()
        if not pattern:
            continue
        if pattern == "*" or domain == pattern or domain.endswith(f".{pattern}"):
            return True
    return False


def _first_public_asset(content: ChannelContent) -> dict:
    asset = content.assets.order_by("sort_order", "created_at").first()
    if not asset:
        return {}
    return {
        "asset_type": asset.asset_type,
        "url": _safe_public_media_url(asset.url),
        "thumbnail_url": _safe_public_media_url(asset.thumbnail_url),
        "mime_type": asset.mime_type,
        "caption": asset.caption,
        "width": asset.width,
        "height": asset.height,
        "duration_seconds": asset.duration_seconds,
    }


def _check_embed_access(request, content: ChannelContent):
    if not _embeds_enabled():
        raise Http404
    policy, _ = ChannelEmbedPolicy.objects.get_or_create(channel=content.channel)
    if not policy.allow_embeds:
        raise PermissionDenied("Embeds are disabled for this channel.")
    domain = _request_domain(request)
    if domain and _domain_matches(domain, policy.blocked_domains):
        raise PermissionDenied("This domain is not allowed to embed this content.")
    if policy.allowed_domains and not _domain_matches(domain, policy.allowed_domains):
        raise PermissionDenied("This domain is not allowed to embed this content.")
    is_public = (
        content.visibility == ChannelContent.Visibility.PUBLIC
        and content.status == ChannelContent.Status.PUBLISHED
        and content.channel.is_public
        and not content.is_deleted
    )
    token = str(request.query_params.get("token") or request.headers.get("X-KIS-Embed-Token") or "").strip()
    requires_token = policy.require_signed_token or not is_public
    if requires_token:
        if not token:
            raise PermissionDenied("A valid embed token is required.")
        token_hash = _embed_token_hash(token)
        query = ChannelContentEmbed.objects.filter(content=content, token_hash=token_hash, is_active=True)
        query = query.filter(Q(expires_at__isnull=True) | Q(expires_at__gt=timezone.now()))
        if domain:
            query = query.filter(Q(domain="") | Q(domain__iexact=domain))
        if not query.exists():
            raise PermissionDenied("Invalid or expired embed token.")
    elif not is_public:
        raise Http404
    return policy, domain


def _embed_content_payload(request, content: ChannelContent, *, oembed: bool = False) -> dict:
    base_url = _embed_public_base_url(request)
    token = str(request.query_params.get("token") or "").strip()
    token_query = f"?token={quote(token)}" if token else ""
    embed_src = f"{base_url}/embed/content/{content.id}{token_query}"
    safe_embed_src = html_escape(embed_src, quote=True)
    thumbnail = _safe_public_media_url(content.thumbnail_url)
    asset = _first_public_asset(content)
    if not thumbnail:
        thumbnail = asset.get("thumbnail_url") or asset.get("url") or ""
    if oembed:
        return {
            "type": "video" if content.content_type in {ChannelContentType.VIDEO, ChannelContentType.SHORT_VIDEO, ChannelContentType.LIVE_STREAM, ChannelContentType.REPLAY} else "rich",
            "version": "1.0",
            "provider_name": "KIS",
            "provider_url": base_url,
            "title": content.title or content.text_plain[:80] or "KIS content",
            "author_name": content.channel.display_name,
            "author_url": f"{base_url}/channels/{content.channel.handle}",
            "thumbnail_url": thumbnail,
            "width": asset.get("width") or 560,
            "height": asset.get("height") or 315,
            "html": (
                f'<iframe src="{safe_embed_src}" width="560" height="315" '
                'frameborder="0" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe>'
            ),
        }
    return {
        "id": str(content.id),
        "title": content.title or content.text_plain[:80] or "KIS content",
        "description": content.description[:500],
        "content_type": content.content_type,
        "channel": BroadcastChannelSummarySerializer(content.channel, context={"request": request}).data,
        "thumbnail_url": thumbnail,
        "asset": asset,
        "text_plain_preview": content.text_plain[:500],
        "published_at": content.published_at.isoformat() if content.published_at else None,
        "dimensions": {"width": asset.get("width") or 560, "height": asset.get("height") or 315},
        "embed_url": embed_src,
        "embed_html": (
            f'<iframe src="{safe_embed_src}" width="560" height="315" '
            'frameborder="0" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe>'
        ),
    }


def _record_embed_impression(request, content: ChannelContent, domain: str):
    if not content.legacy_broadcast_item_id or not getattr(request.user, "is_authenticated", False):
        return
    window = timezone.now().strftime("%Y%m%d%H")
    BroadcastEngagementEvent.objects.get_or_create(
        broadcast_item_id=content.legacy_broadcast_item_id,
        user=request.user,
        event_type=BroadcastEngagementEventType.IMPRESSION,
        window_key=f"embed:{domain or 'unknown'}:{window}",
        defaults={"platform": "embed", "metadata": {"domain": domain}},
    )


def _channel_content_counts(content: ChannelContent) -> dict:
    stats = content.stats if isinstance(content.stats, dict) else {}
    return {
        "views": int(stats.get("views") or 0),
        "shares": int(stats.get("shares") or 0),
        "comments": int(stats.get("comments") or 0),
        "reactions": int(stats.get("reactions") or 0),
        "saves": int(stats.get("saves") or 0),
    }


def _set_channel_content_count(content_id, key: str, value: int):
    content = ChannelContent.objects.only("id", "stats").filter(id=content_id).first()
    if not content:
        return {}
    stats = content.stats if isinstance(content.stats, dict) else {}
    stats[key] = max(int(value), 0)
    ChannelContent.objects.filter(id=content_id).update(stats=stats)
    return stats


def _sync_channel_content_counts(content: ChannelContent) -> dict:
    stats = content.stats if isinstance(content.stats, dict) else {}
    stats.update(
        {
            "reactions": ChannelContentReaction.objects.filter(content=content).count(),
            "comments": ChannelContentComment.objects.filter(content=content, is_deleted=False).count(),
            "saves": ChannelContentSave.objects.filter(content=content).count(),
        }
    )
    ChannelContent.objects.filter(id=content.id).update(stats=stats)
    return stats


def _increment_channel_content_count(content: ChannelContent, key: str) -> dict:
    stats = content.stats if isinstance(content.stats, dict) else {}
    stats[key] = int(stats.get(key) or 0) + 1
    ChannelContent.objects.filter(id=content.id).update(stats=stats)
    return stats


def _request_ip(request) -> str:
    forwarded = request.META.get("HTTP_X_FORWARDED_FOR", "")
    if forwarded:
        return forwarded.split(",")[0].strip()[:45]
    return str(request.META.get("REMOTE_ADDR") or "")[:45]


def _channel_audit(request, *, action: str, target_type: str, target_id, metadata: dict | None = None):
    user = getattr(request, "user", None)
    if not getattr(user, "is_authenticated", False):
        return None
    try:
        return ModerationAuditLog.objects.create(
            actor_id=user.id,
            action=action,
            target_type=target_type.upper()[:32],
            target_id=target_id,
            metadata=metadata or {},
            ip_address=_request_ip(request) or None,
            device_info=str(request.META.get("HTTP_USER_AGENT") or "")[:500],
        )
    except Exception:
        logger.exception("Unable to create channel audit event action=%s target=%s", action, target_id)
        return None


def _notify_channel_subscribers(channel: BroadcastChannel, *, notification_type: str, title: str, body: str, target_type: str, target_id):
    try:
        from apps.notifications import services as notification_services
    except Exception:
        return 0
    subscriptions = (
        BroadcastChannelSubscription.objects
        .filter(channel=channel)
        .exclude(notifications=BroadcastChannelSubscription.NotificationLevel.NONE)
        .values_list("user_id", "notifications")
    )
    count = 0
    for user_id, level in subscriptions[:500]:
        try:
            notification_services.create_notification(
                user_id=user_id,
                type=notification_type,
                title=title[:400],
                body=body[:1000],
                target_type=target_type,
                target_id=target_id,
                priority="MEDIUM" if level == BroadcastChannelSubscription.NotificationLevel.PERSONALIZED else "HIGH",
                dedup_key=f"{notification_type}:{target_id}:{user_id}",
                context={
                    "channel_id": str(channel.id),
                    "channel_handle": channel.handle,
                    "channel_name": channel.display_name,
                },
            )
            count += 1
        except Exception:
            logger.exception("Unable to notify channel subscriber channel=%s user=%s", channel.id, user_id)
    return count


def _notify_course_enrollees(course: "EducationInstitutionCourse", *, notification_type: str, title: str, body: str, target_type: str, target_id):
    """Mirrors _notify_channel_subscribers above, for the education side:
    a new/published lesson notifies everyone actively enrolled in its
    course. Enrollment.course is a direct FK (set when the enrolling
    broadcast is course-scoped) so this needs no traversal through the
    broadcast/program hierarchy - see EducationInstitutionEnrollment.
    """
    try:
        from apps.notifications import services as notification_services
    except Exception:
        return 0
    enrollee_ids = (
        EducationInstitutionEnrollment.objects
        .filter(course=course, status=EducationEnrollmentStatus.ENROLLED)
        .values_list("user_id", flat=True)
    )
    count = 0
    for user_id in enrollee_ids[:500]:
        try:
            notification_services.create_notification(
                user_id=user_id,
                type=notification_type,
                title=title[:400],
                body=body[:1000],
                target_type=target_type,
                target_id=target_id,
                priority="MEDIUM",
                dedup_key=f"{notification_type}:{target_id}:{user_id}",
                context={
                    "institution_id": str(course.institution_id),
                    "course_id": str(course.id),
                    "course_title": course.title,
                },
            )
            count += 1
        except Exception:
            logger.exception("Unable to notify course enrollee course=%s user=%s", course.id, user_id)
    return count


def _target_from_moderation_request(request, channel_id=None):
    target_type = str(request.data.get("target_type") or request.query_params.get("target_type") or "channel").strip().lower()
    target_id = request.data.get("target_id") or request.query_params.get("target_id") or channel_id
    if target_type == ChannelModerationRecord.TargetType.CHANNEL:
        channel = get_object_or_404(BroadcastChannel, id=target_id, is_deleted=False)
        return channel, None, None, channel.id, target_type
    if target_type == ChannelModerationRecord.TargetType.CONTENT:
        content = get_object_or_404(ChannelContent.objects.select_related("channel"), id=target_id, is_deleted=False)
        return content.channel, content, None, content.id, target_type
    if target_type == ChannelModerationRecord.TargetType.COMMENT:
        comment = get_object_or_404(ChannelContentComment.objects.select_related("content__channel"), id=target_id, is_deleted=False)
        return comment.content.channel, comment.content, comment, comment.id, target_type
    raise ValidationError({"target_type": "Expected channel, content, or comment."})


class BroadcastChannelListCreateView(APIView):
    permission_classes = [AllowAny]

    def get(self, request):
        mine = str(request.query_params.get("mine") or request.query_params.get("owned") or "").strip().lower()
        if mine in {"1", "true", "yes", "me"}:
            if not getattr(request.user, "is_authenticated", False):
                return Response({"detail": "Authentication credentials were not provided."}, status=status.HTTP_401_UNAUTHORIZED)
            query = BroadcastChannel.objects.filter(
                is_deleted=False,
            ).filter(
                Q(owner_user=request.user) | Q(roles__user=request.user)
            ).distinct().order_by("-updated_at", "-created_at")
        else:
            query = BroadcastChannel.objects.filter(is_public=True, is_deleted=False).order_by("-subscriber_count", "-created_at")
        q = str(request.query_params.get("q") or "").strip()
        if q:
            query = query.filter(Q(handle__icontains=q) | Q(display_name__icontains=q) | Q(description__icontains=q))
        owner_type = str(request.query_params.get("owner_type") or "").strip()
        if owner_type:
            query = query.filter(owner_type=owner_type)
        category = str(request.query_params.get("category") or "").strip()
        if category:
            query = query.filter(category__iexact=category)
        limit = min(max(int(request.query_params.get("limit") or 25), 1), 100)
        offset = max(int(request.query_params.get("offset") or request.query_params.get("cursor") or 0), 0)
        rows = list(query[offset : offset + limit + 1])
        next_offset = offset + limit if len(rows) > limit else None
        serializer = BroadcastChannelSummarySerializer(rows[:limit], many=True, context={"request": request})
        return Response({"results": serializer.data, "next_cursor": str(next_offset) if next_offset is not None else None})

    def post(self, request):
        if not getattr(request.user, "is_authenticated", False):
            return Response({"detail": "Authentication credentials were not provided."}, status=status.HTTP_401_UNAUTHORIZED)
        owner_type = str(request.data.get("owner_type") or BroadcastChannel.OwnerType.USER).strip().lower()
        resolved_owner_id = request.user.id
        resolved_owner_user = request.user
        if owner_type == BroadcastChannel.OwnerType.USER:
            pass
        elif owner_type == BroadcastChannel.OwnerType.SHOP:
            from apps.commerce.models import Shop
            from apps.commerce.services import _provider_can_manage_shop

            shop = get_object_or_404(Shop, id=str(request.data.get("owner_id") or ""))
            if not _provider_can_manage_shop(request.user, shop) and not request.user.is_staff:
                raise PermissionDenied("Not allowed to create a channel for this shop.")
            resolved_owner_id = shop.id
            resolved_owner_user = None
        elif owner_type == BroadcastChannel.OwnerType.HEALTH:
            from apps.health_ops.models import HealthInstitution
            from apps.health_ops.views import _can_manage_institution

            institution = get_object_or_404(HealthInstitution, id=str(request.data.get("owner_id") or ""))
            if not _can_manage_institution(request.user, institution):
                raise PermissionDenied("Not allowed to create a channel for this institution.")
            resolved_owner_id = institution.id
            resolved_owner_user = None
        elif owner_type == BroadcastChannel.OwnerType.EDUCATION:
            institution = _get_education_institution_or_404(request.user, str(request.data.get("owner_id") or ""))
            _require_manage_institution_membership(request.user, institution)
            resolved_owner_id = institution.id
            resolved_owner_user = None
        elif owner_type == BroadcastChannel.OwnerType.PARTNER:
            from apps.partners.models import Partner
            from apps.partners.services import partner_user_can_manage

            partner = get_object_or_404(Partner, id=str(request.data.get("owner_id") or ""))
            if not partner_user_can_manage(partner, request.user):
                raise PermissionDenied("Not allowed to create a channel for this partner.")
            resolved_owner_id = partner.id
            resolved_owner_user = None
        else:
            raise ValidationError({"owner_type": "Unsupported owner_type."})
        if owner_type == BroadcastChannel.OwnerType.USER:
            # Org-owned channels (shop/health/education/partner) aren't
            # gated on the creating individual's own personal-profile tier
            # at all - a business owner on a free personal plan managing a
            # paid business shouldn't need their own Pro subscription just
            # to create a channel for that business. They're gated purely
            # on manage-rights over the owning entity, already enforced
            # above.
            channel_limit = _resolve_profile_limit(
                request.user,
                "channels_create",
                legacy_required_tier="pro",
                permission_message="Creating a broadcast channel requires Pro tier or higher.",
            )
            if channel_limit is not None:
                existing_channel_count = BroadcastChannel.objects.filter(
                    owner_type=BroadcastChannel.OwnerType.USER,
                    owner_user=request.user,
                    is_deleted=False,
                ).count()
                if existing_channel_count >= channel_limit:
                    raise ValidationError(
                        {"detail": f"Your current plan allows up to {channel_limit} broadcast channel{'s' if channel_limit != 1 else ''}. Upgrade to create more."}
                    )
        handle = _safe_channel_handle_from_value(request.data.get("handle"))
        if not handle:
            raise ValidationError({"handle": "A public channel handle is required."})
        display_name = str(request.data.get("display_name") or request.data.get("name") or "").strip()
        if not display_name:
            raise ValidationError({"display_name": "Display name is required."})
        if BroadcastChannel.objects.filter(handle__iexact=handle).exists():
            raise ValidationError({"handle": "This channel handle is already in use."})
        try:
            channel = BroadcastChannel.objects.create(
                owner_type=owner_type,
                owner_id=resolved_owner_id,
                owner_user=resolved_owner_user,
                handle=handle,
                display_name=display_name[:140],
                description=str(request.data.get("description") or "").strip(),
                avatar_url=str(request.data.get("avatar_url") or "").strip(),
                banner_url=str(request.data.get("banner_url") or "").strip(),
                country=str(request.data.get("country") or getattr(request.user, "country", "") or "").strip()[:8],
                language=str(request.data.get("language") or "").strip()[:16],
                category=str(request.data.get("category") or "").strip()[:64],
                links=request.data.get("links") if isinstance(request.data.get("links"), list) else [],
                branding=request.data.get("branding") if isinstance(request.data.get("branding"), dict) else {},
                is_public=bool(request.data.get("is_public", True)),
            )
        except IntegrityError:
            raise ValidationError({"handle": "This channel handle is already in use."})
        # Unconditional regardless of owner_type - this alone is what makes
        # _user_can_manage_channel/_user_channel_role work correctly for the
        # creator of an org-owned channel, with zero change needed to either
        # of those functions (they already fall through to this role table
        # once channel.owner_user_id is empty, which it is for every
        # non-USER owner_type here).
        BroadcastChannelRole.objects.get_or_create(channel=channel, user=request.user, role=BroadcastChannelRole.Role.OWNER)
        return Response(BroadcastChannelDetailSerializer(channel, context={"request": request}).data, status=status.HTTP_201_CREATED)


class BroadcastChannelDetailView(APIView):
    permission_classes = [AllowAny]

    def get(self, request, handle_or_id: str):
        channel = _resolve_channel_lookup(handle_or_id, include_private=getattr(request.user, "is_authenticated", False))
        if not channel.is_public and not _user_can_manage_channel(request.user, channel):
            raise Http404
        return Response(BroadcastChannelDetailSerializer(channel, context={"request": request}).data)

    def patch(self, request, handle_or_id: str):
        channel = _resolve_channel_lookup(handle_or_id, include_private=True)
        if not _user_can_manage_channel(request.user, channel):
            raise PermissionDenied("You cannot manage this channel.")
        for field in ["display_name", "description", "avatar_url", "banner_url", "country", "language", "category"]:
            if field in request.data:
                setattr(channel, field, str(request.data.get(field) or "").strip())
        if "handle" in request.data:
            handle = _safe_channel_handle_from_value(request.data.get("handle"))
            if not handle:
                raise ValidationError({"handle": "A public channel handle is required."})
            if BroadcastChannel.objects.exclude(id=channel.id).filter(handle__iexact=handle).exists():
                raise ValidationError({"handle": "This channel handle is already in use."})
            channel.handle = handle
        for json_field in ["links", "branding", "settings"]:
            if json_field in request.data:
                value = request.data.get(json_field)
                if json_field == "links" and not isinstance(value, list):
                    raise ValidationError({json_field: "Expected a list."})
                if json_field in {"branding", "settings"} and not isinstance(value, dict):
                    raise ValidationError({json_field: "Expected an object."})
                setattr(channel, json_field, value)
        if "is_public" in request.data:
            channel.is_public = bool(request.data.get("is_public"))
        if "trailer_content_id" in request.data:
            trailer_id = request.data.get("trailer_content_id")
            if trailer_id:
                channel.trailer_content = get_object_or_404(ChannelContent, id=trailer_id, channel=channel, is_deleted=False)
            else:
                channel.trailer_content = None
        if "featured_content_id" in request.data:
            featured_id = request.data.get("featured_content_id")
            if featured_id:
                channel.featured_content = get_object_or_404(ChannelContent, id=featured_id, channel=channel, is_deleted=False)
            else:
                channel.featured_content = None
        channel.save()
        return Response(BroadcastChannelDetailSerializer(channel, context={"request": request}).data)


class BroadcastChannelBroadcastView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, channel_id):
        channel = get_object_or_404(BroadcastChannel, id=channel_id, is_deleted=False)
        if not _user_can_manage_channel(request.user, channel):
            raise PermissionDenied("You cannot broadcast this channel.")
        item = _broadcast_channel_for_feed(channel, request.user)
        _channel_audit(
            request,
            action="channel.broadcast",
            target_type="channel",
            target_id=channel.id,
            metadata={"broadcast_id": str(item.id)},
        )
        data = BroadcastChannelDetailSerializer(channel, context={"request": request}).data
        data["broadcast_id"] = str(item.id)
        data["is_broadcast"] = True
        return Response(data, status=status.HTTP_200_OK)

    def delete(self, request, channel_id):
        channel = get_object_or_404(BroadcastChannel, id=channel_id, is_deleted=False)
        if not _user_can_manage_channel(request.user, channel):
            raise PermissionDenied("You cannot stop broadcasting this channel.")
        removed = _unbroadcast_channel_for_feed(channel)
        _channel_audit(
            request,
            action="channel.unbroadcast",
            target_type="channel",
            target_id=channel.id,
            metadata={"removed": int(removed or 0)},
        )
        data = BroadcastChannelDetailSerializer(channel, context={"request": request}).data
        data["is_broadcast"] = False
        data["broadcast_id"] = ""
        return Response(data, status=status.HTTP_200_OK)


class BroadcastChannelSubscribeView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, channel_id):
        channel = get_object_or_404(BroadcastChannel, id=channel_id, is_deleted=False, is_public=True)
        subscription, created = BroadcastChannelSubscription.objects.get_or_create(
            channel=channel,
            user=request.user,
            defaults={"notifications": request.data.get("notifications") or BroadcastChannelSubscription.NotificationLevel.PERSONALIZED},
        )
        if not created and request.data.get("notifications"):
            subscription.notifications = request.data.get("notifications")
            subscription.save(update_fields=["notifications", "updated_at"])
        if created:
            BroadcastChannel.objects.filter(id=channel.id).update(subscriber_count=models.F("subscriber_count") + 1)
            channel.refresh_from_db(fields=["subscriber_count"])
            _channel_audit(request, action="channel.subscribe", target_type="channel", target_id=channel.id, metadata={"notifications": subscription.notifications})
        notify_main_tab_badges_updated(
            [str(request.user.id)],
            source="broadcast",
            reason="channel_subscription_updated",
            extra={"channel_id": str(channel.id), "subscribed": True},
        )
        return Response(BroadcastChannelSubscriptionSerializer(subscription, context={"request": request}).data)

    def delete(self, request, channel_id):
        channel = get_object_or_404(BroadcastChannel, id=channel_id, is_deleted=False)
        deleted, _ = BroadcastChannelSubscription.objects.filter(channel=channel, user=request.user).delete()
        if deleted:
            BroadcastChannel.objects.filter(id=channel.id, subscriber_count__gt=0).update(subscriber_count=models.F("subscriber_count") - 1)
            notify_main_tab_badges_updated(
                [str(request.user.id)],
                source="broadcast",
                reason="channel_subscription_updated",
                extra={"channel_id": str(channel.id), "subscribed": False},
            )
        return Response({"subscribed": False}, status=status.HTTP_200_OK)


class BroadcastChannelSubscriptionView(APIView):
    permission_classes = [IsAuthenticated]

    def patch(self, request, channel_id):
        channel = get_object_or_404(BroadcastChannel, id=channel_id, is_deleted=False)
        subscription = get_object_or_404(BroadcastChannelSubscription, channel=channel, user=request.user)
        notifications = str(request.data.get("notifications") or "").strip()
        if notifications not in BroadcastChannelSubscription.NotificationLevel.values:
            raise ValidationError({"notifications": "Invalid notification level."})
        subscription.notifications = notifications
        subscription.save(update_fields=["notifications", "updated_at"])
        notify_main_tab_badges_updated(
            [str(request.user.id)],
            source="broadcast",
            reason="channel_subscription_updated",
            extra={"channel_id": str(channel.id), "notifications": notifications},
        )
        return Response(BroadcastChannelSubscriptionSerializer(subscription, context={"request": request}).data)


class MyChannelSubscriptionsView(APIView):
    """List the signed-in user's subscribed channels. This was the one
    real gap found while building KISTube's sidebar Subscriptions list:
    BroadcastChannelSubscribeView/BroadcastChannelSubscriptionView cover
    subscribing and per-channel notification level, but nothing lists
    "every channel I'm subscribed to" - the RN app's own Library screen
    doesn't need this because it filters its already-loaded channel list
    client-side, which doesn't work for a fresh page load with no prior
    channel list in memory. Same pagination shape as
    BroadcastChannelListCreateView.get for consistency."""

    permission_classes = [IsAuthenticated]

    def get(self, request):
        query = (
            BroadcastChannel.objects.filter(
                is_deleted=False,
                subscriptions__user=request.user,
            )
            .distinct()
            .order_by("-subscriptions__created_at")
        )
        limit = min(max(int(request.query_params.get("limit") or 25), 1), 100)
        offset = max(int(request.query_params.get("offset") or request.query_params.get("cursor") or 0), 0)
        rows = list(query[offset : offset + limit + 1])
        next_offset = offset + limit if len(rows) > limit else None
        serializer = BroadcastChannelSummarySerializer(rows[:limit], many=True, context={"request": request})
        return Response({"results": serializer.data, "next_cursor": str(next_offset) if next_offset is not None else None})


class BroadcastChannelContentListCreateView(APIView):
    permission_classes = [AllowAny]

    def get(self, request, channel_id):
        channel = get_object_or_404(BroadcastChannel, id=channel_id, is_deleted=False)
        can_manage = _user_can_manage_channel(request.user, channel)
        if not channel.is_public and not can_manage:
            raise Http404
        query = ChannelContent.objects.select_related("channel").filter(channel=channel, is_deleted=False)
        if not can_manage:
            query = query.filter(visibility=ChannelContent.Visibility.PUBLIC, status=ChannelContent.Status.PUBLISHED)
        status_filter = str(request.query_params.get("status") or "").strip()
        if status_filter and can_manage:
            query = query.filter(status=status_filter)
        type_filter = str(request.query_params.get("type") or "").strip()
        if type_filter:
            if type_filter == "post":
                query = query.filter(content_type__in=[ChannelContentType.TEXT, ChannelContentType.RICH_TEXT])
            else:
                query = query.filter(content_type=type_filter)
        q = str(request.query_params.get("q") or "").strip()
        if q:
            query = query.filter(Q(title__icontains=q) | Q(description__icontains=q) | Q(text_plain__icontains=q))
        date_from = str(request.query_params.get("date_from") or "").strip()
        if date_from:
            query = query.filter(published_at__gte=date_from)
        date_to = str(request.query_params.get("date_to") or "").strip()
        if date_to:
            query = query.filter(published_at__lte=date_to)
        min_duration = request.query_params.get("min_duration")
        if min_duration is not None:
            try:
                query = query.filter(duration_seconds__gte=int(min_duration))
            except (TypeError, ValueError):
                pass
        max_duration = request.query_params.get("max_duration")
        if max_duration is not None:
            try:
                query = query.filter(duration_seconds__lte=int(max_duration))
            except (TypeError, ValueError):
                pass
        sort_param = str(request.query_params.get("sort") or "new").strip().lower()
        if sort_param == "oldest":
            query = query.order_by("published_at", "created_at")
        elif sort_param == "top":
            query = query.order_by("-stats__views", "-published_at", "-created_at")
        else:
            query = query.order_by("-published_at", "-created_at")
        limit = min(max(int(request.query_params.get("limit") or 25), 1), 100)
        offset = max(int(request.query_params.get("offset") or request.query_params.get("cursor") or 0), 0)
        rows = list(query[offset : offset + limit + 1])
        next_offset = offset + limit if len(rows) > limit else None
        serializer = ChannelContentListSerializer(rows[:limit], many=True, context={"request": request})
        return Response({"results": serializer.data, "next_cursor": str(next_offset) if next_offset is not None else None})

    def post(self, request, channel_id):
        channel = get_object_or_404(BroadcastChannel, id=channel_id, is_deleted=False)
        if not _user_can_edit_content(request.user, ChannelContent(channel=channel)):
            raise PermissionDenied("You cannot create content for this channel.")
        raw_attachments = request.data.get("attachments")
        if isinstance(raw_attachments, list):
            validate_attachment_metadata_for_safe_messaging(raw_attachments)
        content = ChannelContent.objects.create(
            channel=channel,
            content_type=_content_type_from_request(request.data.get("content_type") or request.data.get("type")),
            title=str(request.data.get("title") or "").strip()[:220],
            description=str(request.data.get("description") or request.data.get("summary") or "").strip(),
            text_plain=str(request.data.get("text_plain") or request.data.get("textPlain") or "").strip(),
            text_doc=(
                request.data.get("text_doc")
                if isinstance(request.data.get("text_doc"), dict)
                else request.data.get("text")
                if isinstance(request.data.get("text"), dict)
                else {}
            ),
            thumbnail_url=str(
                request.data.get("thumbnail_url")
                or request.data.get("thumbnailUrl")
                or request.data.get("thumbnail")
                or ""
            ).strip(),
            visibility=str(request.data.get("visibility") or ChannelContent.Visibility.PRIVATE).strip().lower(),
            status=str(request.data.get("status") or ChannelContent.Status.DRAFT).strip().lower(),
            scheduled_at=_content_datetime_from_request(request.data.get("scheduled_at")),
            duration_seconds=int(request.data.get("duration_seconds") or 0) or None,
            metadata={
                **(request.data.get("metadata") if isinstance(request.data.get("metadata"), dict) else {}),
                "playlist_ids": request.data.get("playlist_ids") if isinstance(request.data.get("playlist_ids"), list) else [],
                "captions": request.data.get("captions") if isinstance(request.data.get("captions"), (list, dict, str)) else None,
                "embed_allowed": bool(request.data.get("embed_allowed", request.data.get("embedAllowed", False))),
                "composer_type": str(request.data.get("composerType") or request.data.get("composer_type") or "").strip(),
            },
            created_by=request.user,
        )
        if isinstance(raw_attachments, list):
            for index, attachment in enumerate(raw_attachments):
                if isinstance(attachment, dict):
                    ChannelContentAsset.objects.create(
                        content=content,
                        **prepare_channel_asset_payload(
                            _asset_payload_from_attachment(attachment, index),
                            content_type=content.content_type,
                        ),
                    )
        BroadcastChannel.objects.filter(id=channel.id).update(content_count=models.F("content_count") + 1)
        return Response(ChannelContentDetailSerializer(content, context={"request": request}).data, status=status.HTTP_201_CREATED)


class ChannelContentDetailView(APIView):
    permission_classes = [AllowAny]

    def get(self, request, content_id):
        content = get_object_or_404(ChannelContent.objects.select_related("channel"), id=content_id)
        if not _user_can_view_content(request.user, content):
            raise Http404
        return Response(ChannelContentDetailSerializer(content, context={"request": request}).data)

    def patch(self, request, content_id):
        content = get_object_or_404(ChannelContent.objects.select_related("channel"), id=content_id, is_deleted=False)
        if not _user_can_edit_content(request.user, content):
            raise PermissionDenied("You cannot edit this content.")
        for field in ["title", "description", "text_plain", "thumbnail_url", "visibility", "status"]:
            if field in request.data:
                setattr(content, field, str(request.data.get(field) or "").strip())
        if "content_type" in request.data or "type" in request.data:
            content.content_type = _content_type_from_request(request.data.get("content_type") or request.data.get("type"))
        if "text_doc" in request.data:
            value = request.data.get("text_doc")
            if not isinstance(value, dict):
                raise ValidationError({"text_doc": "Expected an object."})
            content.text_doc = value
        if "metadata" in request.data:
            value = request.data.get("metadata")
            if not isinstance(value, dict):
                raise ValidationError({"metadata": "Expected an object."})
            content.metadata = value
        if "tags" in request.data:
            value = request.data.get("tags")
            if not isinstance(value, list):
                raise ValidationError({"tags": "Expected a list of strings."})
            content.tags = [str(t).strip() for t in value if str(t).strip()]
        if "scheduled_at" in request.data:
            content.scheduled_at = _content_datetime_from_request(request.data.get("scheduled_at"))
        if "comments_disabled" in request.data:
            content.comments_disabled = bool(request.data.get("comments_disabled"))
        content.save()
        return Response(ChannelContentDetailSerializer(content, context={"request": request}).data)

    def delete(self, request, content_id):
        content = get_object_or_404(ChannelContent.objects.select_related("channel"), id=content_id, is_deleted=False)
        if not _user_can_edit_content(request.user, content):
            raise PermissionDenied("You cannot delete this content.")
        content.status = ChannelContent.Status.ARCHIVED
        content.visibility = ChannelContent.Visibility.PRIVATE
        content.is_deleted = True
        content.save(update_fields=["status", "visibility", "is_deleted", "updated_at"])
        return Response(status=status.HTTP_204_NO_CONTENT)


class ChannelContentPublishView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, content_id):
        content = get_object_or_404(ChannelContent.objects.select_related("channel"), id=content_id, is_deleted=False)
        if not _user_can_edit_content(request.user, content):
            raise PermissionDenied("You cannot publish this content.")
        validate_channel_content_ready_for_publish(content)
        content.status = ChannelContent.Status.PUBLISHED
        content.visibility = request.data.get("visibility") or content.visibility or ChannelContent.Visibility.PUBLIC
        content.published_at = timezone.now()
        content.save(update_fields=["status", "visibility", "published_at", "updated_at"])
        _channel_audit(request, action="channel_content.publish", target_type="content", target_id=content.id, metadata={"channel_id": str(content.channel_id)})
        _notify_channel_subscribers(
            content.channel,
            notification_type="CHANNEL_CONTENT_PUBLISHED",
            title=content.title or content.channel.display_name,
            body=f"{content.channel.display_name} published new content.",
            target_type="channel_content",
            target_id=content.id,
        )
        ChannelActivityEvent.objects.create(
            channel=content.channel,
            event_type=ChannelActivityEvent.EventType.NEW_CONTENT,
            target_type='content',
            target_id=str(content.id),
            metadata={'title': content.title, 'content_type': content.content_type},
        )
        return Response(ChannelContentDetailSerializer(content, context={"request": request}).data)


class ChannelContentUnpublishView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, content_id):
        content = get_object_or_404(ChannelContent.objects.select_related("channel"), id=content_id, is_deleted=False)
        if not _user_can_edit_content(request.user, content):
            raise PermissionDenied("You cannot unpublish this content.")
        content.status = ChannelContent.Status.DRAFT
        content.visibility = ChannelContent.Visibility.PRIVATE
        content.save(update_fields=["status", "visibility", "updated_at"])
        _channel_audit(request, action="channel_content.unpublish", target_type="content", target_id=content.id, metadata={"channel_id": str(content.channel_id)})
        return Response(ChannelContentDetailSerializer(content, context={"request": request}).data)


class ChannelContentBroadcastView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, content_id):
        content = get_object_or_404(ChannelContent.objects.select_related("channel"), id=content_id, is_deleted=False)
        if not _user_can_edit_content(request.user, content):
            raise PermissionDenied("You cannot broadcast this content.")
        validate_channel_content_ready_for_publish(content)
        if content.status != ChannelContent.Status.PUBLISHED:
            content.status = ChannelContent.Status.PUBLISHED
            content.visibility = ChannelContent.Visibility.PUBLIC
            content.published_at = content.published_at or timezone.now()
            content.save(update_fields=["status", "visibility", "published_at", "updated_at"])
        item = _broadcast_channel_content_for_feed(content, request.user)
        _channel_audit(
            request,
            action="channel_content.broadcast",
            target_type="content",
            target_id=content.id,
            metadata={"channel_id": str(content.channel_id), "broadcast_id": str(item.id)},
        )
        data = ChannelContentDetailSerializer(content, context={"request": request}).data
        data["broadcast_id"] = str(item.id)
        data["is_broadcast"] = True
        return Response(data, status=status.HTTP_200_OK)

    def delete(self, request, content_id):
        content = get_object_or_404(ChannelContent.objects.select_related("channel"), id=content_id, is_deleted=False)
        if not _user_can_edit_content(request.user, content):
            raise PermissionDenied("You cannot stop broadcasting this content.")
        removed = _unbroadcast_channel_content_for_feed(content)
        _channel_audit(
            request,
            action="channel_content.unbroadcast",
            target_type="content",
            target_id=content.id,
            metadata={"channel_id": str(content.channel_id), "removed": int(removed or 0)},
        )
        data = ChannelContentDetailSerializer(content, context={"request": request}).data
        data["is_broadcast"] = False
        data["broadcast_id"] = ""
        return Response(data, status=status.HTTP_200_OK)


class ChannelContentScheduleView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, content_id):
        content = get_object_or_404(ChannelContent.objects.select_related("channel"), id=content_id, is_deleted=False)
        if not _user_can_edit_content(request.user, content):
            raise PermissionDenied("You cannot schedule this content.")
        scheduled_at = _content_datetime_from_request(request.data.get("scheduled_at"))
        if not scheduled_at:
            raise ValidationError({"scheduled_at": "scheduled_at is required."})
        content.status = ChannelContent.Status.SCHEDULED
        content.scheduled_at = scheduled_at
        content.save(update_fields=["status", "scheduled_at", "updated_at"])
        return Response(ChannelContentDetailSerializer(content, context={"request": request}).data)


class ChannelContentAssetUploadView(APIView):
    permission_classes = [IsAuthenticated]
    parser_classes = [JSONParser, FormParser, MultiPartParser]

    def post(self, request, content_id):
        content = get_object_or_404(ChannelContent.objects.select_related("channel"), id=content_id, is_deleted=False)
        if not _user_can_edit_content(request.user, content):
            raise PermissionDenied("You cannot add assets to this content.")
        payload = {
            "asset_type": str(request.data.get("asset_type") or request.data.get("media_type") or "document").strip()[:32],
            "url": str(request.data.get("url") or "").strip(),
            "storage_path": str(request.data.get("storage_path") or request.data.get("path") or "").strip(),
            "mime_type": str(request.data.get("mime_type") or request.data.get("mimeType") or "").strip()[:128],
            "thumbnail_url": str(request.data.get("thumbnail_url") or request.data.get("thumbUrl") or "").strip(),
            "caption": str(request.data.get("caption") or "").strip(),
            "sort_order": int(request.data.get("sort_order") or content.assets.count()),
            "processing_status": str(request.data.get("processing_status") or "ready").strip()[:24],
            "metadata": request.data.get("metadata") if isinstance(request.data.get("metadata"), dict) else {},
        }
        if "attachment" in request.data and isinstance(request.data.get("attachment"), dict):
            validate_attachment_metadata_for_safe_messaging([request.data["attachment"]])
            payload.update(_asset_payload_from_attachment(request.data["attachment"], payload["sort_order"]))
        else:
            validate_attachment_metadata_for_safe_messaging([payload])
            payload = prepare_channel_asset_payload(payload, content_type=content.content_type)
        asset = ChannelContentAsset.objects.create(content=content, **payload)
        return Response(ChannelContentAssetSerializer(asset).data, status=status.HTTP_201_CREATED)


class ChannelLiveStreamListCreateView(APIView):
    permission_classes = [AllowAny]

    def get(self, request, channel_id):
        channel = get_object_or_404(BroadcastChannel, id=channel_id, is_deleted=False)
        can_manage = _user_can_manage_channel(request.user, channel)
        if not channel.is_public and not can_manage:
            raise Http404
        query = ChannelLiveStream.objects.select_related("channel", "content").filter(channel=channel)
        if not can_manage:
            query = query.exclude(status__in=[ChannelLiveStream.Status.CANCELLED, ChannelLiveStream.Status.FAILED])
        status_filter = str(request.query_params.get("status") or "").strip()
        if status_filter:
            query = query.filter(status=status_filter)
        rows = query.order_by("-scheduled_start_at", "-created_at")[:50]
        return Response({"results": ChannelLiveStreamSerializer(rows, many=True, context={"request": request}).data})

    def post(self, request, channel_id):
        from .live_stream_providers import LiveStreamProviderError, get_live_stream_provider

        require_feature(
            request.user,
            "live_streaming",
            "Live streaming is available on Partner plans and above. Upgrade to unlock.",
        )
        channel = get_object_or_404(BroadcastChannel, id=channel_id, is_deleted=False)
        if not _user_can_edit_content(request.user, ChannelContent(channel=channel)):
            raise PermissionDenied("You cannot schedule live streams for this channel.")
        title = str(request.data.get("title") or "").strip()
        if not title:
            raise ValidationError({"title": "A live stream title is required."})
        scheduled_at = _content_datetime_from_request(
            request.data.get("scheduled_start_at") or request.data.get("scheduledStartAt") or request.data.get("scheduled_at")
        )
        stream_uuid = uuid.uuid4()
        dev_payload = _safe_live_dev_payload(channel.id, stream_uuid)

        # Call the live-streaming provider when enabled and not in sandbox/dev mode
        provider_payload: dict = {}
        provider_name = _live_stream_provider()
        if provider_name != "disabled" and not dev_payload:
            lsp = get_live_stream_provider(provider_name)
            if lsp:
                try:
                    provider_payload = lsp.create_live_stream()
                except LiveStreamProviderError as exc:
                    raise ValidationError({"provider": str(exc)})

        merged = provider_payload or dev_payload
        stream_key = f"{channel.id}:{stream_uuid}:{uuid.uuid4()}"
        # SECURITY: never let client-supplied metadata set/override any key
        # that server-side code (this view, or the WHIP proxy view below)
        # trusts as a connection/provider target. `whip_url` in particular is
        # fetched server-side by ChannelLiveStreamWhipView with no further
        # checks - letting a client set it to an internal URL (or the cloud
        # metadata endpoint 169.254.169.254) turned that proxy into an SSRF
        # primitive. Only the provider integration above (`merged`) may set
        # these fields.
        _reserved_live_stream_metadata_keys = {
            "whip_url", "ingest_url", "stream_key", "provider",
            "provider_stream_id", "provider_raw", "provider_calls_enabled",
            "raw_stream_key_returned", "playback_url",
        }
        _user_metadata = request.data.get("metadata") if isinstance(request.data.get("metadata"), dict) else {}
        _safe_user_metadata = {
            k: v for k, v in _user_metadata.items() if k not in _reserved_live_stream_metadata_keys
        }
        live = ChannelLiveStream.objects.create(
            channel=channel,
            title=title[:220],
            description=str(request.data.get("description") or "").strip(),
            scheduled_start_at=scheduled_at,
            provider=merged.get("provider") or provider_name,
            provider_stream_id=merged.get("provider_stream_id") or str(stream_uuid),
            ingest_url=merged.get("ingest_url", ""),
            stream_key_hash=_hash_stream_key(stream_key),
            playback_url=merged.get("playback_url", ""),
            thumbnail_url=str(request.data.get("thumbnail_url") or request.data.get("thumbnailUrl") or "").strip(),
            metadata={
                "provider_calls_enabled": _live_provider_sandbox_enabled(),
                "raw_stream_key_returned": False,
                **({"provider_raw": merged.get("raw")} if merged.get("raw") else {}),
                **_safe_user_metadata,
            },
            created_by=request.user,
        )
        content = ChannelContent.objects.create(
            channel=channel,
            content_type=ChannelContentType.LIVE_STREAM,
            title=live.title,
            description=live.description,
            thumbnail_url=live.thumbnail_url,
            visibility=ChannelContent.Visibility.PUBLIC,
            status=ChannelContent.Status.SCHEDULED,
            scheduled_at=live.scheduled_start_at,
            metadata={"live_stream_id": str(live.id)},
            created_by=request.user,
        )
        live.content = content
        live.save(update_fields=["content", "updated_at"])
        return Response(ChannelLiveStreamSerializer(live, context={"request": request}).data, status=status.HTTP_201_CREATED)


class ChannelLiveStreamDetailView(APIView):
    permission_classes = [AllowAny]

    def get(self, request, stream_id):
        live = get_object_or_404(ChannelLiveStream.objects.select_related("channel", "content"), id=stream_id)
        if not live.channel.is_public and not _user_can_manage_channel(request.user, live.channel):
            raise Http404
        return Response(ChannelLiveStreamSerializer(live, context={"request": request}).data)


class ChannelLiveStreamStreamKeyView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, stream_id):
        live = get_object_or_404(ChannelLiveStream.objects.select_related("channel", "content"), id=stream_id)
        if not _user_can_edit_content(request.user, ChannelContent(channel=live.channel)):
            raise PermissionDenied("You cannot view ingest details for this live stream.")
        stream_key = ""
        ingest_url = str(live.ingest_url or "").strip()
        if "/app/" in ingest_url:
            stream_key = ingest_url.rsplit("/", 1)[-1]
        elif ingest_url.startswith(("rtmp://", "rtmps://")) and live.provider == "disabled":
            stream_key = str(live.provider_stream_id or live.id)
        if not stream_key:
            raise ValidationError({"stream_key": "Stream key is not available for this provider yet."})
        _channel_audit(
            request,
            action="channel_live.stream_key.view",
            target_type="channel",
            target_id=live.channel_id,
            metadata={"stream_id": str(live.id), "provider": live.provider},
        )
        return Response(
            {
                "stream_id": str(live.id),
                "provider": live.provider,
                "ingest_url": ingest_url,
                "stream_key": stream_key,
                "stream_key_available": True,
            },
            status=status.HTTP_200_OK,
        )


class ChannelLiveStreamStartView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, stream_id):
        live = get_object_or_404(ChannelLiveStream.objects.select_related("channel", "content"), id=stream_id)
        if not _user_can_edit_content(request.user, ChannelContent(channel=live.channel)):
            raise PermissionDenied("You cannot start this live stream.")
        # In provider-backed mode the external provider/webhook is the source of truth,
        # but this action is still allowed so Studio can move into the live state once
        # the creator intentionally starts the session. Provider webhooks may update it
        # again when encoder ingest actually connects.
        live.status = ChannelLiveStream.Status.LIVE
        live.started_at = live.started_at or timezone.now()
        live.save(update_fields=["status", "started_at", "updated_at"])
        if live.content_id:
            ChannelContent.objects.filter(id=live.content_id).update(status=ChannelContent.Status.PUBLISHED, visibility=ChannelContent.Visibility.PUBLIC, published_at=timezone.now())
        _channel_audit(request, action="channel_live.start", target_type="channel", target_id=live.channel_id, metadata={"stream_id": str(live.id), "content_id": str(live.content_id or "")})
        _notify_channel_subscribers(
            live.channel,
            notification_type="CHANNEL_LIVE_STARTED",
            title=f"{live.channel.display_name} is live",
            body=live.title,
            target_type="channel_live_stream",
            target_id=live.id,
        )
        return Response(ChannelLiveStreamSerializer(live, context={"request": request}).data)


class ChannelLiveStreamEndView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, stream_id):
        live = get_object_or_404(ChannelLiveStream.objects.select_related("channel", "content"), id=stream_id)
        if not _user_can_edit_content(request.user, ChannelContent(channel=live.channel)):
            raise PermissionDenied("You cannot end this live stream.")
        live.status = ChannelLiveStream.Status.ENDED
        live.ended_at = live.ended_at or timezone.now()
        live.replay_url = str(request.data.get("replay_url") or request.data.get("replayUrl") or live.replay_url or "").strip()
        live.save(update_fields=["status", "ended_at", "replay_url", "updated_at"])

        # Auto-archive live stream as VOD if recording URL is present
        recording_url = (live.metadata or {}).get("recording_url") or ""
        if recording_url and not ChannelContent.objects.filter(
            channel=live.channel, metadata__archived_from_stream=str(live.id)
        ).exists():
            try:
                started = live.started_at
                title = live.title or f"Live Stream — {started.strftime('%b %d, %Y') if started else 'Archived'}"
                ChannelContent.objects.create(
                    channel=live.channel,
                    title=title,
                    description=live.description or "",
                    content_type=ChannelContentType.VIDEO,
                    thumbnail_url=live.thumbnail_url or "",
                    status=ChannelContent.Status.DRAFT,
                    visibility=ChannelContent.Visibility.PUBLIC,
                    duration_seconds=int((live.metadata or {}).get("duration_seconds") or 0) or None,
                    metadata={"archived_from_stream": str(live.id), "recording_url": recording_url},
                )
            except Exception as _vod_err:
                logger.warning("[DVR] Failed to auto-create VOD for stream %s: %s", live.id, _vod_err)

        return Response(ChannelLiveStreamSerializer(live, context={"request": request}).data)


class ChannelLiveStreamWebhookView(APIView):
    permission_classes = [AllowAny]

    def post(self, request, provider):
        from .live_stream_providers import get_live_stream_provider

        provider_name = str(provider).strip().lower()

        # Provider-specific signature verification
        lsp = get_live_stream_provider(provider_name)
        if lsp and hasattr(lsp, "verify_webhook_signature"):
            sig_header = (
                request.headers.get("Mux-Signature")
                or request.headers.get("X-Mux-Signature")
                or ""
            )
            raw_body = request.body if hasattr(request, "body") else b""
            if sig_header and not lsp.verify_webhook_signature(raw_body, sig_header):
                return Response({"detail": "Invalid webhook signature."}, status=status.HTTP_403_FORBIDDEN)
        else:
            # Generic shared-secret fallback
            configured_secret = str(getattr(settings, "LIVE_STREAM_WEBHOOK_SECRET", os.getenv("LIVE_STREAM_WEBHOOK_SECRET", "")) or "")
            supplied = request.headers.get("X-Live-Webhook-Secret") or request.headers.get("X-KIS-Live-Secret") or ""
            if configured_secret and supplied != configured_secret:
                return Response({"detail": "Invalid live webhook signature."}, status=status.HTTP_403_FORBIDDEN)

        payload = request.data if isinstance(request.data, dict) else {}

        # Extract provider_stream_id — handle Mux's event envelope shape
        if lsp and hasattr(lsp, "extract_webhook_stream_id"):
            provider_stream_id = lsp.extract_webhook_stream_id(payload)
        else:
            provider_stream_id = str(payload.get("provider_stream_id") or payload.get("stream_id") or "").strip()

        if not provider_stream_id:
            return Response({"matched": False, "reason": "no_stream_id"}, status=status.HTTP_202_ACCEPTED)

        # Map provider event type to KIS status
        event_type = str(payload.get("type") or "").strip()
        if lsp and event_type and hasattr(lsp, "map_webhook_status"):
            mapped_status = lsp.map_webhook_status(event_type)
        else:
            mapped_status = str(payload.get("status") or "").strip().lower() or None

        live = ChannelLiveStream.objects.filter(provider=provider_name, provider_stream_id=provider_stream_id).first()
        if not live:
            return Response({"matched": False}, status=status.HTTP_202_ACCEPTED)

        if mapped_status and mapped_status in ChannelLiveStream.Status.values:
            live.status = mapped_status
            if mapped_status == "live" and not live.started_at:
                live.started_at = timezone.now()
            elif mapped_status in ("ended", "cancelled") and not live.ended_at:
                live.ended_at = timezone.now()

        # Update viewer count
        viewer_count = live.viewer_count or 0
        if lsp and hasattr(lsp, "extract_viewer_count"):
            vc = lsp.extract_viewer_count(payload)
            if vc is not None:
                viewer_count = vc
        else:
            viewer_count = int(payload.get("viewer_count") or viewer_count)
        live.viewer_count = viewer_count
        live.peak_viewer_count = max(live.peak_viewer_count or 0, viewer_count)

        live.metadata = {
            **(live.metadata or {}),
            "last_webhook": {"provider": provider_name, "event_type": event_type, "status": mapped_status},
        }
        live.save(update_fields=["status", "viewer_count", "peak_viewer_count", "metadata", "started_at", "ended_at", "updated_at"])
        return Response({"matched": True, "id": str(live.id), "status": live.status})


